INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C1','math',6,2,'u1',2,'나누는 수가 분수인 나눗셈의 뜻 — 같은 종류의 양을 얼마씩 몇 번 덜어 낼 수 있는지 묻는 자리임을 알고, (자연수)÷(자연수)·(분수)÷(자연수)를 바탕으로 식을 세우기',ARRAY['6수01-11']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C2','math',6,2,'u1',2,'분모가 같은 (분수)÷(분수) — 두 분수가 같은 단위분수 몇 개인지 세어 분자끼리 나누고, 분모는 답에 남지 않음을 알기',ARRAY['6수01-11']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C3','math',6,2,'u1',3,'분모가 같은 (분수)÷(분수) — 분자끼리 나누어떨어지지 않으면 몫을 분수로 나타내고, 몫의 분수 부분은 남은 양이 아니라 한 몫의 얼마인지를 뜻함을 알기',ARRAY['6수01-11']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C4','math',6,2,'u1',4,'분모가 다른 (분수)÷(분수) — 두 분수를 같은 크기의 조각으로 다시 세는 통분을 한 뒤 분자끼리 나누기',ARRAY['6수01-11']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C5','math',6,2,'u1',5,'(자연수)÷(단위분수) — 단위분수가 1 안에 분모만큼 들어감을 알고 자연수에 분모를 곱해 구하며, 1보다 작은 수로 나누면 몫이 나누어지는 수보다 커짐을 알기',ARRAY['6수01-11']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C6','math',6,2,'u1',6,'(자연수)÷(진분수) — 분자로 나누고 분모를 곱하는 두 걸음을 한 줄로 적어 나누는 분수의 분모와 분자를 바꾸어 곱하기',ARRAY['6수01-11']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C7','math',6,2,'u1',7,'(분수)÷(분수)를 분수의 곱셈으로 — 나누는 분수만 분모와 분자를 바꾸어 곱하고, 나누어지는 분수는 그대로 두어야 함을 알기',ARRAY['6수01-11']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C8','math',6,2,'u1',8,'대분수의 나눗셈 — 대분수를 먼저 가분수로 고친 뒤 통분해 분자끼리 나누거나 곱셈으로 바꾸어 계산하기(두 길의 답은 같다)',ARRAY['6수01-11']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C9','math',6,2,'u1',9,'문제 해결 — 길이 ÷ 타일 한 변으로 가로·세로에 들어가는 개수를 구하고, 가로 수 × 세로 수로 필요한 타일 수를 구하기(조건을 바꾸어도 방법은 같다)',ARRAY['6수01-11']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X01','math',6,'u1',ARRAY['M6-2-u1-C1','M6-2-u1-C6','M6-2-u1-C7']::text[],'나눗셈식을 거꾸로 세운다 — 나누어지는 양과 나누는 양을 바꾸어 (나누는 양)÷(나누어지는 양)으로 쓴다','「무엇을 얼마씩」 — 무엇이 앞, 얼마씩이 뒤') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X02','math',6,'u1',ARRAY['M6-2-u1-C2','M6-2-u1-C3']::text[],'분모가 같은 나눗셈에서 분모를 답에 남기거나 분모끼리도 나눈다(⟨3/4⟩ ÷ ⟨1/4⟩ = ⟨3/4⟩, 분모끼리 4 ÷ 4)','같은 조각이면 개수만 — 분모는 답에 안 남아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X03','math',6,'u1',ARRAY['M6-2-u1-C2','M6-2-u1-C3','M6-2-u1-C5','M6-2-u1-C6']::text[],'나눗셈 대신 분자끼리 빼거나 더한다(연산을 바꾼다)','「몇 번 덜어 낼 수 있나」는 나눗셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X04','math',6,'u1',ARRAY['M6-2-u1-C3']::text[],'몫의 분수 부분을 「남은 양」으로 읽는다(⟨5/6⟩ ÷ ⟨2/6⟩ = 2⟨1/2⟩에서 ⟨1/2⟩이 남았다고 본다)','몫은 컵의 수 — 분수 부분은 컵 하나의 얼마') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X05','math',6,'u1',ARRAY['M6-2-u1-C3','M6-2-u1-C4','M6-2-u1-C7','M6-2-u1-C8']::text[],'나누어떨어지지 않을 때 몫을 거꾸로 적는다(4 ÷ 7을 ⟨7/4⟩로)','나누어지는 수가 분자, 나누는 수가 분모') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X06','math',6,'u1',ARRAY['M6-2-u1-C4']::text[],'분모가 다른데 통분하지 않고 분자끼리 바로 나눈다','조각 크기가 다르면 먼저 같은 조각으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X07','math',6,'u1',ARRAY['M6-2-u1-C4']::text[],'통분을 한쪽만 하거나 분모만 바꾸고 분자를 그대로 둔다','분모를 바꾼 만큼 분자도 같이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X08','math',6,'u1',ARRAY['M6-2-u1-C5']::text[],'(자연수)÷(단위분수)에서 분모로 나누거나 분모만 답으로 쓴다(5 ÷ ⟨1/3⟩ = ⟨5/3⟩)','⟨1/3⟩은 1 안에 3번 — 분모를 곱해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X09','math',6,'u1',ARRAY['M6-2-u1-C5','M6-2-u1-C6']::text[],'「나눗셈을 하면 몫은 늘 작아진다」고 여겨 몫이 커지는 것을 틀렸다고 본다','1보다 작은 수로 나누면 몫이 커져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X10','math',6,'u1',ARRAY['M6-2-u1-C6','M6-2-u1-C7','M6-2-u1-C9']::text[],'나누는 분수를 뒤집지 않고 그대로 곱한다(4 ÷ ⟨2/3⟩ = 4 × ⟨2/3⟩)','나누는 분수의 분모와 분자를 바꾸어 곱해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X11','math',6,'u1',ARRAY['M6-2-u1-C6','M6-2-u1-C9']::text[],'두 걸음의 순서를 거꾸로 한다 — 분모로 나누고 분자를 곱한다','분자로 나누고(÷2) 분모를 곱해요(×3)') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X12','math',6,'u1',ARRAY['M6-2-u1-C7','M6-2-u1-C8']::text[],'두 분수를 다 뒤집거나 앞 분수를 뒤집는다(또는 아무것도 안 뒤집고 곱한다)','뒤집는 것은 나누는 분수 하나뿐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X13','math',6,'u1',ARRAY['M6-2-u1-C8','M6-2-u1-C9']::text[],'대분수를 가분수로 고치지 않고 자연수 부분과 분수 부분을 따로 나누거나 대분수 그대로 뒤집는다','대분수는 먼저 가분수로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X14','math',6,'u1',ARRAY['M6-2-u1-C8']::text[],'대분수를 가분수로 잘못 고친다(자연수와 분자를 더하거나 분모를 곱하지 않는다)','자연수 × 분모 + 분자가 분자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X15','math',6,'u1',ARRAY['M6-2-u1-C3','M6-2-u1-C4','M6-2-u1-C7','M6-2-u1-C8']::text[],'계산 마무리 실수 — 약분하지 않거나 가분수·대분수로 잘못 고친다','몫은 약분해서 대분수로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X16','math',6,'u1',ARRAY['M6-2-u1-C2','M6-2-u1-C4','M6-2-u1-C5','M6-2-u1-C6','M6-2-u1-C7']::text[],'몫을 견줄 때 나누는 수가 클수록 몫도 크다고 여긴다','나누는 수가 작을수록 몫이 커요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X17','math',6,'u1',ARRAY['M6-2-u1-C9']::text[],'가로에 들어가는 수와 세로에 들어가는 수를 더해 전체 타일 수로 본다(곱해야 한다)','가로 줄이 세로 줄 수만큼 늘어선 것 — 곱하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X18','math',6,'u1',ARRAY['M6-2-u1-C1','M6-2-u1-C2','M6-2-u1-C5','M6-2-u1-C9']::text[],'무엇을 묻는지 놓친다 — 개수를 묻는데 양을 쓰거나 나누어지는 양을 그대로 답으로 쓴다','묻는 것이 「몇 개」인지 「얼마」인지 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X19','math',6,'u1',ARRAY['M6-2-u1-C8']::text[],'어떤 수 문제에서 거꾸로 계산을 잘못한다 — 곱한 결과를 다시 곱하거나 결과를 그대로 어떤 수로 본다','곱했으면 거꾸로 나누어 어떤 수를 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X20','math',6,'u1',ARRAY['M6-2-u1-C1','M6-2-u1-C2','M6-2-u1-C3','M6-2-u1-C4','M6-2-u1-C5','M6-2-u1-C6','M6-2-u1-C7','M6-2-u1-C8','M6-2-u1-C9']::text[],'묻는 말을 거꾸로 읽는다 — 옳은↔잘못된, 큰↔작은, 가능↔불가능','물음의 「잘못·가장·없는」에 동그라미 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X21','math',6,'u1',ARRAY['M6-2-u1-C3','M6-2-u1-C6','M6-2-u1-C8']::text[],'몫을 가장 크게 하려면 가장 큰 수를 가장 작은 수로 나누어야 함을 놓친다 — 큰 수끼리 나누거나 작은 수를 큰 수로 나눈다(⟨7/19⟩~⟨11/19⟩ 카드에서 ⟨11/19⟩ ÷ ⟨10/19⟩을 고름)','나누어지는 수는 가장 크게, 나누는 수는 가장 작게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X22','math',6,'u1',ARRAY['M6-2-u1-C5','M6-2-u1-C6','M6-2-u1-C7']::text[],'「1에 해당하는 양」까지 가지 않고 중간 값에서 멈춘다 — ⟨1/3⟩시간 동안의 양이나 통의 ⟨1/4⟩을 채우는 양, 주어진 양을 그대로 답으로 쓴다','이중수직선 아래 줄 1에 맞는 위의 값을 찾을 때까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X23','math',6,'u1',ARRAY['M6-2-u1-C3','M6-2-u1-C4','M6-2-u1-C1']::text[],'「A는 B의 몇 배」를 B ÷ A로 거꾸로 세운다 — 기준이 되는 양(B)을 나누어지는 수로 둔다','「~의」 앞이 기준 — 기준으로 나눠요(자연수로 바꾸어 생각해 보기)') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_basic#1','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C1',1,'mc','auto','엄마가 만든 복숭아잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 들어가는 작은 유리병에 나누어 담으려고 해요. 필요한 유리병의 수를 구하는 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X03']::text[],true,'{"seq":1,"concept":"M6-2-u1-C1","difficulty":1,"kind":"mc","stem":"엄마가 만든 복숭아잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 들어가는 작은 유리병에 나누어 담으려고 해요. 필요한 유리병의 수를 구하는 식은 어느 것인가요?","options":[{"t":"⟨3/5⟩ ÷ ⟨1/5⟩","correct":true},{"t":"⟨1/5⟩ ÷ ⟨3/5⟩","mis":"M6-2-u1-X01"},{"t":"⟨3/5⟩ × ⟨1/5⟩","mis":"M6-2-u1-X03"},{"t":"⟨3/5⟩ − ⟨1/5⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨3/5⟩ kg에서 ⟨1/5⟩ kg씩 몇 번 덜어 낼 수 있는지 묻고 있어요.","같은 양씩 몇 번 덜어 내는지는 나눗셈으로 구해요.","나누어지는 양 ⟨3/5⟩이 앞, 한 병에 담는 ⟨1/5⟩이 뒤 — ⟨3/5⟩ ÷ ⟨1/5⟩이에요."],"asset":{"type":"fbar","bars":[{"den":5,"num":3,"grp":1,"label":"⟨3/5⟩에서 ⟨1/5⟩씩 덜어 내기"}]},"variant_rule":{"alt":[{"stem":"끈 ⟨4/5⟩ m로 마음을 전하는 편지를 꾸며요. 편지 한 장을 꾸미는 데 끈 ⟨1/5⟩ m가 필요해요. 꾸밀 수 있는 편지 수를 구하는 식은 어느 것인가요?","options":[{"t":"⟨4/5⟩ ÷ ⟨1/5⟩","correct":true},{"t":"⟨1/5⟩ ÷ ⟨4/5⟩","mis":"M6-2-u1-X01"},{"t":"⟨4/5⟩ × ⟨1/5⟩","mis":"M6-2-u1-X03"},{"t":"⟨4/5⟩ + ⟨1/5⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨4/5⟩ m에서 ⟨1/5⟩ m씩 덜어 내는 거예요.","몇 번 덜어 낼 수 있는지는 나눗셈이에요.","그래서 식은 ⟨4/5⟩ ÷ ⟨1/5⟩이에요."],"asset":{"type":"fbar","bars":[{"den":5,"num":4,"grp":1,"label":"⟨4/5⟩에서 ⟨1/5⟩씩 덜어 내기"}]}},{"stem":"물 ⟨6/11⟩ L를 한 병에 ⟨2/11⟩ L씩 나누어 담으려고 해요. 필요한 병의 수를 구하는 식은 어느 것인가요?","options":[{"t":"⟨6/11⟩ ÷ ⟨2/11⟩","correct":true},{"t":"⟨2/11⟩ ÷ ⟨6/11⟩","mis":"M6-2-u1-X01"},{"t":"⟨6/11⟩ × ⟨2/11⟩","mis":"M6-2-u1-X03"},{"t":"⟨6/11⟩ − ⟨2/11⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨6/11⟩ L에서 ⟨2/11⟩ L씩 덜어 내요.","같은 양씩 덜어 내는 횟수는 나눗셈이에요.","그래서 식은 ⟨6/11⟩ ÷ ⟨2/11⟩예요."],"asset":{"type":"fbar","bars":[{"den":11,"num":6,"grp":2,"label":"⟨6/11⟩에서 ⟨2/11⟩씩 덜어 내기"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_basic#2','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C1',1,'mc','auto','6학년 1학기에 배운 것이에요. 4 ÷ 5 = 4 × ⟨1/5⟩로 나타내어 계산하면 얼마인가요?',ARRAY['M6-2-u1-X05','M6-2-u1-X18','M6-2-u1-X03']::text[],true,'{"seq":2,"concept":"M6-2-u1-C1","difficulty":1,"kind":"mc","stem":"6학년 1학기에 배운 것이에요. 4 ÷ 5 = 4 × ⟨1/5⟩로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨5/4⟩","mis":"M6-2-u1-X05"},{"t":"⟨1/5⟩","mis":"M6-2-u1-X18"},{"t":"20","mis":"M6-2-u1-X03"}],"explanation":["(자연수)÷(자연수)는 나누는 수를 분모로 하는 단위분수를 곱해요.","4 ÷ 5 = 4 × ⟨1/5⟩ = ⟨4/5⟩.","나누어지는 수 4가 분자, 나누는 수 5가 분모예요."],"variant_rule":{"alt":[{"stem":"6학년 1학기에 배운 것이에요. 7 ÷ 3 = 7 × ⟨1/3⟩로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨2 1/3⟩","correct":true},{"t":"⟨3/7⟩","mis":"M6-2-u1-X05"},{"t":"⟨1/3⟩","mis":"M6-2-u1-X18"},{"t":"21","mis":"M6-2-u1-X03"}],"explanation":["7 ÷ 3 = 7 × ⟨1/3⟩이에요.","7 × ⟨1/3⟩ = ⟨7/3⟩ = ⟨2 1/3⟩.","나누어지는 수 7이 분자 — 가분수는 대분수로 고쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_basic#3','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',1,'mc','auto','편지를 꾸밀 끈 ⟨4/5⟩만큼 색칠했어요. ⟨4/5⟩는 ⟨1/5⟩이 몇 개인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X18','M6-2-u1-X03']::text[],true,'{"seq":3,"concept":"M6-2-u1-C2","difficulty":1,"kind":"mc","stem":"편지를 꾸밀 끈 ⟨4/5⟩만큼 색칠했어요. ⟨4/5⟩는 ⟨1/5⟩이 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"5개","mis":"M6-2-u1-X02"},{"t":"1개","mis":"M6-2-u1-X18"},{"t":"9개","mis":"M6-2-u1-X03"}],"explanation":["⟨4/5⟩는 1을 5칸으로 나눈 것 가운데 4칸이에요.","분모 5는 한 칸의 크기, 분자 4는 칸의 개수예요.","그래서 ⟨4/5⟩는 ⟨1/5⟩이 4개예요."],"asset":{"type":"fbar","bars":[{"den":5,"num":4}]},"variant_rule":{"alt":[{"stem":"⟨3/8⟩은 ⟨1/8⟩이 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"8개","mis":"M6-2-u1-X02"},{"t":"1개","mis":"M6-2-u1-X18"},{"t":"11개","mis":"M6-2-u1-X03"}],"explanation":["⟨3/8⟩은 1을 8칸으로 나눈 것 가운데 3칸이에요.","분자 3이 칸의 개수예요.","그래서 ⟨1/8⟩이 3개예요."],"asset":{"type":"fbar","bars":[{"den":8,"num":3}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_basic#4','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',1,'sa','auto','⟨3/4⟩ ÷ ⟨1/4⟩을 계산해 보세요. 몫을 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u1-C2","difficulty":1,"kind":"sa","stem":"⟨3/4⟩ ÷ ⟨1/4⟩을 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["3"],"explanation":["⟨3/4⟩은 ⟨1/4⟩이 3개, ⟨1/4⟩은 ⟨1/4⟩이 1개예요.","분모가 같으니 분자끼리 나눠요 — 3 ÷ 1 = 3.","분모 4는 조각의 크기라 몫에 남지 않아요."],"asset":{"type":"fbar","bars":[{"den":4,"num":3,"grp":1,"label":"⟨3/4⟩에서 ⟨1/4⟩씩 덜어 내기"}]},"variant_rule":{"alt":[{"stem":"⟨6/7⟩ ÷ ⟨3/7⟩을 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["2"],"explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개, ⟨3/7⟩은 ⟨1/7⟩이 3개예요.","분모가 같으니 분자끼리 나눠요 — 6 ÷ 3 = 2.","분모 7은 조각의 크기라 몫에 남지 않아요."],"asset":{"type":"fbar","bars":[{"den":7,"num":6,"grp":3,"label":"⟨6/7⟩에서 ⟨3/7⟩씩 덜어 내기"}]}},{"stem":"⟨10/11⟩ ÷ ⟨2/11⟩를 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["5"],"explanation":["⟨10/11⟩은 ⟨1/11⟩이 10개, ⟨2/11⟩는 ⟨1/11⟩이 2개예요.","분모가 같으니 분자끼리 나눠요 — 10 ÷ 2 = 5.","분모 11은 조각의 크기라 몫에 남지 않아요."],"asset":{"type":"fbar","bars":[{"den":11,"num":10,"grp":2,"label":"⟨10/11⟩에서 ⟨2/11⟩씩 덜어 내기"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_basic#5','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',2,'sa','auto','끈 ⟨4/5⟩ m에서 편지 한 장에 쓰는 끈 ⟨1/5⟩ m를 몇 번 덜어 낼 수 있는지 세었어요. 꾸밀 수 있는 편지는 몇 장인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u1-C2","difficulty":2,"kind":"sa","stem":"끈 ⟨4/5⟩ m에서 편지 한 장에 쓰는 끈 ⟨1/5⟩ m를 몇 번 덜어 낼 수 있는지 세었어요. 꾸밀 수 있는 편지는 몇 장인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨4/5⟩에서 ⟨1/5⟩을 4번 덜어 낼 수 있어요.","덜어 낸 횟수가 나눗셈의 몫이에요 — ⟨4/5⟩ ÷ ⟨1/5⟩ = 4.","꾸밀 수 있는 편지는 4장이에요."],"asset":{"type":"fbar","bars":[{"den":5,"num":4,"grp":1,"label":"⟨4/5⟩에서 ⟨1/5⟩씩 덜어 내기"}]},"variant_rule":{"alt":[{"stem":"물 ⟨6/11⟩ L를 한 병에 ⟨2/11⟩ L씩 나누어 담으면 몇 병에 담을 수 있나요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨6/11⟩은 ⟨1/11⟩이 6개, ⟨2/11⟩는 ⟨1/11⟩이 2개예요.","⟨6/11⟩ ÷ ⟨2/11⟩ = 6 ÷ 2 = 3.","3병에 나누어 담을 수 있어요."],"asset":{"type":"fbar","bars":[{"den":11,"num":6,"grp":2,"label":"⟨6/11⟩에서 ⟨2/11⟩씩 덜어 내기"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_basic#6','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',2,'mc','auto','구슬 9개를 3개씩 덜어 내는 9 ÷ 3과 ⟨9/10⟩ ÷ ⟨3/10⟩을 그림으로 비교했어요. ⟨9/10⟩ ÷ ⟨3/10⟩과 몫이 같은 자연수의 나눗셈은 어느 것인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X05']::text[],true,'{"seq":6,"concept":"M6-2-u1-C2","difficulty":2,"kind":"mc","stem":"구슬 9개를 3개씩 덜어 내는 9 ÷ 3과 ⟨9/10⟩ ÷ ⟨3/10⟩을 그림으로 비교했어요. ⟨9/10⟩ ÷ ⟨3/10⟩과 몫이 같은 자연수의 나눗셈은 어느 것인가요?","options":[{"t":"9 ÷ 3","correct":true},{"t":"9 ÷ 10","mis":"M6-2-u1-X02"},{"t":"3 ÷ 9","mis":"M6-2-u1-X05"},{"t":"10 ÷ 10","mis":"M6-2-u1-X02"}],"explanation":["⟨9/10⟩는 ⟨1/10⟩이 9개, ⟨3/10⟩은 ⟨1/10⟩이 3개예요.","그래서 ⟨9/10⟩ ÷ ⟨3/10⟩ = 9 ÷ 3 = 3이에요.","구슬 9개를 3개씩 덜어 내는 것과 몫이 같아요."],"asset":{"type":"fbar","bars":[{"den":10,"num":9,"grp":3,"label":"⟨9/10⟩에서 ⟨3/10⟩씩 덜어 내기"}]},"variant_rule":{"alt":[{"stem":"⟨8/11⟩ ÷ ⟨4/11⟩와 관계있는 자연수의 나눗셈은 어느 것인가요?","options":[{"t":"8 ÷ 4","correct":true},{"t":"8 ÷ 11","mis":"M6-2-u1-X02"},{"t":"4 ÷ 8","mis":"M6-2-u1-X05"},{"t":"11 ÷ 11","mis":"M6-2-u1-X02"}],"explanation":["⟨8/11⟩은 ⟨1/11⟩이 8개, ⟨4/11⟩는 ⟨1/11⟩이 4개예요.","⟨8/11⟩ ÷ ⟨4/11⟩ = 8 ÷ 4 = 2.","분자끼리의 나눗셈 8 ÷ 4와 관계있어요."],"asset":{"type":"fbar","bars":[{"den":11,"num":8,"grp":4,"label":"⟨8/11⟩에서 ⟨4/11⟩씩 덜어 내기"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_basic#7','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',2,'ox','auto','친구가 ⟨10/17⟩ ÷ ⟨2/17⟩를 분자끼리 나누고 분모 17을 그대로 두어 ⟨5/17⟩이라고 했어요. 바르게 계산했나요?',ARRAY['M6-2-u1-X02']::text[],true,'{"seq":7,"concept":"M6-2-u1-C2","difficulty":2,"kind":"ox","stem":"친구가 ⟨10/17⟩ ÷ ⟨2/17⟩를 분자끼리 나누고 분모 17을 그대로 두어 ⟨5/17⟩이라고 했어요. 바르게 계산했나요?","answer":"X","reason_options":[{"t":"⟨1/17⟩이 10개를 2개씩 덜어 내는 것이라 몫은 10 ÷ 2 = 5고, 분모는 몫에 남지 않아서","correct":true},{"t":"분자끼리 나누었으니 분모도 그대로 두어야 맞아서","mis":"M6-2-u1-X02"}],"mis":"M6-2-u1-X02","explanation":["⟨10/17⟩은 ⟨1/17⟩이 10개, ⟨2/17⟩는 ⟨1/17⟩이 2개예요.","⟨10/17⟩ ÷ ⟨2/17⟩ = 10 ÷ 2 = 5.","분모 17을 그대로 두면 안 돼요 — 몫은 5예요."],"variant_rule":{"alt":[{"stem":"⟨9/14⟩ ÷ ⟨3/14⟩을 분자끼리 나누고 분모를 그대로 두어 ⟨3/14⟩이라고 계산했어요. 바르게 계산했나요?","answer":"X","reason_options":[{"t":"⟨1/14⟩이 9개를 3개씩 덜어 내는 것이라 몫은 9 ÷ 3 = 3이어서","correct":true},{"t":"분모가 같으면 분모를 그대로 쓰는 것이 맞아서","mis":"M6-2-u1-X02"}],"explanation":["⟨9/14⟩는 ⟨1/14⟩이 9개, ⟨3/14⟩은 ⟨1/14⟩이 3개예요.","⟨9/14⟩ ÷ ⟨3/14⟩ = 9 ÷ 3 = 3.","분모는 몫에 남지 않아요 — 몫은 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_basic#8','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C1',2,'mc','auto','6학년 1학기에 배운 (분수)÷(자연수)예요. ⟨6/7⟩ ÷ 3을 계산하면 얼마인가요?',ARRAY['M6-2-u1-X03','M6-2-u1-X02','M6-2-u1-X05']::text[],true,'{"seq":8,"concept":"M6-2-u1-C1","difficulty":2,"kind":"mc","stem":"6학년 1학기에 배운 (분수)÷(자연수)예요. ⟨6/7⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨2/7⟩","correct":true},{"t":"⟨18/7⟩","mis":"M6-2-u1-X03"},{"t":"2","mis":"M6-2-u1-X02"},{"t":"⟨7/2⟩","mis":"M6-2-u1-X05"}],"explanation":["분자 6을 3으로 나눌 수 있어요 — 6 ÷ 3 = 2.","분모 7은 그대로예요.","그래서 ⟨6/7⟩ ÷ 3 = ⟨2/7⟩예요."],"variant_rule":{"alt":[{"stem":"6학년 1학기에 배운 (분수)÷(자연수)예요. ⟨5/9⟩ ÷ 4를 계산하면 얼마인가요?","options":[{"t":"⟨5/36⟩","correct":true},{"t":"⟨20/9⟩","mis":"M6-2-u1-X03"},{"t":"⟨5/4⟩","mis":"M6-2-u1-X02"},{"t":"⟨36/5⟩","mis":"M6-2-u1-X05"}],"explanation":["분자 5는 4로 나누어떨어지지 않아요.","그래서 곱셈으로 나타내요 — ⟨5/9⟩ ÷ 4 = ⟨5/9⟩ × ⟨1/4⟩ = ⟨5/36⟩.","(분수)÷(자연수)는 자연수를 분모로 하는 단위분수를 곱해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_basic#9','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M6-2-u1-C2","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨3/4⟩ ÷ ⟨1/4⟩","r":"3"},{"l":"⟨6/7⟩ ÷ ⟨3/7⟩","r":"2"},{"l":"⟨10/11⟩ ÷ ⟨2/11⟩","r":"5"}],"mis":"M6-2-u1-X02","explanation":["분모가 같으면 단위분수의 개수끼리 나눠요.","3 ÷ 1 = 3, 6 ÷ 3 = 2, 10 ÷ 2 = 5예요.","분모는 몫에 남지 않아요."],"variant_rule":{"alt":[{"stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨5/8⟩ ÷ ⟨1/8⟩","r":"5"},{"l":"⟨10/11⟩ ÷ ⟨5/11⟩","r":"2"},{"l":"⟨9/14⟩ ÷ ⟨3/14⟩","r":"3"}],"explanation":["분자끼리 나눠요.","5 ÷ 1 = 5, 10 ÷ 5 = 2, 9 ÷ 3 = 3이에요.","분모는 몫에 남지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_basic#10','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',3,'mc','auto','⟨14/15⟩ ÷ ⟨□/15⟩의 몫이 자연수일 때, 5, 6, 7 가운데 □ 안에 들어갈 수 있는 수는 어느 것인가요?',ARRAY['M6-2-u1-X02']::text[],false,'{"seq":10,"concept":"M6-2-u1-C2","difficulty":3,"kind":"mc","stem":"⟨14/15⟩ ÷ ⟨□/15⟩의 몫이 자연수일 때, 5, 6, 7 가운데 □ 안에 들어갈 수 있는 수는 어느 것인가요?","options":[{"t":"7","correct":true},{"t":"5","mis":"M6-2-u1-X02"},{"t":"6","mis":"M6-2-u1-X02"}],"explanation":["분모가 같으니 ⟨14/15⟩ ÷ ⟨□/15⟩ = 14 ÷ □예요.","14 ÷ □가 나누어떨어져야 몫이 자연수예요.","14 ÷ 7 = 2 — □에 들어갈 수는 7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_challenge#1','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',2,'sa','auto','그림처럼 ⟨4/7⟩에서 ⟨2/7⟩씩 덜어 냈어요. ⟨4/7⟩ ÷ ⟨2/7⟩ = 4 ÷ 2의 몫을 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-2-u1-C2","difficulty":2,"kind":"sa","stem":"그림처럼 ⟨4/7⟩에서 ⟨2/7⟩씩 덜어 냈어요. ⟨4/7⟩ ÷ ⟨2/7⟩ = 4 ÷ 2의 몫을 숫자로 쓰세요.","answer":["2"],"explanation":["⟨4/7⟩는 ⟨1/7⟩이 4개, ⟨2/7⟩는 ⟨1/7⟩이 2개예요.","⟨4/7⟩ ÷ ⟨2/7⟩ = 4 ÷ 2 = 2.","⟨2/7⟩씩 2번 덜어 낼 수 있어요."],"asset":{"type":"fbar","bars":[{"den":7,"num":4,"grp":2,"label":"⟨4/7⟩에서 ⟨2/7⟩씩 덜어 내기"}]},"variant_rule":{"alt":[{"stem":"⟨8/9⟩에서 ⟨2/9⟩씩 덜어 냈어요. ⟨8/9⟩ ÷ ⟨2/9⟩의 몫을 숫자로 쓰세요.","answer":["4"],"explanation":["⟨8/9⟩은 ⟨1/9⟩이 8개, ⟨2/9⟩는 ⟨1/9⟩이 2개예요.","⟨8/9⟩ ÷ ⟨2/9⟩ = 8 ÷ 2 = 4.","⟨2/9⟩씩 4번 덜어 낼 수 있어요."],"asset":{"type":"fbar","bars":[{"den":9,"num":8,"grp":2,"label":"⟨8/9⟩에서 ⟨2/9⟩씩 덜어 내기"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_challenge#2','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C1',2,'error','auto','복숭아잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 작은 유리병에 나누어 담는 장면을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u1-X03','M6-2-u1-X20']::text[],false,'{"seq":2,"concept":"M6-2-u1-C1","difficulty":2,"kind":"error","stem":"복숭아잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 작은 유리병에 나누어 담는 장면을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 나누는 수가 분수라서 나눗셈이 아니라 곱셈 ⟨3/5⟩ × ⟨1/5⟩로 구해야 해.","correct":true,"mis_target":"M6-2-u1-X03"},{"t":"도윤 — ⟨3/5⟩은 ⟨1/5⟩이 3개니까 3 ÷ 1처럼 생각하면 돼.","mis":"M6-2-u1-X20"},{"t":"하린 — 작은 유리병 세 개에 나누어 담으면 돼.","mis":"M6-2-u1-X20"}],"explanation":["같은 양씩 몇 번 덜어 낼 수 있는지 묻는 것은 늘 나눗셈이에요.","⟨3/5⟩ ÷ ⟨1/5⟩ = 3 ÷ 1 = 3 — 유리병 3개예요.","수아는 나누는 수가 분수라고 연산을 바꿨어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_challenge#3','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',3,'mc','auto','「몫이 같은 분수의 나눗셈 만들기」 놀이예요. 4 ÷ 2를 보고 분자를 4와 2로 하는 나눗셈을 만들었어요. 4 ÷ 2와 몫이 다른 것은 어느 것인가요?',ARRAY['M6-2-u1-X20']::text[],false,'{"seq":3,"concept":"M6-2-u1-C2","difficulty":3,"kind":"mc","stem":"「몫이 같은 분수의 나눗셈 만들기」 놀이예요. 4 ÷ 2를 보고 분자를 4와 2로 하는 나눗셈을 만들었어요. 4 ÷ 2와 몫이 다른 것은 어느 것인가요?","options":[{"t":"⟨2/5⟩ ÷ ⟨4/5⟩","correct":true},{"t":"⟨4/5⟩ ÷ ⟨2/5⟩","mis":"M6-2-u1-X20"},{"t":"⟨4/7⟩ ÷ ⟨2/7⟩","mis":"M6-2-u1-X20"},{"t":"⟨4/9⟩ ÷ ⟨2/9⟩","mis":"M6-2-u1-X20"}],"explanation":["분모가 같으면 몫은 분자끼리 나눈 값이에요.","⟨4/5⟩ ÷ ⟨2/5⟩, ⟨4/7⟩ ÷ ⟨2/7⟩, ⟨4/9⟩ ÷ ⟨2/9⟩는 모두 4 ÷ 2 = 2예요.","⟨2/5⟩ ÷ ⟨4/5⟩ = 2 ÷ 4 = ⟨1/2⟩로 순서가 거꾸로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_challenge#4','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',3,'mc','auto','⟨4/5⟩에서 ⟨1/5⟩을 몇 번 덜어 낼 수 있는지 세는 것과 같은 계산은 어느 것인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X03','M6-2-u1-X05']::text[],false,'{"seq":4,"concept":"M6-2-u1-C2","difficulty":3,"kind":"mc","stem":"⟨4/5⟩에서 ⟨1/5⟩을 몇 번 덜어 낼 수 있는지 세는 것과 같은 계산은 어느 것인가요?","options":[{"t":"4 ÷ 1","correct":true},{"t":"5 ÷ 1","mis":"M6-2-u1-X02"},{"t":"4 − 1","mis":"M6-2-u1-X03"},{"t":"1 ÷ 4","mis":"M6-2-u1-X05"}],"explanation":["⟨4/5⟩는 ⟨1/5⟩이 4개, ⟨1/5⟩은 ⟨1/5⟩이 1개예요.","그래서 ⟨4/5⟩ ÷ ⟨1/5⟩ = 4 ÷ 1 = 4예요.","분모 5끼리 나누거나 빼는 것이 아니에요."],"asset":{"type":"fbar","bars":[{"den":5,"num":4,"grp":1,"label":"⟨4/5⟩에서 ⟨1/5⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_challenge#5','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',3,'mc','auto','친구가 ⟨10/17⟩ ÷ ⟨2/17⟩를 잘못 계산해 ⟨5/17⟩이라고 썼어요. 바르게 계산한 몫은 얼마인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X05','M6-2-u1-X03']::text[],true,'{"seq":5,"concept":"M6-2-u1-C2","difficulty":3,"kind":"mc","stem":"친구가 ⟨10/17⟩ ÷ ⟨2/17⟩를 잘못 계산해 ⟨5/17⟩이라고 썼어요. 바르게 계산한 몫은 얼마인가요?","options":[{"t":"5","correct":true},{"t":"⟨5/17⟩","mis":"M6-2-u1-X02"},{"t":"⟨1/5⟩","mis":"M6-2-u1-X05"},{"t":"8","mis":"M6-2-u1-X03"}],"explanation":["친구는 분모를 그대로 두고 계산했어요.","⟨10/17⟩ ÷ ⟨2/17⟩ = 10 ÷ 2 = 5.","분모가 같은 나눗셈의 몫에는 분모가 남지 않아요."],"variant_rule":{"alt":[{"stem":"⟨9/14⟩ ÷ ⟨3/14⟩을 바르게 계산한 몫은 얼마인가요?","options":[{"t":"3","correct":true},{"t":"⟨3/14⟩","mis":"M6-2-u1-X02"},{"t":"⟨1/3⟩","mis":"M6-2-u1-X05"},{"t":"6","mis":"M6-2-u1-X03"}],"explanation":["⟨9/14⟩는 ⟨1/14⟩이 9개, ⟨3/14⟩은 ⟨1/14⟩이 3개예요.","⟨9/14⟩ ÷ ⟨3/14⟩ = 9 ÷ 3 = 3.","분모는 몫에 남지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_challenge#6','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',3,'ox','auto','⟨9/10⟩ ÷ ⟨3/10⟩은 구슬 9개를 3개씩 덜어 내는 9 ÷ 3과 몫이 같아요.',ARRAY['M6-2-u1-X02']::text[],false,'{"seq":6,"concept":"M6-2-u1-C2","difficulty":3,"kind":"ox","stem":"⟨9/10⟩ ÷ ⟨3/10⟩은 구슬 9개를 3개씩 덜어 내는 9 ÷ 3과 몫이 같아요.","answer":"O","reason_options":[{"t":"⟨1/10⟩ 9개를 ⟨1/10⟩ 3개씩 덜어 내는 것이라 9 ÷ 3과 같아서","correct":true},{"t":"분수끼리 나누면 몫도 분모가 10인 분수여야 해서","mis":"M6-2-u1-X02"}],"mis":"M6-2-u1-X02","explanation":["⟨9/10⟩는 ⟨1/10⟩이 9개, ⟨3/10⟩은 ⟨1/10⟩이 3개예요.","⟨9/10⟩ ÷ ⟨3/10⟩ = 9 ÷ 3 = 3.","두 나눗셈의 몫은 3으로 같아요."],"asset":{"type":"fbar","bars":[{"den":10,"num":9,"grp":3,"label":"⟨9/10⟩에서 ⟨3/10⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_challenge#7','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C1',3,'mc','auto','끈 ⟨4/5⟩ m로 한 장에 ⟨1/5⟩ m씩 쓰는 편지를 꾸며요. 꾸밀 수 있는 편지 수를 구하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-2-u1-X20']::text[],false,'{"seq":7,"concept":"M6-2-u1-C1","difficulty":3,"kind":"mc","stem":"끈 ⟨4/5⟩ m로 한 장에 ⟨1/5⟩ m씩 쓰는 편지를 꾸며요. 꾸밀 수 있는 편지 수를 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"⟨4/5⟩ − ⟨1/5⟩을 계산한다","correct":true},{"t":"⟨4/5⟩에서 ⟨1/5⟩을 몇 번 덜어 낼 수 있는지 센다","mis":"M6-2-u1-X20"},{"t":"⟨4/5⟩ ÷ ⟨1/5⟩을 계산한다","mis":"M6-2-u1-X20"},{"t":"⟨4/5⟩만큼 색칠하고 ⟨1/5⟩이 몇 개인지 센다","mis":"M6-2-u1-X20"}],"explanation":["편지 수는 ⟨4/5⟩에서 ⟨1/5⟩을 몇 번 덜어 내는지예요.","덜어 내기·나눗셈·단위분수 세기는 모두 같은 생각이에요 — 4장.","뺄셈은 한 번 덜어 내고 남은 끈의 길이일 뿐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_challenge#8','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',4,'mc','auto','분모만 바꾸어 ⟨4/5⟩ ÷ ⟨2/5⟩, ⟨4/7⟩ ÷ ⟨2/7⟩, ⟨4/9⟩ ÷ ⟨2/9⟩를 만들었어요. 세 나눗셈의 몫을 비교한 것으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u1-X16','M6-2-u1-X02']::text[],false,'{"seq":8,"concept":"M6-2-u1-C2","difficulty":4,"kind":"mc","stem":"분모만 바꾸어 ⟨4/5⟩ ÷ ⟨2/5⟩, ⟨4/7⟩ ÷ ⟨2/7⟩, ⟨4/9⟩ ÷ ⟨2/9⟩를 만들었어요. 세 나눗셈의 몫을 비교한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"세 몫은 모두 2로 같다","correct":true},{"t":"분모가 클수록 몫이 크다","mis":"M6-2-u1-X16"},{"t":"분모가 클수록 몫이 작다","mis":"M6-2-u1-X02"},{"t":"몫은 ⟨2/5⟩, ⟨2/7⟩, ⟨2/9⟩이다","mis":"M6-2-u1-X02"}],"explanation":["분모가 같은 나눗셈은 분자끼리 나눠요.","세 나눗셈 모두 4 ÷ 2 = 2예요.","분모가 무엇이든 단위분수의 개수가 같으면 몫이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_challenge#9','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',4,'essay','teacher','⟨9/10⟩ ÷ ⟨3/10⟩ = 3이에요. 몫에 분모 10이 남지 않는 까닭을 ⟨1/10⟩의 개수를 들어 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u1-C2","difficulty":4,"kind":"essay","stem":"⟨9/10⟩ ÷ ⟨3/10⟩ = 3이에요. 몫에 분모 10이 남지 않는 까닭을 ⟨1/10⟩의 개수를 들어 설명해 보세요.","answer_guide":{"answer":"예: ⟨9/10⟩는 ⟨1/10⟩이 9개이고 ⟨3/10⟩은 ⟨1/10⟩이 3개이다. 같은 크기의 조각이니 개수끼리 나누면 되어 9 ÷ 3 = 3이다. 분모 10은 조각의 크기를 나타낼 뿐 덜어 낸 횟수에는 들어가지 않으므로 몫에 남지 않는다.","scoring_points":["두 분수를 ⟨1/10⟩의 개수로 나타냈는가","9 ÷ 3 = 3을 썼는가","분모는 조각의 크기라 몫에 남지 않음을 설명했는가"]},"explanation":["⟨9/10⟩는 ⟨1/10⟩이 9개, ⟨3/10⟩은 ⟨1/10⟩이 3개예요.","조각 크기가 같으니 9 ÷ 3 = 3이에요.","분모는 조각의 크기라 몫에 남지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L02_challenge#10','math',6,2,'u1','L02','tb_g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C1',4,'essay','teacher','만화에서 친구가 복숭아잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 담는 문제를 보고 「3 ÷ 1은 3이잖아.」라고 말했어요. 이 생각이 맞는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u1-C1","difficulty":4,"kind":"essay","stem":"만화에서 친구가 복숭아잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 담는 문제를 보고 「3 ÷ 1은 3이잖아.」라고 말했어요. 이 생각이 맞는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: ⟨3/5⟩은 ⟨1/5⟩이 3개이고 ⟨1/5⟩은 ⟨1/5⟩이 1개이다. 같은 크기의 조각 3개를 1개씩 덜어 내는 것이므로 ⟨3/5⟩ ÷ ⟨1/5⟩ = 3 ÷ 1 = 3이고 작은 유리병 3개가 필요하다.","scoring_points":["⟨3/5⟩을 ⟨1/5⟩ 3개로 나타냈는가","⟨3/5⟩ ÷ ⟨1/5⟩ = 3 ÷ 1 = 3을 썼는가","유리병 3개라고 답했는가"]},"explanation":["⟨3/5⟩은 ⟨1/5⟩이 3개예요.","⟨3/5⟩ ÷ ⟨1/5⟩ = 3 ÷ 1 = 3.","그래서 작은 유리병 3개가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_basic#1','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',1,'mc','auto','⟨4/9⟩와 ⟨7/9⟩은 ⟨1/9⟩이 각각 몇 개인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X05']::text[],false,'{"seq":1,"concept":"M6-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨4/9⟩와 ⟨7/9⟩은 ⟨1/9⟩이 각각 몇 개인가요?","options":[{"t":"4개, 7개","correct":true},{"t":"9개, 9개","mis":"M6-2-u1-X02"},{"t":"7개, 4개","mis":"M6-2-u1-X05"},{"t":"4개, 9개","mis":"M6-2-u1-X02"}],"explanation":["⟨4/9⟩는 ⟨1/9⟩ 조각 4개예요.","⟨7/9⟩은 ⟨1/9⟩ 조각 7개예요.","그래서 ⟨4/9⟩ ÷ ⟨7/9⟩ = 4 ÷ 7로 계산할 수 있어요."],"asset":{"type":"fbar","bars":[{"den":9,"num":4},{"den":9,"num":7}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_basic#2','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',1,'mc','auto','⟨4/9⟩ ÷ ⟨7/9⟩을 계산해 보세요.',ARRAY['M6-2-u1-X02','M6-2-u1-X05','M6-2-u1-X03']::text[],true,'{"seq":2,"concept":"M6-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨4/9⟩ ÷ ⟨7/9⟩을 계산해 보세요.","options":[{"t":"⟨4/7⟩","correct":true},{"t":"⟨4/63⟩","mis":"M6-2-u1-X02"},{"t":"⟨1 3/4⟩","mis":"M6-2-u1-X05"},{"t":"⟨1 2/9⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨4/9⟩는 ⟨1/9⟩이 4개, ⟨7/9⟩은 ⟨1/9⟩이 7개예요.","분모가 같으니 분자끼리 나눠요 — 4 ÷ 7 = ⟨4/7⟩.","분모 9는 조각의 크기라 몫에 남지 않아요."],"variant_rule":{"alt":[{"stem":"⟨3/10⟩ ÷ ⟨7/10⟩을 계산해 보세요.","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨3/70⟩","mis":"M6-2-u1-X02"},{"t":"⟨2 1/3⟩","mis":"M6-2-u1-X05"},{"t":"1","mis":"M6-2-u1-X03"}],"explanation":["⟨3/10⟩은 ⟨1/10⟩이 3개, ⟨7/10⟩은 ⟨1/10⟩이 7개예요.","분모가 같으니 분자끼리 나눠요 — 3 ÷ 7 = ⟨3/7⟩.","분모 10은 조각의 크기라 몫에 남지 않아요."]},{"stem":"⟨4/13⟩ ÷ ⟨11/13⟩을 계산해 보세요.","options":[{"t":"⟨4/11⟩","correct":true},{"t":"⟨4/143⟩","mis":"M6-2-u1-X02"},{"t":"⟨2 3/4⟩","mis":"M6-2-u1-X05"},{"t":"⟨1 2/13⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨4/13⟩는 ⟨1/13⟩이 4개, ⟨11/13⟩은 ⟨1/13⟩이 11개예요.","분모가 같으니 분자끼리 나눠요 — 4 ÷ 11 = ⟨4/11⟩.","분모 13은 조각의 크기라 몫에 남지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_basic#3','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',1,'mc','auto','⟨5/7⟩ ÷ ⟨4/7⟩를 계산해 보세요.',ARRAY['M6-2-u1-X02','M6-2-u1-X05','M6-2-u1-X03']::text[],true,'{"seq":3,"concept":"M6-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨5/7⟩ ÷ ⟨4/7⟩를 계산해 보세요.","options":[{"t":"⟨1 1/4⟩","correct":true},{"t":"⟨5/28⟩","mis":"M6-2-u1-X02"},{"t":"⟨4/5⟩","mis":"M6-2-u1-X05"},{"t":"⟨1/7⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨5/7⟩는 ⟨1/7⟩이 5개, ⟨4/7⟩는 ⟨1/7⟩이 4개예요.","분모가 같으니 분자끼리 나눠요 — 5 ÷ 4 = ⟨5/4⟩ = ⟨1 1/4⟩.","분모 7은 조각의 크기라 몫에 남지 않아요."],"variant_rule":{"alt":[{"stem":"⟨8/11⟩ ÷ ⟨3/11⟩을 계산해 보세요.","options":[{"t":"⟨2 2/3⟩","correct":true},{"t":"⟨8/33⟩","mis":"M6-2-u1-X02"},{"t":"⟨3/8⟩","mis":"M6-2-u1-X05"},{"t":"⟨5/11⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨8/11⟩은 ⟨1/11⟩이 8개, ⟨3/11⟩은 ⟨1/11⟩이 3개예요.","분모가 같으니 분자끼리 나눠요 — 8 ÷ 3 = ⟨8/3⟩ = ⟨2 2/3⟩.","분모 11은 조각의 크기라 몫에 남지 않아요."]},{"stem":"⟨8/11⟩ ÷ ⟨5/11⟩를 계산해 보세요.","options":[{"t":"⟨1 3/5⟩","correct":true},{"t":"⟨8/55⟩","mis":"M6-2-u1-X02"},{"t":"⟨5/8⟩","mis":"M6-2-u1-X05"},{"t":"⟨3/11⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨8/11⟩은 ⟨1/11⟩이 8개, ⟨5/11⟩는 ⟨1/11⟩이 5개예요.","분모가 같으니 분자끼리 나눠요 — 8 ÷ 5 = ⟨8/5⟩ = ⟨1 3/5⟩.","분모 11은 조각의 크기라 몫에 남지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_basic#4','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',1,'mc','auto','먹고 남은 과일 껍질로 만든 친환경 비료 ⟨5/6⟩ L를 ⟨2/6⟩ L짜리 컵에 나누어 채우려고 해요. 채울 수 있는 컵의 수를 구하는 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X03']::text[],true,'{"seq":4,"concept":"M6-2-u1-C3","difficulty":1,"kind":"mc","stem":"먹고 남은 과일 껍질로 만든 친환경 비료 ⟨5/6⟩ L를 ⟨2/6⟩ L짜리 컵에 나누어 채우려고 해요. 채울 수 있는 컵의 수를 구하는 식은 어느 것인가요?","options":[{"t":"⟨5/6⟩ ÷ ⟨2/6⟩","correct":true},{"t":"⟨2/6⟩ ÷ ⟨5/6⟩","mis":"M6-2-u1-X01"},{"t":"⟨5/6⟩ × ⟨2/6⟩","mis":"M6-2-u1-X03"},{"t":"⟨5/6⟩ − ⟨2/6⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨5/6⟩ L에서 ⟨2/6⟩ L씩 몇 번 덜어 내는지 묻고 있어요.","덜어 내는 횟수는 나눗셈이에요.","비료의 양 ⟨5/6⟩가 앞, 컵 하나의 ⟨2/6⟩가 뒤 — ⟨5/6⟩ ÷ ⟨2/6⟩예요."],"asset":{"type":"fbar","bars":[{"den":6,"num":5,"grp":2,"label":"⟨5/6⟩에서 ⟨2/6⟩씩 덜어 내기"}]},"variant_rule":{"alt":[{"stem":"서우는 ⟨7/8⟩ km를 걸었고 지호는 ⟨5/8⟩ km를 걸었어요. 서우가 걸은 거리는 지호가 걸은 거리의 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"⟨7/8⟩ ÷ ⟨5/8⟩","correct":true},{"t":"⟨5/8⟩ ÷ ⟨7/8⟩","mis":"M6-2-u1-X23"},{"t":"⟨7/8⟩ × ⟨5/8⟩","mis":"M6-2-u1-X03"},{"t":"⟨7/8⟩ − ⟨5/8⟩","mis":"M6-2-u1-X03"}],"explanation":["「서우는 지호의 몇 배」에서 기준은 지호예요.","기준인 지호의 거리로 나눠요.","그래서 식은 ⟨7/8⟩ ÷ ⟨5/8⟩예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_basic#5','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',2,'mc','auto','친환경 비료 ⟨5/6⟩ L를 ⟨2/6⟩ L짜리 컵에 나누어 채우면 몇 컵을 채울 수 있나요?',ARRAY['M6-2-u1-X04','M6-2-u1-X05']::text[],false,'{"seq":5,"concept":"M6-2-u1-C3","difficulty":2,"kind":"mc","stem":"친환경 비료 ⟨5/6⟩ L를 ⟨2/6⟩ L짜리 컵에 나누어 채우면 몇 컵을 채울 수 있나요?","options":[{"t":"⟨2 1/2⟩컵","correct":true},{"t":"2컵","mis":"M6-2-u1-X04"},{"t":"⟨2/5⟩컵","mis":"M6-2-u1-X05"},{"t":"⟨2 1/6⟩컵","mis":"M6-2-u1-X04"}],"explanation":["⟨5/6⟩는 ⟨1/6⟩이 5개, ⟨2/6⟩는 ⟨1/6⟩이 2개예요.","⟨5/6⟩ ÷ ⟨2/6⟩ = 5 ÷ 2 = ⟨5/2⟩ = ⟨2 1/2⟩.","2컵을 가득 채우고 한 컵의 ⟨1/2⟩을 더 채워요."],"asset":{"type":"fbar","bars":[{"den":6,"num":5,"grp":2,"label":"⟨5/6⟩에서 ⟨2/6⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_basic#6','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',2,'ox','auto','친환경 비료 ⟨5/6⟩ L를 ⟨2/6⟩ L짜리 컵에 나누면 ⟨2 1/2⟩컵이에요. 여기서 ⟨1/2⟩은 비료가 ⟨1/2⟩ L 남는다는 뜻이에요.',ARRAY['M6-2-u1-X04']::text[],false,'{"seq":6,"concept":"M6-2-u1-C3","difficulty":2,"kind":"ox","stem":"친환경 비료 ⟨5/6⟩ L를 ⟨2/6⟩ L짜리 컵에 나누면 ⟨2 1/2⟩컵이에요. 여기서 ⟨1/2⟩은 비료가 ⟨1/2⟩ L 남는다는 뜻이에요.","answer":"X","reason_options":[{"t":"몫은 컵의 수라서 ⟨1/2⟩은 ⟨2/6⟩ L짜리 컵의 절반을 채운다는 뜻이어서","correct":true},{"t":"두 컵을 채우고 남은 비료가 ⟨1/2⟩ L라서","mis":"M6-2-u1-X04"}],"mis":"M6-2-u1-X04","explanation":["2컵을 채우면 비료 ⟨1/6⟩ L가 남아요.","남은 ⟨1/6⟩ L는 ⟨2/6⟩ L짜리 컵의 절반이에요.","그래서 ⟨1/2⟩은 남은 양이 아니라 컵 하나의 절반이라는 뜻이에요."],"asset":{"type":"fbar","bars":[{"den":6,"num":5,"grp":2,"label":"⟨5/6⟩에서 ⟨2/6⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_basic#7','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',2,'mc','auto','서우는 ⟨7/8⟩ km를 걸었고 지호는 ⟨5/8⟩ km를 걸었어요. 서우가 걸은 거리는 지호가 걸은 거리의 몇 배인가요?',ARRAY['M6-2-u1-X23','M6-2-u1-X03','M6-2-u1-X02']::text[],true,'{"seq":7,"concept":"M6-2-u1-C3","difficulty":2,"kind":"mc","stem":"서우는 ⟨7/8⟩ km를 걸었고 지호는 ⟨5/8⟩ km를 걸었어요. 서우가 걸은 거리는 지호가 걸은 거리의 몇 배인가요?","options":[{"t":"⟨1 2/5⟩배","correct":true},{"t":"⟨5/7⟩배","mis":"M6-2-u1-X23"},{"t":"⟨1/4⟩배","mis":"M6-2-u1-X03"},{"t":"⟨7/40⟩배","mis":"M6-2-u1-X02"}],"explanation":["몇 배인지는 ⟨7/8⟩ ÷ ⟨5/8⟩로 구해요.","⟨7/8⟩ ÷ ⟨5/8⟩ = 7 ÷ 5 = ⟨7/5⟩ = ⟨1 2/5⟩.","서우가 걸은 거리는 지호의 ⟨1 2/5⟩배예요."],"variant_rule":{"alt":[{"stem":"집에서 학교까지는 ⟨12/13⟩ km, 집에서 도서관까지는 ⟨5/13⟩ km예요. 집에서 학교까지의 거리는 집에서 도서관까지의 거리의 몇 배인가요?","options":[{"t":"⟨2 2/5⟩배","correct":true},{"t":"⟨5/12⟩배","mis":"M6-2-u1-X23"},{"t":"⟨7/13⟩배","mis":"M6-2-u1-X03"},{"t":"⟨12/65⟩배","mis":"M6-2-u1-X02"}],"explanation":["몇 배인지는 ⟨12/13⟩ ÷ ⟨5/13⟩로 구해요.","⟨12/13⟩ ÷ ⟨5/13⟩ = 12 ÷ 5 = ⟨12/5⟩ = ⟨2 2/5⟩.","학교까지의 거리는 도서관까지의 ⟨2 2/5⟩배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_basic#8','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M6-2-u1-C3","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨3/10⟩ ÷ ⟨7/10⟩","r":"⟨3/7⟩"},{"l":"⟨4/13⟩ ÷ ⟨11/13⟩","r":"⟨4/11⟩"},{"l":"⟨8/11⟩ ÷ ⟨3/11⟩","r":"⟨2 2/3⟩"}],"mis":"M6-2-u1-X05","explanation":["분자끼리 나누고, 나누어떨어지지 않으면 몫을 분수로 나타내요.","3 ÷ 7 = ⟨3/7⟩, 4 ÷ 11 = ⟨4/11⟩, 8 ÷ 3 = ⟨8/3⟩ = ⟨2 2/3⟩.","나누어지는 수가 분자, 나누는 수가 분모예요."],"variant_rule":{"alt":[{"stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨9/14⟩ ÷ ⟨11/14⟩","r":"⟨9/11⟩"},{"l":"⟨7/16⟩ ÷ ⟨9/16⟩","r":"⟨7/9⟩"},{"l":"⟨17/19⟩ ÷ ⟨7/19⟩","r":"⟨2 3/7⟩"}],"explanation":["분자끼리 나눠요.","9 ÷ 11 = ⟨9/11⟩, 7 ÷ 9 = ⟨7/9⟩, 17 ÷ 7 = ⟨17/7⟩ = ⟨2 3/7⟩.","나누어지는 수가 분자, 나누는 수가 분모예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_basic#9','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',2,'sa','auto','⟨5/7⟩ ÷ ⟨4/7⟩의 몫을 가분수로 나타내면 ⟨□/4⟩예요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-2-u1-C3","difficulty":2,"kind":"sa","stem":"⟨5/7⟩ ÷ ⟨4/7⟩의 몫을 가분수로 나타내면 ⟨□/4⟩예요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["5"],"explanation":["분모가 같으니 ⟨5/7⟩ ÷ ⟨4/7⟩ = 5 ÷ 4예요.","(자연수)÷(자연수)의 몫은 나누어지는 수가 분자 — 5 ÷ 4 = ⟨5/4⟩.","그래서 □는 5예요(대분수로는 ⟨1 1/4⟩)."],"variant_rule":{"alt":[{"stem":"⟨8/11⟩ ÷ ⟨3/11⟩의 몫을 가분수로 나타내면 ⟨□/3⟩이에요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["8"],"explanation":["⟨8/11⟩ ÷ ⟨3/11⟩ = 8 ÷ 3이에요.","8 ÷ 3 = ⟨8/3⟩.","그래서 □는 8이에요(대분수로는 ⟨2 2/3⟩)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_basic#10','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',3,'mc','auto','수 카드 ⟨7/19⟩, ⟨8/19⟩, ⟨9/19⟩, ⟨10/19⟩, ⟨11/19⟩ 가운데 2장을 골라 몫이 가장 큰 나눗셈식을 만들려고 해요. 알맞은 식은 어느 것인가요?',ARRAY['M6-2-u1-X21']::text[],false,'{"seq":10,"concept":"M6-2-u1-C3","difficulty":3,"kind":"mc","stem":"수 카드 ⟨7/19⟩, ⟨8/19⟩, ⟨9/19⟩, ⟨10/19⟩, ⟨11/19⟩ 가운데 2장을 골라 몫이 가장 큰 나눗셈식을 만들려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"⟨11/19⟩ ÷ ⟨7/19⟩","correct":true},{"t":"⟨7/19⟩ ÷ ⟨11/19⟩","mis":"M6-2-u1-X21"},{"t":"⟨11/19⟩ ÷ ⟨10/19⟩","mis":"M6-2-u1-X21"},{"t":"⟨10/19⟩ ÷ ⟨7/19⟩","mis":"M6-2-u1-X21"}],"explanation":["분모가 같으니 몫은 분자끼리 나눈 값이에요.","나누어지는 수는 가장 크게, 나누는 수는 가장 작게 — 11 ÷ 7.","⟨11/19⟩ ÷ ⟨7/19⟩ = 11 ÷ 7 = ⟨11/7⟩ = ⟨1 4/7⟩가 가장 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_challenge#1','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',2,'mc','auto','⟨7/16⟩ ÷ ⟨9/16⟩를 계산해 보세요.',ARRAY['M6-2-u1-X02','M6-2-u1-X05','M6-2-u1-X03']::text[],true,'{"seq":1,"concept":"M6-2-u1-C3","difficulty":2,"kind":"mc","stem":"⟨7/16⟩ ÷ ⟨9/16⟩를 계산해 보세요.","options":[{"t":"⟨7/9⟩","correct":true},{"t":"⟨7/144⟩","mis":"M6-2-u1-X02"},{"t":"⟨1 2/7⟩","mis":"M6-2-u1-X05"},{"t":"1","mis":"M6-2-u1-X03"}],"explanation":["⟨7/16⟩은 ⟨1/16⟩이 7개, ⟨9/16⟩는 ⟨1/16⟩이 9개예요.","분모가 같으니 분자끼리 나눠요 — 7 ÷ 9 = ⟨7/9⟩.","분모 16은 조각의 크기라 몫에 남지 않아요."],"variant_rule":{"alt":[{"stem":"⟨17/19⟩ ÷ ⟨7/19⟩을 계산해 보세요.","options":[{"t":"⟨2 3/7⟩","correct":true},{"t":"⟨17/133⟩","mis":"M6-2-u1-X02"},{"t":"⟨7/17⟩","mis":"M6-2-u1-X05"},{"t":"⟨10/19⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨17/19⟩은 ⟨1/19⟩이 17개, ⟨7/19⟩은 ⟨1/19⟩이 7개예요.","분모가 같으니 분자끼리 나눠요 — 17 ÷ 7 = ⟨17/7⟩ = ⟨2 3/7⟩.","분모 19는 조각의 크기라 몫에 남지 않아요."]},{"stem":"⟨9/14⟩ ÷ ⟨11/14⟩을 계산해 보세요.","options":[{"t":"⟨9/11⟩","correct":true},{"t":"⟨9/154⟩","mis":"M6-2-u1-X02"},{"t":"⟨1 2/9⟩","mis":"M6-2-u1-X05"},{"t":"⟨1 3/7⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨9/14⟩는 ⟨1/14⟩이 9개, ⟨11/14⟩은 ⟨1/14⟩이 11개예요.","분모가 같으니 분자끼리 나눠요 — 9 ÷ 11 = ⟨9/11⟩.","분모 14는 조각의 크기라 몫에 남지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_challenge#2','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',2,'sa','auto','⟨8/11⟩ ÷ ⟨3/11⟩의 몫을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-2-u1-C3","difficulty":2,"kind":"sa","stem":"⟨8/11⟩ ÷ ⟨3/11⟩의 몫을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨8/11⟩ ÷ ⟨3/11⟩ = 8 ÷ 3 = ⟨8/3⟩.","⟨8/3⟩은 ⟨1/3⟩이 8개 — 3개씩 2묶음과 2개예요.","그래서 ⟨8/3⟩ = ⟨2 2/3⟩ — 자연수 부분은 2예요."],"variant_rule":{"alt":[{"stem":"⟨17/19⟩ ÷ ⟨7/19⟩의 몫을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨17/19⟩ ÷ ⟨7/19⟩ = 17 ÷ 7 = ⟨17/7⟩.","⟨17/7⟩은 ⟨1/7⟩이 17개 — 7개씩 2묶음과 3개예요.","그래서 ⟨17/7⟩ = ⟨2 3/7⟩ — 자연수 부분은 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_challenge#3','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',3,'error','auto','⟨5/6⟩ ÷ ⟨2/6⟩ = ⟨2 1/2⟩(친환경 비료 컵)을 두고 친구들이 설명했어요. 잘못 설명한 친구는 누구인가요?',ARRAY['M6-2-u1-X04','M6-2-u1-X20']::text[],false,'{"seq":3,"concept":"M6-2-u1-C3","difficulty":3,"kind":"error","stem":"⟨5/6⟩ ÷ ⟨2/6⟩ = ⟨2 1/2⟩(친환경 비료 컵)을 두고 친구들이 설명했어요. 잘못 설명한 친구는 누구인가요?","options":[{"t":"민준 — ⟨1/2⟩은 비료가 ⟨1/2⟩ L 남았다는 뜻이야.","correct":true,"mis_target":"M6-2-u1-X04"},{"t":"서아 — ⟨2/6⟩ L짜리 컵 2개를 가득 채울 수 있어.","mis":"M6-2-u1-X20"},{"t":"지우 — 몫은 채울 수 있는 컵의 수를 나타내.","mis":"M6-2-u1-X20"}],"explanation":["몫 ⟨2 1/2⟩은 컵 2개와 컵 하나의 ⟨1/2⟩이라는 뜻이에요.","남은 비료는 ⟨1/6⟩ L이고, 이것이 ⟨2/6⟩ L짜리 컵의 절반을 채워요.","민준이는 몫의 분수 부분을 남은 양으로 읽었어요."],"asset":{"type":"fbar","bars":[{"den":6,"num":5,"grp":2,"label":"⟨5/6⟩에서 ⟨2/6⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_challenge#4','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',3,'mc','auto','조건에 맞는 분수의 나눗셈식은 어느 것인가요? — 진분수끼리의 나눗셈 · 두 분수의 분모는 같고 9 이하 · 8 ÷ 5를 이용하여 계산할 수 있음',ARRAY['M6-2-u1-X05','M6-2-u1-X18']::text[],false,'{"seq":4,"concept":"M6-2-u1-C3","difficulty":3,"kind":"mc","stem":"조건에 맞는 분수의 나눗셈식은 어느 것인가요? — 진분수끼리의 나눗셈 · 두 분수의 분모는 같고 9 이하 · 8 ÷ 5를 이용하여 계산할 수 있음","options":[{"t":"⟨8/9⟩ ÷ ⟨5/9⟩","correct":true},{"t":"⟨5/9⟩ ÷ ⟨8/9⟩","mis":"M6-2-u1-X05"},{"t":"⟨8/11⟩ ÷ ⟨5/11⟩","mis":"M6-2-u1-X18"},{"t":"⟨8/9⟩ ÷ ⟨5/8⟩","mis":"M6-2-u1-X18"}],"explanation":["8 ÷ 5를 이용하려면 분자가 8과 5고 분모가 같아야 해요.","진분수이려면 분모가 8보다 커야 하고, 9 이하여야 하니 분모는 9예요.","⟨8/9⟩ ÷ ⟨5/9⟩ = 8 ÷ 5 = ⟨8/5⟩ = ⟨1 3/5⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_challenge#5','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',3,'mc','auto','다음 중 몫이 자연수가 아닌 것은 어느 것인가요?',ARRAY['M6-2-u1-X20']::text[],false,'{"seq":5,"concept":"M6-2-u1-C3","difficulty":3,"kind":"mc","stem":"다음 중 몫이 자연수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨8/11⟩ ÷ ⟨3/11⟩","correct":true},{"t":"⟨6/7⟩ ÷ ⟨2/7⟩","mis":"M6-2-u1-X20"},{"t":"⟨8/11⟩ ÷ ⟨4/11⟩","mis":"M6-2-u1-X20"},{"t":"⟨10/11⟩ ÷ ⟨2/11⟩","mis":"M6-2-u1-X20"}],"explanation":["분모가 같으니 분자끼리 나누어 봐요.","6 ÷ 2 = 3, 8 ÷ 4 = 2, 10 ÷ 2 = 5는 나누어떨어져요.","8 ÷ 3 = ⟨8/3⟩ = ⟨2 2/3⟩는 자연수가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_challenge#6','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',3,'mc','auto','다음 중 몫이 1보다 작은 것은 어느 것인가요?',ARRAY['M6-2-u1-X05']::text[],false,'{"seq":6,"concept":"M6-2-u1-C3","difficulty":3,"kind":"mc","stem":"다음 중 몫이 1보다 작은 것은 어느 것인가요?","options":[{"t":"⟨4/9⟩ ÷ ⟨7/9⟩","correct":true},{"t":"⟨7/8⟩ ÷ ⟨5/8⟩","mis":"M6-2-u1-X05"},{"t":"⟨5/7⟩ ÷ ⟨4/7⟩","mis":"M6-2-u1-X05"},{"t":"⟨8/11⟩ ÷ ⟨3/11⟩","mis":"M6-2-u1-X05"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작아요.","⟨4/9⟩ ÷ ⟨7/9⟩ = 4 ÷ 7 = ⟨4/7⟩.","나머지는 나누어지는 수가 더 커서 몫이 1보다 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_challenge#7','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',3,'mc','auto','친환경 비료 ⟨5/6⟩ L를 ⟨2/6⟩ L짜리 컵에 나누어 채우면 ⟨2 1/2⟩컵이에요. ⟨2 1/2⟩컵이 뜻하는 것으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u1-X04','M6-2-u1-X18']::text[],false,'{"seq":7,"concept":"M6-2-u1-C3","difficulty":3,"kind":"mc","stem":"친환경 비료 ⟨5/6⟩ L를 ⟨2/6⟩ L짜리 컵에 나누어 채우면 ⟨2 1/2⟩컵이에요. ⟨2 1/2⟩컵이 뜻하는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨2/6⟩ L짜리 컵 2개를 가득 채우고 한 컵의 ⟨1/2⟩을 더 채운다","correct":true},{"t":"비료가 ⟨1/2⟩ L 남는다","mis":"M6-2-u1-X04"},{"t":"컵이 ⟨1/2⟩개 모자란다","mis":"M6-2-u1-X04"},{"t":"남는 비료 ⟨1/6⟩ L가 몫이다","mis":"M6-2-u1-X18"}],"explanation":["⟨2/6⟩ L씩 2번 덜어 내면 ⟨1/6⟩ L가 남아요.","남은 ⟨1/6⟩ L는 ⟨2/6⟩ L짜리 컵의 ⟨1/2⟩이에요.","몫은 컵의 수 — 분수 부분은 컵 하나의 얼마인지예요."],"asset":{"type":"fbar","bars":[{"den":6,"num":5,"grp":2,"label":"⟨5/6⟩에서 ⟨2/6⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_challenge#8','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',4,'essay','teacher','⟨5/6⟩ ÷ ⟨2/6⟩ = ⟨2 1/2⟩에서 몫의 ⟨1/2⟩이 「남은 비료 ⟨1/2⟩ L」가 아닌 까닭을 그림이나 식으로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u1-C3","difficulty":4,"kind":"essay","stem":"⟨5/6⟩ ÷ ⟨2/6⟩ = ⟨2 1/2⟩에서 몫의 ⟨1/2⟩이 「남은 비료 ⟨1/2⟩ L」가 아닌 까닭을 그림이나 식으로 설명해 보세요.","answer_guide":{"answer":"예: ⟨5/6⟩에서 ⟨2/6⟩을 2번 덜어 내면 ⟨1/6⟩이 남는다. 남은 ⟨1/6⟩ L는 ⟨2/6⟩ L짜리 컵의 절반을 채운다. 몫은 채울 수 있는 컵의 수이므로 ⟨1/2⟩은 컵 하나의 절반이라는 뜻이고, 남은 비료의 양은 ⟨1/6⟩ L이다.","scoring_points":["남는 비료가 ⟨1/6⟩ L임을 구했는가","⟨1/6⟩ L가 ⟨2/6⟩ L짜리 컵의 절반임을 설명했는가","몫은 컵의 수를 나타냄을 밝혔는가"]},"explanation":["⟨2/6⟩ L씩 2번 덜어 내면 ⟨1/6⟩ L가 남아요.","⟨1/6⟩ L는 ⟨2/6⟩ L짜리 컵의 절반이에요.","몫의 ⟨1/2⟩은 컵 하나의 절반이라는 뜻이에요."],"asset":{"type":"fbar","bars":[{"den":6,"num":5,"grp":2,"label":"⟨5/6⟩에서 ⟨2/6⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_challenge#9','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',4,'essay','teacher','수 카드 ⟨7/19⟩, ⟨8/19⟩, ⟨9/19⟩, ⟨10/19⟩, ⟨11/19⟩ 가운데 2장을 골라 몫이 가장 큰 나눗셈식을 만들고, 그렇게 고른 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u1-C3","difficulty":4,"kind":"essay","stem":"수 카드 ⟨7/19⟩, ⟨8/19⟩, ⟨9/19⟩, ⟨10/19⟩, ⟨11/19⟩ 가운데 2장을 골라 몫이 가장 큰 나눗셈식을 만들고, 그렇게 고른 까닭을 설명해 보세요.","answer_guide":{"answer":"예: ⟨11/19⟩ ÷ ⟨7/19⟩ = 11 ÷ 7 = ⟨11/7⟩ = ⟨1 4/7⟩. 분모가 같으니 몫은 분자끼리 나눈 값인데, 나누어지는 수가 클수록, 나누는 수가 작을수록 몫이 커지므로 가장 큰 ⟨11/19⟩을 가장 작은 ⟨7/19⟩로 나눈다.","scoring_points":["⟨11/19⟩ ÷ ⟨7/19⟩을 만들었는가","몫 ⟨1 4/7⟩를 바르게 구했는가","가장 큰 수를 가장 작은 수로 나누는 까닭을 설명했는가"]},"explanation":["분모가 같으니 몫은 분자끼리 나눈 값이에요.","나누어지는 수는 크게, 나누는 수는 작게 해야 몫이 커요.","⟨11/19⟩ ÷ ⟨7/19⟩ = ⟨1 4/7⟩가 가장 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L03_challenge#10','math',6,2,'u1','L03','tb_g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',4,'mc','auto','⟨3/13⟩, ⟨10/13⟩, ⟨7/13⟩ 가운데 가장 큰 분수를 가장 작은 분수로 나눈 몫은 얼마인가요?',ARRAY['M6-2-u1-X21']::text[],false,'{"seq":10,"concept":"M6-2-u1-C3","difficulty":4,"kind":"mc","stem":"⟨3/13⟩, ⟨10/13⟩, ⟨7/13⟩ 가운데 가장 큰 분수를 가장 작은 분수로 나눈 몫은 얼마인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨3/10⟩","mis":"M6-2-u1-X21"},{"t":"⟨1 3/7⟩","mis":"M6-2-u1-X21"},{"t":"⟨2 1/3⟩","mis":"M6-2-u1-X21"}],"explanation":["가장 큰 분수는 ⟨10/13⟩, 가장 작은 분수는 ⟨3/13⟩이에요.","⟨10/13⟩ ÷ ⟨3/13⟩ = 10 ÷ 3 = ⟨10/3⟩ = ⟨3 1/3⟩.","작은 수를 큰 수로 나누거나 다른 두 수를 고르면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_basic#1','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',1,'mc','auto','학교 텃밭에서 자란 대파 길이는 ⟨3/4⟩ m이고, 부추 길이는 ⟨3/8⟩ m예요. 대파 길이는 부추 길이의 몇 배인지 구하는 식은 어느 것인가요?',ARRAY['M6-2-u1-X23','M6-2-u1-X03']::text[],false,'{"seq":1,"concept":"M6-2-u1-C4","difficulty":1,"kind":"mc","stem":"학교 텃밭에서 자란 대파 길이는 ⟨3/4⟩ m이고, 부추 길이는 ⟨3/8⟩ m예요. 대파 길이는 부추 길이의 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"⟨3/4⟩ ÷ ⟨3/8⟩","correct":true},{"t":"⟨3/8⟩ ÷ ⟨3/4⟩","mis":"M6-2-u1-X23"},{"t":"⟨3/4⟩ × ⟨3/8⟩","mis":"M6-2-u1-X03"},{"t":"⟨3/4⟩ − ⟨3/8⟩","mis":"M6-2-u1-X03"}],"explanation":["「대파 길이는 부추 길이의 몇 배」에서 기준은 부추예요.","기준인 부추 길이로 나눠요.","그래서 식은 ⟨3/4⟩ ÷ ⟨3/8⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_basic#2','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',1,'mc','auto','⟨3/4⟩ ÷ ⟨2/5⟩를 통분하여 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u1-X07']::text[],true,'{"seq":2,"concept":"M6-2-u1-C4","difficulty":1,"kind":"mc","stem":"⟨3/4⟩ ÷ ⟨2/5⟩를 통분하여 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨15/20⟩ ÷ ⟨8/20⟩","correct":true},{"t":"⟨3/20⟩ ÷ ⟨2/20⟩","mis":"M6-2-u1-X07"},{"t":"⟨15/20⟩ ÷ ⟨2/20⟩","mis":"M6-2-u1-X07"},{"t":"⟨3/4⟩ ÷ ⟨2/4⟩","mis":"M6-2-u1-X07"}],"explanation":["4와 5의 공배수 20을 공통분모로 해요.","⟨3/4⟩ = ⟨15/20⟩, ⟨2/5⟩ = ⟨8/20⟩이에요.","분모를 바꾼 만큼 분자도 함께 바꿔야 해요."],"variant_rule":{"alt":[{"stem":"⟨2/7⟩ ÷ ⟨9/10⟩를 통분하여 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨20/70⟩ ÷ ⟨63/70⟩","correct":true},{"t":"⟨2/70⟩ ÷ ⟨9/70⟩","mis":"M6-2-u1-X07"},{"t":"⟨20/70⟩ ÷ ⟨9/70⟩","mis":"M6-2-u1-X07"},{"t":"⟨2/7⟩ ÷ ⟨9/7⟩","mis":"M6-2-u1-X07"}],"explanation":["7과 10의 공배수 70을 공통분모로 해요.","⟨2/7⟩ = ⟨20/70⟩, ⟨9/10⟩ = ⟨63/70⟩이에요.","분모를 바꾼 만큼 분자도 함께 바꿔야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_basic#3','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',1,'mc','auto','⟨3/4⟩ ÷ ⟨2/5⟩를 계산해 보세요.',ARRAY['M6-2-u1-X06','M6-2-u1-X10','M6-2-u1-X05']::text[],true,'{"seq":3,"concept":"M6-2-u1-C4","difficulty":1,"kind":"mc","stem":"⟨3/4⟩ ÷ ⟨2/5⟩를 계산해 보세요.","options":[{"t":"⟨1 7/8⟩","correct":true},{"t":"⟨1 1/2⟩","mis":"M6-2-u1-X06"},{"t":"⟨3/10⟩","mis":"M6-2-u1-X10"},{"t":"⟨8/15⟩","mis":"M6-2-u1-X05"}],"explanation":["분모가 다르니 먼저 통분해요 — ⟨3/4⟩ ÷ ⟨2/5⟩ = ⟨15/20⟩ ÷ ⟨8/20⟩.","분모가 같아졌으니 분자끼리 나눠요 — 15 ÷ 8 = ⟨15/8⟩ = ⟨1 7/8⟩.","조각의 크기를 같게 맞춘 뒤 개수끼리 나눈 거예요."],"variant_rule":{"alt":[{"stem":"⟨3/7⟩ ÷ ⟨5/8⟩를 계산해 보세요.","options":[{"t":"⟨24/35⟩","correct":true},{"t":"⟨3/5⟩","mis":"M6-2-u1-X06"},{"t":"⟨15/56⟩","mis":"M6-2-u1-X10"},{"t":"⟨1 11/24⟩","mis":"M6-2-u1-X05"}],"explanation":["분모가 다르니 먼저 통분해요 — ⟨3/7⟩ ÷ ⟨5/8⟩ = ⟨24/56⟩ ÷ ⟨35/56⟩.","분모가 같아졌으니 분자끼리 나눠요 — 24 ÷ 35 = ⟨24/35⟩.","조각의 크기를 같게 맞춘 뒤 개수끼리 나눈 거예요."]},{"stem":"⟨1/3⟩ ÷ ⟨5/6⟩를 계산해 보세요.","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨1/5⟩","mis":"M6-2-u1-X06"},{"t":"⟨5/18⟩","mis":"M6-2-u1-X10"},{"t":"⟨2 1/2⟩","mis":"M6-2-u1-X05"}],"explanation":["분모가 다르니 먼저 통분해요 — ⟨1/3⟩ ÷ ⟨5/6⟩ = ⟨2/6⟩ ÷ ⟨5/6⟩.","분모가 같아졌으니 분자끼리 나눠요 — 2 ÷ 5 = ⟨2/5⟩.","조각의 크기를 같게 맞춘 뒤 개수끼리 나눈 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_basic#4','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',1,'sa','auto','그림처럼 ⟨3/4⟩을 ⟨6/8⟩으로 나타냈어요. 대파 ⟨3/4⟩ m는 부추 ⟨3/8⟩ m의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u1-C4","difficulty":1,"kind":"sa","stem":"그림처럼 ⟨3/4⟩을 ⟨6/8⟩으로 나타냈어요. 대파 ⟨3/4⟩ m는 부추 ⟨3/8⟩ m의 몇 배인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨3/4⟩ = ⟨6/8⟩이에요.","⟨3/4⟩ ÷ ⟨3/8⟩ = ⟨6/8⟩ ÷ ⟨3/8⟩ = 6 ÷ 3 = 2.","대파 길이는 부추 길이의 2배예요."],"asset":{"type":"fbar","bars":[{"den":8,"num":6,"label":"⟨3/4⟩ = ⟨6/8⟩"},{"den":8,"num":3,"label":"⟨3/8⟩"}]},"variant_rule":{"alt":[{"stem":"⟨7/9⟩ ÷ ⟨7/18⟩의 몫을 숫자로 쓰세요.","answer":["2"],"explanation":["⟨7/9⟩ = ⟨14/18⟩예요.","⟨7/9⟩ ÷ ⟨7/18⟩ = ⟨14/18⟩ ÷ ⟨7/18⟩ = 14 ÷ 7 = 2.","몫은 2예요."],"asset":{"type":"fbar","bars":[{"den":18,"num":14,"label":"⟨7/9⟩ = ⟨14/18⟩"},{"den":18,"num":7,"label":"⟨7/18⟩"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_basic#5','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',2,'mc','auto','⟨3/4⟩ ÷ ⟨2/5⟩를 계산할 때 먼저 통분하는 까닭은 무엇인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X02']::text[],false,'{"seq":5,"concept":"M6-2-u1-C4","difficulty":2,"kind":"mc","stem":"⟨3/4⟩ ÷ ⟨2/5⟩를 계산할 때 먼저 통분하는 까닭은 무엇인가요?","options":[{"t":"분모가 다르면 조각의 크기가 달라 개수끼리 나눌 수 없어서","correct":true},{"t":"통분하면 분자가 커져 계산이 쉬워져서","mis":"M6-2-u1-X06"},{"t":"나누는 수를 자연수로 만들기 위해서","mis":"M6-2-u1-X06"},{"t":"분모끼리 나누어야 해서","mis":"M6-2-u1-X02"}],"explanation":["⟨3/4⟩과 ⟨2/5⟩는 크기가 다른 조각을 센 수예요.","조각 크기가 다르면 개수끼리 나눌 수 없어요.","통분하면 분모가 같은 나눗셈이 되어 분자끼리 나눌 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_basic#6','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',2,'ox','auto','친구가 ⟨8/9⟩ ÷ ⟨5/8⟩를 ⟨8/72⟩ ÷ ⟨5/72⟩로 고쳐 8 ÷ 5 = ⟨1 3/5⟩이라고 계산했어요. 바르게 계산했나요?',ARRAY['M6-2-u1-X07']::text[],false,'{"seq":6,"concept":"M6-2-u1-C4","difficulty":2,"kind":"ox","stem":"친구가 ⟨8/9⟩ ÷ ⟨5/8⟩를 ⟨8/72⟩ ÷ ⟨5/72⟩로 고쳐 8 ÷ 5 = ⟨1 3/5⟩이라고 계산했어요. 바르게 계산했나요?","answer":"X","reason_options":[{"t":"분모를 72로 바꾸면 분자도 64와 45로 바꾸어야 해서","correct":true},{"t":"분모를 같게 했으니 분자끼리 나누면 맞아서","mis":"M6-2-u1-X07"}],"mis":"M6-2-u1-X07","explanation":["⟨8/9⟩ = ⟨64/72⟩, ⟨5/8⟩ = ⟨45/72⟩예요.","⟨8/9⟩ ÷ ⟨5/8⟩ = ⟨64/72⟩ ÷ ⟨45/72⟩ = 64 ÷ 45 = ⟨64/45⟩ = ⟨1 19/45⟩.","분모만 바꾸고 분자를 그대로 두면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_basic#7','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',2,'mc','auto','은수는 시장에서 돼지고기를 ⟨3/5⟩ kg, 닭고기를 ⟨2/9⟩ kg 샀어요. 은수가 산 돼지고기 양은 닭고기 양의 몇 배인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X23','M6-2-u1-X10']::text[],true,'{"seq":7,"concept":"M6-2-u1-C4","difficulty":2,"kind":"mc","stem":"은수는 시장에서 돼지고기를 ⟨3/5⟩ kg, 닭고기를 ⟨2/9⟩ kg 샀어요. 은수가 산 돼지고기 양은 닭고기 양의 몇 배인가요?","options":[{"t":"⟨2 7/10⟩배","correct":true},{"t":"⟨1 1/2⟩배","mis":"M6-2-u1-X06"},{"t":"⟨10/27⟩배","mis":"M6-2-u1-X23"},{"t":"⟨2/15⟩배","mis":"M6-2-u1-X10"}],"explanation":["몇 배인지는 ⟨3/5⟩ ÷ ⟨2/9⟩로 구해요.","⟨3/5⟩ ÷ ⟨2/9⟩ = ⟨27/45⟩ ÷ ⟨10/45⟩ = 27 ÷ 10 = ⟨27/10⟩ = ⟨2 7/10⟩.","돼지고기는 닭고기의 ⟨2 7/10⟩배예요."],"variant_rule":{"alt":[{"stem":"종이 팩을 선우는 ⟨7/9⟩ kg, 연우는 ⟨7/12⟩ kg 모았어요. 선우가 모은 종이 팩 무게는 연우가 모은 종이 팩 무게의 몇 배인가요?","options":[{"t":"⟨1 1/3⟩배","correct":true},{"t":"1배","mis":"M6-2-u1-X06"},{"t":"⟨3/4⟩배","mis":"M6-2-u1-X23"},{"t":"⟨49/108⟩배","mis":"M6-2-u1-X10"}],"explanation":["몇 배인지는 ⟨7/9⟩ ÷ ⟨7/12⟩로 구해요.","⟨7/9⟩ ÷ ⟨7/12⟩ = ⟨28/36⟩ ÷ ⟨21/36⟩ = 28 ÷ 21 = ⟨28/21⟩ = ⟨1 1/3⟩.","선우가 모은 무게는 연우의 ⟨1 1/3⟩배예요."]},{"stem":"준기의 필통 무게는 ⟨5/6⟩ kg, 지수의 필통 무게는 ⟨3/4⟩ kg이에요. 준기의 필통 무게는 지수의 필통 무게의 몇 배인가요?","options":[{"t":"⟨1 1/9⟩배","correct":true},{"t":"⟨1 2/3⟩배","mis":"M6-2-u1-X06"},{"t":"⟨9/10⟩배","mis":"M6-2-u1-X23"},{"t":"⟨5/8⟩배","mis":"M6-2-u1-X10"}],"explanation":["몇 배인지는 ⟨5/6⟩ ÷ ⟨3/4⟩으로 구해요.","⟨5/6⟩ ÷ ⟨3/4⟩ = ⟨10/12⟩ ÷ ⟨9/12⟩ = 10 ÷ 9 = ⟨10/9⟩ = ⟨1 1/9⟩.","준기의 필통은 지수의 ⟨1 1/9⟩배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_basic#8','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',2,'match','auto','나눗셈식과 통분한 식을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u1-C4","difficulty":2,"kind":"match","stem":"나눗셈식과 통분한 식을 알맞게 이으세요.","pairs":[{"l":"⟨2/5⟩ ÷ ⟨2/15⟩","r":"⟨6/15⟩ ÷ ⟨2/15⟩"},{"l":"⟨1/3⟩ ÷ ⟨5/6⟩","r":"⟨2/6⟩ ÷ ⟨5/6⟩"},{"l":"⟨3/7⟩ ÷ ⟨5/8⟩","r":"⟨24/56⟩ ÷ ⟨35/56⟩"}],"mis":"M6-2-u1-X07","explanation":["두 분모의 공배수를 공통분모로 해요.","5와 15는 15, 3과 6은 6, 7과 8은 56이에요.","분모를 바꾼 만큼 분자도 함께 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_basic#9','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',2,'sa','auto','⟨2/5⟩ ÷ ⟨2/15⟩를 계산해 보세요. 몫을 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-2-u1-C4","difficulty":2,"kind":"sa","stem":"⟨2/5⟩ ÷ ⟨2/15⟩를 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["3"],"explanation":["분모가 다르니 먼저 통분해요 — ⟨2/5⟩ ÷ ⟨2/15⟩ = ⟨6/15⟩ ÷ ⟨2/15⟩.","분모가 같아졌으니 분자끼리 나눠요 — 6 ÷ 2 = 3.","조각의 크기를 같게 맞춘 뒤 개수끼리 나눈 거예요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩ ÷ ⟨3/16⟩을 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["4"],"explanation":["분모가 다르니 먼저 통분해요 — ⟨3/4⟩ ÷ ⟨3/16⟩ = ⟨12/16⟩ ÷ ⟨3/16⟩.","분모가 같아졌으니 분자끼리 나눠요 — 12 ÷ 3 = 4.","조각의 크기를 같게 맞춘 뒤 개수끼리 나눈 거예요."]},{"stem":"⟨5/9⟩ ÷ ⟨5/18⟩를 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["2"],"explanation":["분모가 다르니 먼저 통분해요 — ⟨5/9⟩ ÷ ⟨5/18⟩ = ⟨10/18⟩ ÷ ⟨5/18⟩.","분모가 같아졌으니 분자끼리 나눠요 — 10 ÷ 5 = 2.","조각의 크기를 같게 맞춘 뒤 개수끼리 나눈 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_basic#10','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',3,'mc','auto','⟨7/11⟩ ÷ ⟨9/11⟩는 7 ÷ 9로 계산할 수 있어요. 같은 생각으로 ⟨3/4⟩ ÷ ⟨2/5⟩는 어떤 자연수의 나눗셈으로 계산할 수 있나요?',ARRAY['M6-2-u1-X06','M6-2-u1-X02','M6-2-u1-X05']::text[],false,'{"seq":10,"concept":"M6-2-u1-C4","difficulty":3,"kind":"mc","stem":"⟨7/11⟩ ÷ ⟨9/11⟩는 7 ÷ 9로 계산할 수 있어요. 같은 생각으로 ⟨3/4⟩ ÷ ⟨2/5⟩는 어떤 자연수의 나눗셈으로 계산할 수 있나요?","options":[{"t":"15 ÷ 8","correct":true},{"t":"3 ÷ 2","mis":"M6-2-u1-X06"},{"t":"4 ÷ 5","mis":"M6-2-u1-X02"},{"t":"8 ÷ 15","mis":"M6-2-u1-X05"}],"explanation":["분모가 같으면 분자끼리 나눌 수 있어요.","통분하면 ⟨3/4⟩ ÷ ⟨2/5⟩ = ⟨15/20⟩ ÷ ⟨8/20⟩이에요.","그래서 15 ÷ 8로 계산해요 — 몫은 ⟨1 7/8⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_challenge#1','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',2,'mc','auto','⟨2/7⟩ ÷ ⟨9/10⟩를 계산해 보세요.',ARRAY['M6-2-u1-X06','M6-2-u1-X10','M6-2-u1-X05']::text[],true,'{"seq":1,"concept":"M6-2-u1-C4","difficulty":2,"kind":"mc","stem":"⟨2/7⟩ ÷ ⟨9/10⟩를 계산해 보세요.","options":[{"t":"⟨20/63⟩","correct":true},{"t":"⟨2/9⟩","mis":"M6-2-u1-X06"},{"t":"⟨9/35⟩","mis":"M6-2-u1-X10"},{"t":"⟨3 3/20⟩","mis":"M6-2-u1-X05"}],"explanation":["분모가 다르니 먼저 통분해요 — ⟨2/7⟩ ÷ ⟨9/10⟩ = ⟨20/70⟩ ÷ ⟨63/70⟩.","분모가 같아졌으니 분자끼리 나눠요 — 20 ÷ 63 = ⟨20/63⟩.","조각의 크기를 같게 맞춘 뒤 개수끼리 나눈 거예요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ ÷ ⟨4/7⟩를 계산해 보세요.","options":[{"t":"⟨1 11/24⟩","correct":true},{"t":"⟨1 1/4⟩","mis":"M6-2-u1-X06"},{"t":"⟨10/21⟩","mis":"M6-2-u1-X10"},{"t":"⟨24/35⟩","mis":"M6-2-u1-X05"}],"explanation":["분모가 다르니 먼저 통분해요 — ⟨5/6⟩ ÷ ⟨4/7⟩ = ⟨35/42⟩ ÷ ⟨24/42⟩.","분모가 같아졌으니 분자끼리 나눠요 — 35 ÷ 24 = ⟨35/24⟩ = ⟨1 11/24⟩.","조각의 크기를 같게 맞춘 뒤 개수끼리 나눈 거예요."]},{"stem":"⟨5/6⟩ ÷ ⟨3/8⟩을 계산해 보세요.","options":[{"t":"⟨2 2/9⟩","correct":true},{"t":"⟨1 2/3⟩","mis":"M6-2-u1-X06"},{"t":"⟨5/16⟩","mis":"M6-2-u1-X10"},{"t":"⟨9/20⟩","mis":"M6-2-u1-X05"}],"explanation":["분모가 다르니 먼저 통분해요 — ⟨5/6⟩ ÷ ⟨3/8⟩ = ⟨20/24⟩ ÷ ⟨9/24⟩.","분모가 같아졌으니 분자끼리 나눠요 — 20 ÷ 9 = ⟨20/9⟩ = ⟨2 2/9⟩.","조각의 크기를 같게 맞춘 뒤 개수끼리 나눈 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_challenge#2','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',2,'sa','auto','⟨5/8⟩ ÷ ⟨3/16⟩ = ⟨□/16⟩ ÷ ⟨3/16⟩이에요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-2-u1-C4","difficulty":2,"kind":"sa","stem":"⟨5/8⟩ ÷ ⟨3/16⟩ = ⟨□/16⟩ ÷ ⟨3/16⟩이에요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["10"],"explanation":["8과 16의 공배수 16을 공통분모로 해요.","⟨5/8⟩ = ⟨10/16⟩이에요.","그래서 □는 10이고, 몫은 10 ÷ 3 = ⟨10/3⟩ = ⟨3 1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ ÷ ⟨4/7⟩ = ⟨□/42⟩ ÷ ⟨24/42⟩예요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["35"],"explanation":["6과 7의 공배수 42를 공통분모로 해요.","⟨5/6⟩ = ⟨35/42⟩예요.","그래서 □는 35고, 몫은 35 ÷ 24 = ⟨35/24⟩ = ⟨1 11/24⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_challenge#3','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',3,'error','auto','⟨8/9⟩ ÷ ⟨5/8⟩를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u1-X07','M6-2-u1-X20']::text[],false,'{"seq":3,"concept":"M6-2-u1-C4","difficulty":3,"kind":"error","stem":"⟨8/9⟩ ÷ ⟨5/8⟩를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"현우 — 공통분모 72로 ⟨8/72⟩ ÷ ⟨5/72⟩로 고치면 돼.","correct":true,"mis_target":"M6-2-u1-X07"},{"t":"나래 — ⟨64/72⟩ ÷ ⟨45/72⟩로 통분하면 64 ÷ 45야.","mis":"M6-2-u1-X20"},{"t":"준서 — 분모가 다르니까 먼저 통분해야 해.","mis":"M6-2-u1-X20"}],"explanation":["⟨8/9⟩ = ⟨64/72⟩, ⟨5/8⟩ = ⟨45/72⟩예요.","⟨8/9⟩ ÷ ⟨5/8⟩ = 64 ÷ 45 = ⟨1 19/45⟩.","현우는 분모만 바꾸고 분자는 그대로 두었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_challenge#4','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',3,'mc','auto','「몫이 큰 순서대로 배치하기」 놀이예요. ⟨3/4⟩ ÷ ⟨2/5⟩, ⟨1/3⟩ ÷ ⟨5/6⟩, ⟨2/5⟩ ÷ ⟨2/15⟩를 몫이 큰 순서대로 놓은 것은 어느 것인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X20']::text[],false,'{"seq":4,"concept":"M6-2-u1-C4","difficulty":3,"kind":"mc","stem":"「몫이 큰 순서대로 배치하기」 놀이예요. ⟨3/4⟩ ÷ ⟨2/5⟩, ⟨1/3⟩ ÷ ⟨5/6⟩, ⟨2/5⟩ ÷ ⟨2/15⟩를 몫이 큰 순서대로 놓은 것은 어느 것인가요?","options":[{"t":"⟨2/5⟩ ÷ ⟨2/15⟩, ⟨3/4⟩ ÷ ⟨2/5⟩, ⟨1/3⟩ ÷ ⟨5/6⟩","correct":true},{"t":"⟨3/4⟩ ÷ ⟨2/5⟩, ⟨2/5⟩ ÷ ⟨2/15⟩, ⟨1/3⟩ ÷ ⟨5/6⟩","mis":"M6-2-u1-X06"},{"t":"⟨1/3⟩ ÷ ⟨5/6⟩, ⟨3/4⟩ ÷ ⟨2/5⟩, ⟨2/5⟩ ÷ ⟨2/15⟩","mis":"M6-2-u1-X20"},{"t":"⟨2/5⟩ ÷ ⟨2/15⟩, ⟨1/3⟩ ÷ ⟨5/6⟩, ⟨3/4⟩ ÷ ⟨2/5⟩","mis":"M6-2-u1-X06"}],"explanation":["통분하여 몫을 구해요 — ⟨2/5⟩ ÷ ⟨2/15⟩ = 6 ÷ 2 = 3.","⟨3/4⟩ ÷ ⟨2/5⟩ = 15 ÷ 8 = ⟨1 7/8⟩, ⟨1/3⟩ ÷ ⟨5/6⟩ = 2 ÷ 5 = ⟨2/5⟩.","3 > ⟨1 7/8⟩ > ⟨2/5⟩ 순서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_challenge#5','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',3,'mc','auto','친구가 ⟨3/4⟩ ÷ ⟨3/16⟩을 분자끼리 바로 나누어 3 ÷ 3 = 1이라고 계산했어요. 바르게 계산한 몫은 얼마인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X05','M6-2-u1-X03']::text[],false,'{"seq":5,"concept":"M6-2-u1-C4","difficulty":3,"kind":"mc","stem":"친구가 ⟨3/4⟩ ÷ ⟨3/16⟩을 분자끼리 바로 나누어 3 ÷ 3 = 1이라고 계산했어요. 바르게 계산한 몫은 얼마인가요?","options":[{"t":"4","correct":true},{"t":"1","mis":"M6-2-u1-X06"},{"t":"⟨1/4⟩","mis":"M6-2-u1-X05"},{"t":"⟨9/64⟩","mis":"M6-2-u1-X03"}],"explanation":["분모가 다르면 먼저 통분해야 해요.","⟨3/4⟩ ÷ ⟨3/16⟩ = ⟨12/16⟩ ÷ ⟨3/16⟩ = 12 ÷ 3 = 4.","통분하지 않고 분자끼리 나누면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_challenge#6','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',3,'mc','auto','계산 결과가 큰 것부터 차례로 쓴 것은 어느 것인가요? ㉠ ⟨15/16⟩ ÷ ⟨5/16⟩ ㉡ ⟨7/18⟩ ÷ ⟨8/9⟩ ㉢ ⟨2/5⟩ ÷ ⟨3/10⟩',ARRAY['M6-2-u1-X20','M6-2-u1-X06','M6-2-u1-X16']::text[],false,'{"seq":6,"concept":"M6-2-u1-C4","difficulty":3,"kind":"mc","stem":"계산 결과가 큰 것부터 차례로 쓴 것은 어느 것인가요? ㉠ ⟨15/16⟩ ÷ ⟨5/16⟩ ㉡ ⟨7/18⟩ ÷ ⟨8/9⟩ ㉢ ⟨2/5⟩ ÷ ⟨3/10⟩","options":[{"t":"㉠, ㉢, ㉡","correct":true},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u1-X20"},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u1-X06"},{"t":"㉢, ㉠, ㉡","mis":"M6-2-u1-X16"}],"explanation":["㉠ ⟨15/16⟩ ÷ ⟨5/16⟩ = 15 ÷ 5 = 3.","㉡ ⟨7/18⟩ ÷ ⟨8/9⟩ = 7 ÷ 16 = ⟨7/16⟩, ㉢ ⟨2/5⟩ ÷ ⟨3/10⟩ = 4 ÷ 3 = ⟨1 1/3⟩.","3 > ⟨1 1/3⟩ > ⟨7/16⟩ — ㉠, ㉢, ㉡이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_challenge#7','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',3,'mc','auto','계산 결과가 더 작은 것은 어느 것인가요? ㉠ ⟨11/12⟩ ÷ ⟨2/3⟩ ㉡ ⟨11/12⟩ ÷ ⟨3/4⟩',ARRAY['M6-2-u1-X16','M6-2-u1-X06']::text[],false,'{"seq":7,"concept":"M6-2-u1-C4","difficulty":3,"kind":"mc","stem":"계산 결과가 더 작은 것은 어느 것인가요? ㉠ ⟨11/12⟩ ÷ ⟨2/3⟩ ㉡ ⟨11/12⟩ ÷ ⟨3/4⟩","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M6-2-u1-X16"},{"t":"두 몫이 같다","mis":"M6-2-u1-X06"}],"explanation":["㉠ ⟨11/12⟩ ÷ ⟨2/3⟩ = 11 ÷ 8 = ⟨1 3/8⟩.","㉡ ⟨11/12⟩ ÷ ⟨3/4⟩ = 11 ÷ 9 = ⟨1 2/9⟩.","나누는 수 ⟨3/4⟩이 ⟨2/3⟩보다 커서 ㉡의 몫이 더 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_challenge#8','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',4,'essay','teacher','⟨3/4⟩ ÷ ⟨2/5⟩를 계산하려면 왜 먼저 통분해야 하는지, 통분한 뒤 어떻게 계산하는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u1-C4","difficulty":4,"kind":"essay","stem":"⟨3/4⟩ ÷ ⟨2/5⟩를 계산하려면 왜 먼저 통분해야 하는지, 통분한 뒤 어떻게 계산하는지 설명해 보세요.","answer_guide":{"answer":"예: ⟨3/4⟩는 ⟨1/4⟩이 3개, ⟨2/5⟩는 ⟨1/5⟩이 2개라 조각의 크기가 달라 개수끼리 나눌 수 없다. 공통분모 20으로 통분하면 ⟨15/20⟩ ÷ ⟨8/20⟩이 되어 ⟨1/20⟩의 개수끼리 나누면 15 ÷ 8 = ⟨15/8⟩ = ⟨1 7/8⟩이다.","scoring_points":["조각의 크기가 달라 바로 나눌 수 없다고 썼는가","⟨15/20⟩ ÷ ⟨8/20⟩로 통분했는가","15 ÷ 8 = ⟨1 7/8⟩을 구했는가"]},"explanation":["분모가 다르면 단위분수의 크기가 달라요.","⟨3/4⟩ ÷ ⟨2/5⟩ = ⟨15/20⟩ ÷ ⟨8/20⟩ = 15 ÷ 8 = ⟨1 7/8⟩.","통분하면 분모가 같은 나눗셈과 같아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_challenge#9','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',4,'essay','teacher','친구가 ⟨8/9⟩ ÷ ⟨5/8⟩를 ⟨8/72⟩ ÷ ⟨5/72⟩로 고쳐 계산했어요. 잘못된 곳을 찾아 이유를 쓰고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u1-C4","difficulty":4,"kind":"essay","stem":"친구가 ⟨8/9⟩ ÷ ⟨5/8⟩를 ⟨8/72⟩ ÷ ⟨5/72⟩로 고쳐 계산했어요. 잘못된 곳을 찾아 이유를 쓰고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 분모를 72로 바꾸면서 분자는 그대로 두었다. ⟨8/9⟩ = ⟨64/72⟩, ⟨5/8⟩ = ⟨45/72⟩이므로 ⟨8/9⟩ ÷ ⟨5/8⟩ = ⟨64/72⟩ ÷ ⟨45/72⟩ = 64 ÷ 45 = ⟨64/45⟩ = ⟨1 19/45⟩이다.","scoring_points":["분자를 바꾸지 않은 곳을 찾았는가","⟨64/72⟩ ÷ ⟨45/72⟩로 바르게 통분했는가","⟨1 19/45⟩를 구했는가"]},"explanation":["분모를 바꾸면 분자도 같은 수를 곱해 바꿔요.","⟨8/9⟩ ÷ ⟨5/8⟩ = 64 ÷ 45 = ⟨1 19/45⟩.","분모만 바꾸면 크기가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L04_challenge#10','math',6,2,'u1','L04','tb_g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',4,'mc','auto','⟨5/6⟩ ÷ ⟨4/7⟩를 통분하여 계산한 몫은 얼마인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X05','M6-2-u1-X10']::text[],false,'{"seq":10,"concept":"M6-2-u1-C4","difficulty":4,"kind":"mc","stem":"⟨5/6⟩ ÷ ⟨4/7⟩를 통분하여 계산한 몫은 얼마인가요?","options":[{"t":"⟨1 11/24⟩","correct":true},{"t":"⟨1 1/4⟩","mis":"M6-2-u1-X06"},{"t":"⟨24/35⟩","mis":"M6-2-u1-X05"},{"t":"⟨10/21⟩","mis":"M6-2-u1-X10"}],"explanation":["6과 7의 공배수 42로 통분해요 — ⟨5/6⟩ ÷ ⟨4/7⟩ = ⟨35/42⟩ ÷ ⟨24/42⟩.","35 ÷ 24 = ⟨35/24⟩ = ⟨1 11/24⟩.","분자 5와 4를 바로 나누면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_basic#1','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',1,'mc','auto','로봇이 주스 5 L를 만드는 데 ⟨1/3⟩시간이 걸렸어요. 로봇이 1시간 동안 만들 수 있는 주스양을 구하는 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X10','M6-2-u1-X03']::text[],false,'{"seq":1,"concept":"M6-2-u1-C5","difficulty":1,"kind":"mc","stem":"로봇이 주스 5 L를 만드는 데 ⟨1/3⟩시간이 걸렸어요. 로봇이 1시간 동안 만들 수 있는 주스양을 구하는 식은 어느 것인가요?","options":[{"t":"5 ÷ ⟨1/3⟩","correct":true},{"t":"⟨1/3⟩ ÷ 5","mis":"M6-2-u1-X01"},{"t":"5 × ⟨1/3⟩","mis":"M6-2-u1-X10"},{"t":"5 − ⟨1/3⟩","mis":"M6-2-u1-X03"}],"explanation":["주스 5 L를 만드는 데 2시간이 걸렸다면 5 ÷ 2로 구해요.","주스양을 걸린 시간으로 나누는 거예요.","걸린 시간이 ⟨1/3⟩시간이니 식은 5 ÷ ⟨1/3⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_basic#2','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',1,'mc','auto','「주스 5 L를 만드는 데 2시간이 걸렸다면 1시간 동안 만들 수 있는 주스양은 5 ÷ 2로 구할 수 있어요.」 여기서 무엇을 무엇으로 나누었나요?',ARRAY['M6-2-u1-X01','M6-2-u1-X03']::text[],false,'{"seq":2,"concept":"M6-2-u1-C5","difficulty":1,"kind":"mc","stem":"「주스 5 L를 만드는 데 2시간이 걸렸다면 1시간 동안 만들 수 있는 주스양은 5 ÷ 2로 구할 수 있어요.」 여기서 무엇을 무엇으로 나누었나요?","options":[{"t":"주스양을 걸린 시간으로","correct":true},{"t":"걸린 시간을 주스양으로","mis":"M6-2-u1-X01"},{"t":"주스양과 걸린 시간을 곱해서","mis":"M6-2-u1-X03"},{"t":"1시간을 주스양으로","mis":"M6-2-u1-X01"}],"explanation":["1시간 동안의 양은 전체 양을 걸린 시간으로 나누어 구해요.","5 ÷ 2는 주스양 5를 시간 2로 나눈 식이에요.","걸린 시간이 분수여도 같은 식 — 5 ÷ ⟨1/3⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_basic#3','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',1,'sa','auto','4 ÷ ⟨1/2⟩을 계산해 보세요. 몫을 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-2-u1-C5","difficulty":1,"kind":"sa","stem":"4 ÷ ⟨1/2⟩을 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["8"],"explanation":["1 안에는 ⟨1/2⟩이 2번 들어가요.","4 ÷ ⟨1/2⟩ = 4 × 2 = 8.","1보다 작은 수로 나누니 몫 8은 4보다 커요."],"variant_rule":{"alt":[{"stem":"6 ÷ ⟨1/5⟩을 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["30"],"explanation":["1 안에는 ⟨1/5⟩이 5번 들어가요.","6 ÷ ⟨1/5⟩ = 6 × 5 = 30.","1보다 작은 수로 나누니 몫 30은 6보다 커요."]},{"stem":"11 ÷ ⟨1/4⟩을 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["44"],"explanation":["1 안에는 ⟨1/4⟩이 4번 들어가요.","11 ÷ ⟨1/4⟩ = 11 × 4 = 44.","1보다 작은 수로 나누니 몫 44는 11보다 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_basic#4','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',1,'sa','auto','이중수직선에서 1시간은 ⟨1/3⟩시간의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u1-C5","difficulty":1,"kind":"sa","stem":"이중수직선에서 1시간은 ⟨1/3⟩시간의 몇 배인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["1시간을 3으로 똑같이 나눈 하나가 ⟨1/3⟩시간이에요.","그래서 1시간은 ⟨1/3⟩시간의 3배예요.","로봇이 1시간 동안 만드는 주스는 ⟨1/3⟩시간 동안의 3배예요."],"variant_rule":{"alt":[{"stem":"1은 ⟨1/4⟩의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["1을 4로 똑같이 나눈 하나가 ⟨1/4⟩이에요.","그래서 1은 ⟨1/4⟩의 4배예요.","⟨1/4⟩만큼의 양을 4배 하면 1만큼의 양이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_basic#5','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',2,'sa','auto','로봇이 주스 5 L를 만드는 데 ⟨1/3⟩시간이 걸렸어요. 로봇이 1시간 동안 만들 수 있는 주스는 몇 L인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u1-C5","difficulty":2,"kind":"sa","stem":"로봇이 주스 5 L를 만드는 데 ⟨1/3⟩시간이 걸렸어요. 로봇이 1시간 동안 만들 수 있는 주스는 몇 L인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["1시간은 ⟨1/3⟩시간의 3배예요.","5 ÷ ⟨1/3⟩ = 5 × 3 = 15.","1시간 동안 주스 15 L를 만들 수 있어요."],"variant_rule":{"alt":[{"stem":"진수는 자전거를 타고 2 km를 가는 데 ⟨1/3⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 갈 수 있는 거리는 몇 km인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["1시간은 ⟨1/3⟩시간의 3배예요.","2 ÷ ⟨1/3⟩ = 2 × 3 = 6.","1시간 동안 6 km를 갈 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_basic#6','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',2,'mc','auto','7 ÷ ⟨1/6⟩을 계산해 보세요.',ARRAY['M6-2-u1-X08','M6-2-u1-X01','M6-2-u1-X03']::text[],true,'{"seq":6,"concept":"M6-2-u1-C5","difficulty":2,"kind":"mc","stem":"7 ÷ ⟨1/6⟩을 계산해 보세요.","options":[{"t":"42","correct":true},{"t":"⟨1 1/6⟩","mis":"M6-2-u1-X08"},{"t":"⟨1/42⟩","mis":"M6-2-u1-X01"},{"t":"13","mis":"M6-2-u1-X03"}],"explanation":["1 안에는 ⟨1/6⟩이 6번 들어가요.","7 ÷ ⟨1/6⟩ = 7 × 6 = 42.","1보다 작은 수로 나누니 몫 42는 7보다 커요."],"variant_rule":{"alt":[{"stem":"8 ÷ ⟨1/4⟩을 계산해 보세요.","options":[{"t":"32","correct":true},{"t":"2","mis":"M6-2-u1-X08"},{"t":"⟨1/32⟩","mis":"M6-2-u1-X01"},{"t":"12","mis":"M6-2-u1-X03"}],"explanation":["1 안에는 ⟨1/4⟩이 4번 들어가요.","8 ÷ ⟨1/4⟩ = 8 × 4 = 32.","1보다 작은 수로 나누니 몫 32는 8보다 커요."]},{"stem":"6 ÷ ⟨1/7⟩을 계산해 보세요.","options":[{"t":"42","correct":true},{"t":"⟨6/7⟩","mis":"M6-2-u1-X08"},{"t":"⟨1/42⟩","mis":"M6-2-u1-X01"},{"t":"13","mis":"M6-2-u1-X03"}],"explanation":["1 안에는 ⟨1/7⟩이 7번 들어가요.","6 ÷ ⟨1/7⟩ = 6 × 7 = 42.","1보다 작은 수로 나누니 몫 42는 6보다 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_basic#7','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',2,'ox','auto','5 ÷ ⟨1/3⟩의 몫은 나누어지는 수 5보다 작아요.',ARRAY['M6-2-u1-X09']::text[],false,'{"seq":7,"concept":"M6-2-u1-C5","difficulty":2,"kind":"ox","stem":"5 ÷ ⟨1/3⟩의 몫은 나누어지는 수 5보다 작아요.","answer":"X","reason_options":[{"t":"1보다 작은 ⟨1/3⟩로 나누면 몫은 5 × 3 = 15로 5보다 커져서","correct":true},{"t":"나눗셈을 하면 몫은 언제나 나누어지는 수보다 작아져서","mis":"M6-2-u1-X09"}],"mis":"M6-2-u1-X09","explanation":["5 ÷ ⟨1/3⟩ = 5 × 3 = 15예요.","1보다 작은 수로 나누면 몫이 나누어지는 수보다 커져요.","「나눗셈을 하면 작아진다」는 늘 맞는 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_basic#8','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M6-2-u1-C5","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"4 ÷ ⟨1/2⟩","r":"8"},{"l":"6 ÷ ⟨1/5⟩","r":"30"},{"l":"11 ÷ ⟨1/4⟩","r":"44"}],"mis":"M6-2-u1-X08","explanation":["자연수에 단위분수의 분모를 곱해요.","4 × 2 = 8, 6 × 5 = 30, 11 × 4 = 44예요.","분모로 나누면 안 돼요."],"variant_rule":{"alt":[{"stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"5 ÷ ⟨1/2⟩","r":"10"},{"l":"6 ÷ ⟨1/7⟩","r":"42"},{"l":"10 ÷ ⟨1/9⟩","r":"90"}],"explanation":["자연수에 단위분수의 분모를 곱해요.","5 × 2 = 10, 6 × 7 = 42, 10 × 9 = 90이에요.","분모로 나누면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_basic#9','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',2,'sa','auto','밀가루 8 kg을 한 통에 ⟨1/4⟩ kg씩 나누어 담으려고 해요. 통은 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-2-u1-C5","difficulty":2,"kind":"sa","stem":"밀가루 8 kg을 한 통에 ⟨1/4⟩ kg씩 나누어 담으려고 해요. 통은 몇 개 필요한가요? 숫자로 쓰세요.","answer":["32"],"explanation":["식은 8 ÷ ⟨1/4⟩이에요.","8 ÷ ⟨1/4⟩ = 8 × 4 = 32.","통 32개가 필요해요."],"variant_rule":{"alt":[{"stem":"물 3 L를 한 컵에 ⟨1/5⟩ L씩 나누어 담으려면 컵은 몇 개 필요한가요? 숫자로 쓰세요.","answer":["15"],"explanation":["식은 3 ÷ ⟨1/5⟩이에요.","3 ÷ ⟨1/5⟩ = 3 × 5 = 15.","컵 15개가 필요해요."]},{"stem":"길이가 2 m인 끈을 ⟨1/3⟩ m씩 잘라 리본을 만들려고 해요. 리본을 몇 개 만들 수 있나요? 숫자로 쓰세요.","answer":["6"],"explanation":["식은 2 ÷ ⟨1/3⟩이에요.","2 ÷ ⟨1/3⟩ = 2 × 3 = 6.","리본 6개를 만들 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_basic#10','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',3,'mc','auto','「같은 것을 찾아요」 카드 놀이예요. 5 ÷ ⟨1/3⟩ 카드와 짝이 되는 카드는 어느 것인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X08']::text[],true,'{"seq":10,"concept":"M6-2-u1-C5","difficulty":3,"kind":"mc","stem":"「같은 것을 찾아요」 카드 놀이예요. 5 ÷ ⟨1/3⟩ 카드와 짝이 되는 카드는 어느 것인가요?","options":[{"t":"5 × 3","correct":true},{"t":"5 × ⟨1/3⟩","mis":"M6-2-u1-X10"},{"t":"3 × ⟨1/5⟩","mis":"M6-2-u1-X08"},{"t":"5 ÷ 3","mis":"M6-2-u1-X08"}],"explanation":["1은 ⟨1/3⟩의 3배라 5 ÷ ⟨1/3⟩은 5의 3배예요.","5 ÷ ⟨1/3⟩ = 5 × 3 = 15.","짝 카드는 (자연수)×(자연수) 5 × 3이에요."],"variant_rule":{"alt":[{"stem":"「같은 것을 찾아요」 카드 놀이예요. 11 ÷ ⟨1/4⟩ 카드와 짝이 되는 카드는 어느 것인가요?","options":[{"t":"11 × 4","correct":true},{"t":"11 × ⟨1/4⟩","mis":"M6-2-u1-X10"},{"t":"4 × ⟨1/11⟩","mis":"M6-2-u1-X08"},{"t":"11 ÷ 4","mis":"M6-2-u1-X08"}],"explanation":["1은 ⟨1/4⟩의 4배예요.","11 ÷ ⟨1/4⟩ = 11 × 4 = 44.","짝 카드는 11 × 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_challenge#1','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C4',2,'mc','auto','⟨3/8⟩ ÷ ⟨2/5⟩를 계산해 보세요.',ARRAY['M6-2-u1-X06','M6-2-u1-X10','M6-2-u1-X05']::text[],true,'{"seq":1,"concept":"M6-2-u1-C4","difficulty":2,"kind":"mc","stem":"⟨3/8⟩ ÷ ⟨2/5⟩를 계산해 보세요.","options":[{"t":"⟨15/16⟩","correct":true},{"t":"⟨1 1/2⟩","mis":"M6-2-u1-X06"},{"t":"⟨3/20⟩","mis":"M6-2-u1-X10"},{"t":"⟨1 1/15⟩","mis":"M6-2-u1-X05"}],"explanation":["분모가 다르니 먼저 통분해요 — ⟨3/8⟩ ÷ ⟨2/5⟩ = ⟨15/40⟩ ÷ ⟨16/40⟩.","분모가 같아졌으니 분자끼리 나눠요 — 15 ÷ 16 = ⟨15/16⟩.","조각의 크기를 같게 맞춘 뒤 개수끼리 나눈 거예요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩ ÷ ⟨1/2⟩을 계산해 보세요.","options":[{"t":"⟨1 1/2⟩","correct":true},{"t":"3","mis":"M6-2-u1-X06"},{"t":"⟨3/8⟩","mis":"M6-2-u1-X10"},{"t":"⟨2/3⟩","mis":"M6-2-u1-X05"}],"explanation":["분모가 다르니 먼저 통분해요 — ⟨3/4⟩ ÷ ⟨1/2⟩ = ⟨3/4⟩ ÷ ⟨2/4⟩.","분모가 같아졌으니 분자끼리 나눠요 — 3 ÷ 2 = ⟨3/2⟩ = ⟨1 1/2⟩.","조각의 크기를 같게 맞춘 뒤 개수끼리 나눈 거예요."]},{"stem":"⟨2/5⟩ ÷ ⟨5/6⟩를 계산해 보세요.","options":[{"t":"⟨12/25⟩","correct":true},{"t":"⟨2/5⟩","mis":"M6-2-u1-X06"},{"t":"⟨1/3⟩","mis":"M6-2-u1-X10"},{"t":"⟨2 1/12⟩","mis":"M6-2-u1-X05"}],"explanation":["분모가 다르니 먼저 통분해요 — ⟨2/5⟩ ÷ ⟨5/6⟩ = ⟨12/30⟩ ÷ ⟨25/30⟩.","분모가 같아졌으니 분자끼리 나눠요 — 12 ÷ 25 = ⟨12/25⟩.","조각의 크기를 같게 맞춘 뒤 개수끼리 나눈 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_challenge#2','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',2,'mc','auto','계산 결과가 28인 것은 어느 것인가요? ㉠ 8 ÷ ⟨1/7⟩ ㉡ 4 ÷ ⟨1/7⟩',ARRAY['M6-2-u1-X08']::text[],false,'{"seq":2,"concept":"M6-2-u1-C5","difficulty":2,"kind":"mc","stem":"계산 결과가 28인 것은 어느 것인가요? ㉠ 8 ÷ ⟨1/7⟩ ㉡ 4 ÷ ⟨1/7⟩","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M6-2-u1-X08"},{"t":"둘 다 아니다","mis":"M6-2-u1-X08"}],"explanation":["㉠ 8 ÷ ⟨1/7⟩ = 8 × 7 = 56.","㉡ 4 ÷ ⟨1/7⟩ = 4 × 7 = 28.","계산 결과가 28인 것은 ㉡이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_challenge#3','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',3,'mc','auto','어떤 수를 ⟨1/6⟩로 나누어야 할 것을 잘못하여 곱했더니 18이 되었어요. 어떤 수는 얼마인가요?',ARRAY['M6-2-u1-X19','M6-2-u1-X01']::text[],false,'{"seq":3,"concept":"M6-2-u1-C5","difficulty":3,"kind":"mc","stem":"어떤 수를 ⟨1/6⟩로 나누어야 할 것을 잘못하여 곱했더니 18이 되었어요. 어떤 수는 얼마인가요?","options":[{"t":"108","correct":true},{"t":"3","mis":"M6-2-u1-X19"},{"t":"18","mis":"M6-2-u1-X19"},{"t":"⟨1/108⟩","mis":"M6-2-u1-X01"}],"explanation":["어떤 수를 □라 하면 □ × ⟨1/6⟩ = 18이에요.","□ = 18 ÷ ⟨1/6⟩ = 18 × 6 = 108.","곱한 것을 거꾸로 나누어 어떤 수를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_challenge#4','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',3,'mc','auto','□ < 2 ÷ ⟨1/3⟩에서 □ 안에 들어갈 수 있는 자연수를 모두 고른 것은 어느 것인가요?',ARRAY['M6-2-u1-X20','M6-2-u1-X18','M6-2-u1-X08']::text[],false,'{"seq":4,"concept":"M6-2-u1-C5","difficulty":3,"kind":"mc","stem":"□ < 2 ÷ ⟨1/3⟩에서 □ 안에 들어갈 수 있는 자연수를 모두 고른 것은 어느 것인가요?","options":[{"t":"1, 2, 3, 4, 5","correct":true},{"t":"1, 2, 3, 4, 5, 6","mis":"M6-2-u1-X20"},{"t":"6","mis":"M6-2-u1-X18"},{"t":"없다","mis":"M6-2-u1-X08"}],"explanation":["2 ÷ ⟨1/3⟩ = 2 × 3 = 6이에요.","□ < 6이니 □는 6보다 작은 자연수예요.","1, 2, 3, 4, 5 — 6은 들어가지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_challenge#5','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',3,'sa','auto','5 ÷ ⟨1/3⟩과 4 ÷ ⟨1/6⟩의 계산 결과의 차를 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M6-2-u1-C5","difficulty":3,"kind":"sa","stem":"5 ÷ ⟨1/3⟩과 4 ÷ ⟨1/6⟩의 계산 결과의 차를 숫자로 쓰세요.","answer":["9"],"explanation":["5 ÷ ⟨1/3⟩ = 5 × 3 = 15.","4 ÷ ⟨1/6⟩ = 4 × 6 = 24.","두 결과의 차는 24 − 15 = 9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_challenge#6','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',3,'mc','auto','2 ÷ ⟨1/3⟩을 이용하여 풀 수 있는 문제는 어느 것인가요?',ARRAY['M6-2-u1-X18','M6-2-u1-X10','M6-2-u1-X01']::text[],false,'{"seq":6,"concept":"M6-2-u1-C5","difficulty":3,"kind":"mc","stem":"2 ÷ ⟨1/3⟩을 이용하여 풀 수 있는 문제는 어느 것인가요?","options":[{"t":"길이가 2 m인 끈을 ⟨1/3⟩ m씩 잘라 리본을 만들면 몇 개 만들 수 있나요?","correct":true},{"t":"끈 2 m를 3명이 똑같이 나누어 가지면 한 명은 몇 m를 가지나요?","mis":"M6-2-u1-X18"},{"t":"끈 2 m의 ⟨1/3⟩은 몇 m인가요?","mis":"M6-2-u1-X10"},{"t":"끈 ⟨1/3⟩ m를 2 m씩 자르면 몇 개가 되나요?","mis":"M6-2-u1-X01"}],"explanation":["2 ÷ ⟨1/3⟩은 2 m에서 ⟨1/3⟩ m씩 몇 번 덜어 낼 수 있는지예요.","2 ÷ ⟨1/3⟩ = 2 × 3 = 6 — 리본 6개예요.","3명이 나누는 것은 2 ÷ 3, 2 m의 ⟨1/3⟩은 2 × ⟨1/3⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_challenge#7','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',3,'mc','auto','이중수직선으로 로봇이 1시간 동안 만드는 주스양을 구해요. ① ⟨1/3⟩시간 동안 5 L ② 1시간 동안 □ L — ①에서 ②로 가는 계산은 어느 것인가요?',ARRAY['M6-2-u1-X08','M6-2-u1-X10','M6-2-u1-X22']::text[],false,'{"seq":7,"concept":"M6-2-u1-C5","difficulty":3,"kind":"mc","stem":"이중수직선으로 로봇이 1시간 동안 만드는 주스양을 구해요. ① ⟨1/3⟩시간 동안 5 L ② 1시간 동안 □ L — ①에서 ②로 가는 계산은 어느 것인가요?","options":[{"t":"5 × 3","correct":true},{"t":"5 ÷ 3","mis":"M6-2-u1-X08"},{"t":"5 × ⟨1/3⟩","mis":"M6-2-u1-X10"},{"t":"5 그대로","mis":"M6-2-u1-X22"}],"explanation":["1시간은 ⟨1/3⟩시간의 3배예요.","시간이 3배가 되면 주스양도 3배 — 5 × 3 = 15.","5 L는 ⟨1/3⟩시간 동안의 양이라 1시간 동안의 양이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_challenge#8','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',4,'essay','teacher','「나눗셈을 하면 그 결과가 작아진다.」라는 친구의 생각이 늘 맞는 것은 아님을 5 ÷ ⟨1/3⟩을 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u1-C5","difficulty":4,"kind":"essay","stem":"「나눗셈을 하면 그 결과가 작아진다.」라는 친구의 생각이 늘 맞는 것은 아님을 5 ÷ ⟨1/3⟩을 예로 들어 설명해 보세요.","answer_guide":{"answer":"예: 5 ÷ ⟨1/3⟩은 5 안에 ⟨1/3⟩이 몇 번 들어가는지이다. 1 안에 ⟨1/3⟩이 3번 들어가므로 5 ÷ ⟨1/3⟩ = 5 × 3 = 15이다. 1보다 작은 수로 나누면 몫이 나누어지는 수보다 커지므로 나눗셈 결과가 늘 작아지는 것은 아니다.","scoring_points":["5 ÷ ⟨1/3⟩ = 15를 바르게 구했는가","1 안에 ⟨1/3⟩이 3번 들어감을 썼는가","1보다 작은 수로 나누면 몫이 커짐을 밝혔는가"]},"explanation":["5 ÷ ⟨1/3⟩ = 5 × 3 = 15예요.","15는 나누어지는 수 5보다 커요.","1보다 작은 수로 나누면 몫이 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_challenge#9','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',4,'mc','auto','6 ÷ ⟨1/3⟩과 6 ÷ ⟨1/5⟩ 가운데 몫이 더 큰 것과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u1-X16','M6-2-u1-X08']::text[],false,'{"seq":9,"concept":"M6-2-u1-C5","difficulty":4,"kind":"mc","stem":"6 ÷ ⟨1/3⟩과 6 ÷ ⟨1/5⟩ 가운데 몫이 더 큰 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"6 ÷ ⟨1/5⟩ — ⟨1/5⟩이 더 작아서 6 안에 더 많이 들어가요","correct":true},{"t":"6 ÷ ⟨1/3⟩ — 3이 5보다 작아서 몫이 커요","mis":"M6-2-u1-X16"},{"t":"두 몫이 같아요 — 나누어지는 수가 6으로 같아서","mis":"M6-2-u1-X08"},{"t":"6 ÷ ⟨1/3⟩ — ⟨1/3⟩이 더 커서 몫이 커요","mis":"M6-2-u1-X16"}],"explanation":["6 ÷ ⟨1/3⟩ = 6 × 3 = 18.","6 ÷ ⟨1/5⟩ = 6 × 5 = 30.","나누는 수가 작을수록 몫이 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L05_challenge#10','math',6,2,'u1','L05','tb_g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',4,'essay','teacher','어떤 수를 ⟨1/6⟩로 나누어야 할 것을 잘못하여 곱했더니 18이 되었어요. 어떤 수를 구하는 과정을 식으로 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u1-C5","difficulty":4,"kind":"essay","stem":"어떤 수를 ⟨1/6⟩로 나누어야 할 것을 잘못하여 곱했더니 18이 되었어요. 어떤 수를 구하는 과정을 식으로 설명해 보세요.","answer_guide":{"answer":"예: 어떤 수를 □라 하면 잘못 계산한 식은 □ × ⟨1/6⟩ = 18이다. 곱셈과 나눗셈의 관계로 □ = 18 ÷ ⟨1/6⟩ = 18 × 6 = 108이므로 어떤 수는 108이다.","scoring_points":["잘못 계산한 식 □ × ⟨1/6⟩ = 18을 세웠는가","□ = 18 ÷ ⟨1/6⟩로 바꾸었는가","어떤 수 108을 구했는가"]},"explanation":["잘못 계산한 식부터 세워요 — □ × ⟨1/6⟩ = 18.","□ = 18 ÷ ⟨1/6⟩ = 18 × 6 = 108.","어떤 수는 108이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_basic#1','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',1,'mc','auto','오늘 자전거를 타고 4 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. 자전거로 1시간 동안 갈 수 있는 거리를 구하는 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X10','M6-2-u1-X03']::text[],false,'{"seq":1,"concept":"M6-2-u1-C6","difficulty":1,"kind":"mc","stem":"오늘 자전거를 타고 4 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. 자전거로 1시간 동안 갈 수 있는 거리를 구하는 식은 어느 것인가요?","options":[{"t":"4 ÷ ⟨2/3⟩","correct":true},{"t":"⟨2/3⟩ ÷ 4","mis":"M6-2-u1-X01"},{"t":"4 × ⟨2/3⟩","mis":"M6-2-u1-X10"},{"t":"4 − ⟨2/3⟩","mis":"M6-2-u1-X03"}],"explanation":["간 거리를 걸린 시간으로 나누면 1시간 동안의 거리예요.","4 km를 가는 데 3시간이 걸렸다면 4 ÷ 3이에요.","걸린 시간이 ⟨2/3⟩시간이니 식은 4 ÷ ⟨2/3⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_basic#2','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',1,'sa','auto','자전거로 4 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. ⟨2/3⟩시간을 2로 나누어 ⟨1/3⟩시간 동안 간 거리를 구하면 몇 km인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M6-2-u1-C6","difficulty":1,"kind":"sa","stem":"자전거로 4 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. ⟨2/3⟩시간을 2로 나누어 ⟨1/3⟩시간 동안 간 거리를 구하면 몇 km인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨1/3⟩시간은 ⟨2/3⟩시간을 2로 나눈 것이에요.","거리도 2로 나눠요 — 4 ÷ 2 = 2.","⟨1/3⟩시간 동안 2 km를 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_basic#3','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',1,'sa','auto','7 ÷ ⟨7/9⟩을 계산해 보세요. 몫을 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-2-u1-C6","difficulty":1,"kind":"sa","stem":"7 ÷ ⟨7/9⟩을 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["9"],"explanation":["분자 7로 나누고 분모 9를 곱해요 — 7 ÷ ⟨7/9⟩ = 7 ÷ 7 × 9 = 9.","곱셈으로 나타내면 7 × ⟨9/7⟩ = 9.","나누는 분수의 분모와 분자를 바꾸어 곱한 거예요."],"variant_rule":{"alt":[{"stem":"9 ÷ ⟨3/7⟩을 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["21"],"explanation":["분자 3으로 나누고 분모 7을 곱해요 — 9 ÷ ⟨3/7⟩ = 9 ÷ 3 × 7 = 21.","곱셈으로 나타내면 9 × ⟨7/3⟩ = 21.","나누는 분수의 분모와 분자를 바꾸어 곱한 거예요."]},{"stem":"6 ÷ ⟨2/5⟩를 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["15"],"explanation":["분자 2로 나누고 분모 5를 곱해요 — 6 ÷ ⟨2/5⟩ = 6 ÷ 2 × 5 = 15.","곱셈으로 나타내면 6 × ⟨5/2⟩ = 15.","나누는 분수의 분모와 분자를 바꾸어 곱한 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_basic#4','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',1,'mc','auto','4 ÷ ⟨3/4⟩을 계산해 보세요.',ARRAY['M6-2-u1-X10','M6-2-u1-X01','M6-2-u1-X22']::text[],true,'{"seq":4,"concept":"M6-2-u1-C6","difficulty":1,"kind":"mc","stem":"4 ÷ ⟨3/4⟩을 계산해 보세요.","options":[{"t":"⟨5 1/3⟩","correct":true},{"t":"3","mis":"M6-2-u1-X10"},{"t":"⟨3/16⟩","mis":"M6-2-u1-X01"},{"t":"⟨1 1/3⟩","mis":"M6-2-u1-X22"}],"explanation":["분자 3으로 나누고 분모 4를 곱해요 — 4 ÷ ⟨3/4⟩ = 4 ÷ 3 × 4 = ⟨5 1/3⟩.","곱셈으로 나타내면 4 × ⟨4/3⟩ = ⟨5 1/3⟩.","나누는 분수의 분모와 분자를 바꾸어 곱한 거예요."],"variant_rule":{"alt":[{"stem":"5 ÷ ⟨2/3⟩를 계산해 보세요.","options":[{"t":"⟨7 1/2⟩","correct":true},{"t":"⟨3 1/3⟩","mis":"M6-2-u1-X10"},{"t":"⟨2/15⟩","mis":"M6-2-u1-X01"},{"t":"⟨2 1/2⟩","mis":"M6-2-u1-X22"}],"explanation":["분자 2로 나누고 분모 3을 곱해요 — 5 ÷ ⟨2/3⟩ = 5 ÷ 2 × 3 = ⟨7 1/2⟩.","곱셈으로 나타내면 5 × ⟨3/2⟩ = ⟨7 1/2⟩.","나누는 분수의 분모와 분자를 바꾸어 곱한 거예요."]},{"stem":"2 ÷ ⟨5/6⟩를 계산해 보세요.","options":[{"t":"⟨2 2/5⟩","correct":true},{"t":"⟨1 2/3⟩","mis":"M6-2-u1-X10"},{"t":"⟨5/12⟩","mis":"M6-2-u1-X01"},{"t":"⟨2/5⟩","mis":"M6-2-u1-X22"}],"explanation":["분자 5로 나누고 분모 6을 곱해요 — 2 ÷ ⟨5/6⟩ = 2 ÷ 5 × 6 = ⟨2 2/5⟩.","곱셈으로 나타내면 2 × ⟨6/5⟩ = ⟨2 2/5⟩.","나누는 분수의 분모와 분자를 바꾸어 곱한 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_basic#5','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',2,'sa','auto','자전거로 4 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 갈 수 있는 거리는 몇 km인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M6-2-u1-C6","difficulty":2,"kind":"sa","stem":"자전거로 4 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 갈 수 있는 거리는 몇 km인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["⟨1/3⟩시간 동안 4 ÷ 2 = 2 km를 가요.","1시간은 ⟨1/3⟩시간의 3배 — 2 × 3 = 6.","4 ÷ ⟨2/3⟩ = 4 × ⟨3/2⟩ = 6, 1시간 동안 6 km예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_basic#6','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',2,'mc','auto','4 ÷ ⟨2/3⟩ = 4 ÷ 2 × 3을 곱셈 하나로 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X11','M6-2-u1-X22']::text[],true,'{"seq":6,"concept":"M6-2-u1-C6","difficulty":2,"kind":"mc","stem":"4 ÷ ⟨2/3⟩ = 4 ÷ 2 × 3을 곱셈 하나로 나타낸 것은 어느 것인가요?","options":[{"t":"4 × ⟨3/2⟩","correct":true},{"t":"4 × ⟨2/3⟩","mis":"M6-2-u1-X10"},{"t":"4 ÷ 3 × 2","mis":"M6-2-u1-X11"},{"t":"4 × 3","mis":"M6-2-u1-X22"}],"explanation":["÷ 2는 × ⟨1/2⟩과 같아요 — 4 ÷ 2 × 3 = 4 × ⟨1/2⟩ × 3.","⟨1/2⟩ × 3 = ⟨3/2⟩이라 4 × ⟨3/2⟩이에요.","4 ÷ ⟨2/3⟩ = 4 × ⟨3/2⟩ = 6 — 나누는 분수의 분모와 분자가 바뀌었어요."],"variant_rule":{"alt":[{"stem":"3 ÷ ⟨5/6⟩ = 3 ÷ 5 × 6을 곱셈 하나로 나타낸 것은 어느 것인가요?","options":[{"t":"3 × ⟨6/5⟩","correct":true},{"t":"3 × ⟨5/6⟩","mis":"M6-2-u1-X10"},{"t":"3 ÷ 6 × 5","mis":"M6-2-u1-X11"},{"t":"3 × 6","mis":"M6-2-u1-X22"}],"explanation":["÷ 5는 × ⟨1/5⟩과 같아요 — 3 ÷ 5 × 6 = 3 × ⟨1/5⟩ × 6.","⟨1/5⟩ × 6 = ⟨6/5⟩이라 3 × ⟨6/5⟩이에요.","3 ÷ ⟨5/6⟩ = 3 × ⟨6/5⟩ = ⟨3 3/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_basic#7','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',2,'mc','auto','잘못 계산한 것을 찾으세요. ㉠ 6 ÷ ⟨2/5⟩ = 6 ÷ 2 × 5 = 15 ㉡ 10 ÷ ⟨3/5⟩ = 10 ÷ 5 × 3 = 6',ARRAY['M6-2-u1-X11']::text[],false,'{"seq":7,"concept":"M6-2-u1-C6","difficulty":2,"kind":"mc","stem":"잘못 계산한 것을 찾으세요. ㉠ 6 ÷ ⟨2/5⟩ = 6 ÷ 2 × 5 = 15 ㉡ 10 ÷ ⟨3/5⟩ = 10 ÷ 5 × 3 = 6","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M6-2-u1-X11"},{"t":"둘 다 바르다","mis":"M6-2-u1-X11"}],"explanation":["(자연수)÷(진분수)는 분자로 나누고 분모를 곱해요.","㉠ 6 ÷ ⟨2/5⟩ = 6 ÷ 2 × 5 = 15로 바르게 계산했어요.","㉡은 분모 5로 나누고 분자 3을 곱했어요 — 10 ÷ ⟨3/5⟩ = 10 ÷ 3 × 5 = ⟨16 2/3⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_basic#8','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',2,'ox','auto','(자연수)÷(진분수)는 자연수를 분수의 분자로 나누고 분모를 곱하여 계산할 수 있어요.',ARRAY['M6-2-u1-X11']::text[],false,'{"seq":8,"concept":"M6-2-u1-C6","difficulty":2,"kind":"ox","stem":"(자연수)÷(진분수)는 자연수를 분수의 분자로 나누고 분모를 곱하여 계산할 수 있어요.","answer":"O","reason_options":[{"t":"4 ÷ ⟨2/3⟩ = 4 ÷ 2 × 3처럼 분자로 나누고 분모를 곱하면 1에 해당하는 양이 나와서","correct":true},{"t":"분모로 나누고 분자를 곱해야 1에 해당하는 양이 나와서","mis":"M6-2-u1-X11"}],"mis":"M6-2-u1-X11","explanation":["4 ÷ ⟨2/3⟩에서 ⟨2/3⟩시간을 2로 나누면 ⟨1/3⟩시간 — 4 ÷ 2 = 2.","1시간은 ⟨1/3⟩시간의 3배 — 2 × 3 = 6.","분자로 나누고 분모를 곱하는 것은 나누는 분수를 뒤집어 곱하는 것과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_basic#9','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',2,'sa','auto','혼자 사시는 어르신들께 반려 식물을 선물하는 행사에서 흙 15 kg을 화분 한 개에 ⟨3/20⟩ kg씩 나누어 담으려고 해요. 몇 개의 화분에 담을 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-2-u1-C6","difficulty":2,"kind":"sa","stem":"혼자 사시는 어르신들께 반려 식물을 선물하는 행사에서 흙 15 kg을 화분 한 개에 ⟨3/20⟩ kg씩 나누어 담으려고 해요. 몇 개의 화분에 담을 수 있나요? 숫자로 쓰세요.","answer":["100"],"explanation":["식은 15 ÷ ⟨3/20⟩이에요.","15 ÷ ⟨3/20⟩ = 15 × ⟨20/3⟩ = 100.","화분 100개에 나누어 담을 수 있어요."],"variant_rule":{"alt":[{"stem":"15 ÷ ⟨3/8⟩의 몫을 숫자로 쓰세요.","answer":["40"],"explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요.","15 ÷ ⟨3/8⟩ = 15 × ⟨8/3⟩ = 40.","몫은 40이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_basic#10','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',3,'mc','auto','수 카드 4와 5를 한 번씩만 이용하여 (자연수)÷(분모가 9인 진분수) 식을 만들려고 해요. 몫이 더 작은 나눗셈식은 어느 것인가요?',ARRAY['M6-2-u1-X16','M6-2-u1-X01']::text[],false,'{"seq":10,"concept":"M6-2-u1-C6","difficulty":3,"kind":"mc","stem":"수 카드 4와 5를 한 번씩만 이용하여 (자연수)÷(분모가 9인 진분수) 식을 만들려고 해요. 몫이 더 작은 나눗셈식은 어느 것인가요?","options":[{"t":"4 ÷ ⟨5/9⟩","correct":true},{"t":"5 ÷ ⟨4/9⟩","mis":"M6-2-u1-X16"},{"t":"⟨4/9⟩ ÷ 5","mis":"M6-2-u1-X01"},{"t":"⟨5/9⟩ ÷ 4","mis":"M6-2-u1-X01"}],"explanation":["4 ÷ ⟨5/9⟩ = 4 × ⟨9/5⟩ = ⟨36/5⟩ = ⟨7 1/5⟩.","5 ÷ ⟨4/9⟩ = 5 × ⟨9/4⟩ = ⟨45/4⟩ = ⟨11 1/4⟩.","나누어지는 수는 작게, 나누는 수는 크게 해야 몫이 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_challenge#1','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',2,'mc','auto','3 ÷ ⟨5/6⟩를 계산해 보세요.',ARRAY['M6-2-u1-X10','M6-2-u1-X01','M6-2-u1-X22']::text[],true,'{"seq":1,"concept":"M6-2-u1-C6","difficulty":2,"kind":"mc","stem":"3 ÷ ⟨5/6⟩를 계산해 보세요.","options":[{"t":"⟨3 3/5⟩","correct":true},{"t":"⟨2 1/2⟩","mis":"M6-2-u1-X10"},{"t":"⟨5/18⟩","mis":"M6-2-u1-X01"},{"t":"⟨3/5⟩","mis":"M6-2-u1-X22"}],"explanation":["분자 5로 나누고 분모 6을 곱해요 — 3 ÷ ⟨5/6⟩ = 3 ÷ 5 × 6 = ⟨3 3/5⟩.","곱셈으로 나타내면 3 × ⟨6/5⟩ = ⟨3 3/5⟩.","나누는 분수의 분모와 분자를 바꾸어 곱한 거예요."],"variant_rule":{"alt":[{"stem":"8 ÷ ⟨4/9⟩를 계산해 보세요.","options":[{"t":"18","correct":true},{"t":"⟨3 5/9⟩","mis":"M6-2-u1-X10"},{"t":"⟨1/18⟩","mis":"M6-2-u1-X01"},{"t":"2","mis":"M6-2-u1-X22"}],"explanation":["분자 4로 나누고 분모 9를 곱해요 — 8 ÷ ⟨4/9⟩ = 8 ÷ 4 × 9 = 18.","곱셈으로 나타내면 8 × ⟨9/4⟩ = 18.","나누는 분수의 분모와 분자를 바꾸어 곱한 거예요."]},{"stem":"9 ÷ ⟨6/7⟩을 계산해 보세요.","options":[{"t":"⟨10 1/2⟩","correct":true},{"t":"⟨7 5/7⟩","mis":"M6-2-u1-X10"},{"t":"⟨2/21⟩","mis":"M6-2-u1-X01"},{"t":"⟨1 1/2⟩","mis":"M6-2-u1-X22"}],"explanation":["분자 6으로 나누고 분모 7을 곱해요 — 9 ÷ ⟨6/7⟩ = 9 ÷ 6 × 7 = ⟨10 1/2⟩.","곱셈으로 나타내면 9 × ⟨7/6⟩ = ⟨10 1/2⟩.","나누는 분수의 분모와 분자를 바꾸어 곱한 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_challenge#2','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',2,'mc','auto','친구가 6 ÷ ⟨2/3⟩ = 6 ÷ 3 × 2 = 4라고 잘못 계산했어요. 바르게 계산한 몫은 얼마인가요?',ARRAY['M6-2-u1-X11','M6-2-u1-X01','M6-2-u1-X22']::text[],false,'{"seq":2,"concept":"M6-2-u1-C6","difficulty":2,"kind":"mc","stem":"친구가 6 ÷ ⟨2/3⟩ = 6 ÷ 3 × 2 = 4라고 잘못 계산했어요. 바르게 계산한 몫은 얼마인가요?","options":[{"t":"9","correct":true},{"t":"4","mis":"M6-2-u1-X11"},{"t":"⟨1/9⟩","mis":"M6-2-u1-X01"},{"t":"18","mis":"M6-2-u1-X22"}],"explanation":["분자 2로 나누고 분모 3을 곱해야 해요.","6 ÷ ⟨2/3⟩ = 6 ÷ 2 × 3 = 9.","친구는 분모로 나누고 분자를 곱했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_challenge#3','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',3,'mc','auto','몫이 가장 큰 것은 어느 것인가요?',ARRAY['M6-2-u1-X16']::text[],false,'{"seq":3,"concept":"M6-2-u1-C6","difficulty":3,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"7 ÷ ⟨3/7⟩","correct":true},{"t":"12 ÷ ⟨9/11⟩","mis":"M6-2-u1-X16"},{"t":"10 ÷ ⟨5/8⟩","mis":"M6-2-u1-X16"},{"t":"9 ÷ ⟨3/5⟩","mis":"M6-2-u1-X16"}],"explanation":["7 ÷ ⟨3/7⟩ = ⟨49/3⟩ = ⟨16 1/3⟩, 10 ÷ ⟨5/8⟩ = 16이에요.","9 ÷ ⟨3/5⟩ = 15, 12 ÷ ⟨9/11⟩ = ⟨44/3⟩ = ⟨14 2/3⟩예요.","나누어지는 수가 크다고 몫이 가장 큰 것은 아니에요 — 7 ÷ ⟨3/7⟩이 가장 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_challenge#4','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',3,'mc','auto','두 몫의 크기를 비교한 것으로 알맞은 것은 어느 것인가요? 8 ÷ ⟨3/4⟩ ○ 10 ÷ ⟨5/6⟩',ARRAY['M6-2-u1-X16','M6-2-u1-X11']::text[],false,'{"seq":4,"concept":"M6-2-u1-C6","difficulty":3,"kind":"mc","stem":"두 몫의 크기를 비교한 것으로 알맞은 것은 어느 것인가요? 8 ÷ ⟨3/4⟩ ○ 10 ÷ ⟨5/6⟩","options":[{"t":"8 ÷ ⟨3/4⟩ < 10 ÷ ⟨5/6⟩","correct":true},{"t":"8 ÷ ⟨3/4⟩ > 10 ÷ ⟨5/6⟩","mis":"M6-2-u1-X16"},{"t":"8 ÷ ⟨3/4⟩ = 10 ÷ ⟨5/6⟩","mis":"M6-2-u1-X11"}],"explanation":["8 ÷ ⟨3/4⟩ = 8 × ⟨4/3⟩ = ⟨32/3⟩ = ⟨10 2/3⟩.","10 ÷ ⟨5/6⟩ = 10 × ⟨6/5⟩ = 12.","⟨10 2/3⟩ < 12예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_challenge#5','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',3,'mc','auto','계산 결과가 자연수인 것은 어느 것인가요? ㉠ 6 ÷ ⟨4/11⟩ ㉡ 14 ÷ ⟨7/22⟩ ㉢ 8 ÷ ⟨5/8⟩',ARRAY['M6-2-u1-X11']::text[],false,'{"seq":5,"concept":"M6-2-u1-C6","difficulty":3,"kind":"mc","stem":"계산 결과가 자연수인 것은 어느 것인가요? ㉠ 6 ÷ ⟨4/11⟩ ㉡ 14 ÷ ⟨7/22⟩ ㉢ 8 ÷ ⟨5/8⟩","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M6-2-u1-X11"},{"t":"㉢","mis":"M6-2-u1-X11"}],"explanation":["㉠ 6 ÷ ⟨4/11⟩ = 6 × ⟨11/4⟩ = ⟨16 1/2⟩.","㉡ 14 ÷ ⟨7/22⟩ = 14 ÷ 7 × 22 = 44.","㉢ 8 ÷ ⟨5/8⟩ = 8 × ⟨8/5⟩ = ⟨12 4/5⟩ — 자연수인 것은 ㉡이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_challenge#6','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',3,'error','auto','자전거로 4 km를 가는 데 ⟨2/3⟩시간이 걸렸을 때 1시간 동안 갈 수 있는 거리를 구하는 방법을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u1-X11','M6-2-u1-X20']::text[],false,'{"seq":6,"concept":"M6-2-u1-C6","difficulty":3,"kind":"error","stem":"자전거로 4 km를 가는 데 ⟨2/3⟩시간이 걸렸을 때 1시간 동안 갈 수 있는 거리를 구하는 방법을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은호 — ⟨2/3⟩시간을 3으로 나누면 ⟨1/3⟩시간이니까 4를 3으로 나눠야 해.","correct":true,"mis_target":"M6-2-u1-X11"},{"t":"다인 — ⟨2/3⟩시간을 2로 나누어 ⟨1/3⟩시간 동안 간 거리를 구할 수 있어.","mis":"M6-2-u1-X20"},{"t":"로운 — ⟨1/3⟩시간 동안 간 거리를 3배 하면 1시간 동안의 거리야.","mis":"M6-2-u1-X20"}],"explanation":["⟨1/3⟩시간은 ⟨2/3⟩시간을 2로 나눈 것이에요 — 4 ÷ 2 = 2.","1시간은 ⟨1/3⟩시간의 3배 — 2 × 3 = 6.","은호는 분자 대신 분모로 나누려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_challenge#7','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',3,'sa','auto','□ < 9 ÷ ⟨7/11⟩에서 □ 안에 들어갈 수 있는 가장 큰 자연수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M6-2-u1-C6","difficulty":3,"kind":"sa","stem":"□ < 9 ÷ ⟨7/11⟩에서 □ 안에 들어갈 수 있는 가장 큰 자연수를 숫자로 쓰세요.","answer":["14"],"explanation":["9 ÷ ⟨7/11⟩ = 9 × ⟨11/7⟩ = ⟨99/7⟩ = ⟨14 1/7⟩.","□ < ⟨14 1/7⟩이에요.","□ 안에 들어갈 수 있는 가장 큰 자연수는 14예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_challenge#8','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',4,'essay','teacher','자전거로 4 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. 이중수직선을 떠올려 1시간 동안 갈 수 있는 거리를 두 단계로 구하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u1-C6","difficulty":4,"kind":"essay","stem":"자전거로 4 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. 이중수직선을 떠올려 1시간 동안 갈 수 있는 거리를 두 단계로 구하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: ① ⟨2/3⟩시간을 2로 나누면 ⟨1/3⟩시간이므로 거리도 2로 나누어 ⟨1/3⟩시간 동안 4 ÷ 2 = 2 km를 간다. ② 1시간은 ⟨1/3⟩시간의 3배이므로 2 × 3 = 6 km를 간다. 그래서 4 ÷ ⟨2/3⟩ = 4 ÷ 2 × 3 = 6이다.","scoring_points":["⟨1/3⟩시간 동안의 거리 2 km를 구했는가","3배 하여 6 km를 구했는가","4 ÷ ⟨2/3⟩ = 4 ÷ 2 × 3으로 정리했는가"]},"explanation":["⟨1/3⟩시간 동안 4 ÷ 2 = 2 km예요.","1시간 동안 2 × 3 = 6 km예요.","4 ÷ ⟨2/3⟩ = 4 ÷ 2 × 3 = 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_challenge#9','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',4,'essay','teacher','수 카드 4와 5를 한 번씩만 써서 몫이 더 작은 (자연수)÷(분모가 9인 진분수) 식을 만들고, 그렇게 만든 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u1-C6","difficulty":4,"kind":"essay","stem":"수 카드 4와 5를 한 번씩만 써서 몫이 더 작은 (자연수)÷(분모가 9인 진분수) 식을 만들고, 그렇게 만든 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 4 ÷ ⟨5/9⟩ = 4 × ⟨9/5⟩ = ⟨36/5⟩ = ⟨7 1/5⟩이고 5 ÷ ⟨4/9⟩ = 5 × ⟨9/4⟩ = ⟨45/4⟩ = ⟨11 1/4⟩이다. 나누어지는 수가 작고 나누는 수가 클수록 몫이 작아지므로 4 ÷ ⟨5/9⟩의 몫이 더 작다.","scoring_points":["4 ÷ ⟨5/9⟩를 만들었는가","두 식의 몫 ⟨7 1/5⟩, ⟨11 1/4⟩을 비교했는가","나누어지는 수는 작게, 나누는 수는 크게 하는 까닭을 썼는가"]},"explanation":["4 ÷ ⟨5/9⟩ = ⟨7 1/5⟩이에요.","5 ÷ ⟨4/9⟩ = ⟨11 1/4⟩이에요.","몫을 작게 하려면 작은 수를 큰 분수로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L06_challenge#10','math',6,2,'u1','L06','tb_g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',4,'mc','auto','9 ÷ ⟨3/5⟩ = 9 ÷ ㉠ × ㉡ = ㉢이에요. ㉢ − ㉠ + ㉡의 값은 얼마인가요?',ARRAY['M6-2-u1-X11','M6-2-u1-X20']::text[],false,'{"seq":10,"concept":"M6-2-u1-C6","difficulty":4,"kind":"mc","stem":"9 ÷ ⟨3/5⟩ = 9 ÷ ㉠ × ㉡ = ㉢이에요. ㉢ − ㉠ + ㉡의 값은 얼마인가요?","options":[{"t":"17","correct":true},{"t":"13","mis":"M6-2-u1-X11"},{"t":"23","mis":"M6-2-u1-X20"},{"t":"7","mis":"M6-2-u1-X20"}],"explanation":["분자로 나누고 분모를 곱해요 — 9 ÷ ⟨3/5⟩ = 9 ÷ 3 × 5 = 15.","㉠ = 3, ㉡ = 5, ㉢ = 15예요.","15 − 3 + 5 = 17이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_basic#1','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_basic','lesson_basic','M6-2-u1-C7',1,'mc','auto','다양한 음식 문화를 체험하려고 쌀 ⟨2/5⟩ kg을 빈 통에 담았더니 통의 ⟨3/4⟩이 찼어요. 한 통을 가득 채울 수 있는 쌀의 양을 구하는 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X10','M6-2-u1-X03']::text[],false,'{"seq":1,"concept":"M6-2-u1-C7","difficulty":1,"kind":"mc","stem":"다양한 음식 문화를 체험하려고 쌀 ⟨2/5⟩ kg을 빈 통에 담았더니 통의 ⟨3/4⟩이 찼어요. 한 통을 가득 채울 수 있는 쌀의 양을 구하는 식은 어느 것인가요?","options":[{"t":"⟨2/5⟩ ÷ ⟨3/4⟩","correct":true},{"t":"⟨3/4⟩ ÷ ⟨2/5⟩","mis":"M6-2-u1-X01"},{"t":"⟨2/5⟩ × ⟨3/4⟩","mis":"M6-2-u1-X10"},{"t":"⟨3/4⟩ − ⟨2/5⟩","mis":"M6-2-u1-X03"}],"explanation":["쌀 4 kg으로 같은 크기의 통 2개를 채웠다면 4 ÷ 2로 구해요.","쌀의 양을 통의 수로 나누는 거예요.","통의 수가 ⟨3/4⟩이니 식은 ⟨2/5⟩ ÷ ⟨3/4⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_basic#2','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_basic','lesson_basic','M6-2-u1-C7',1,'mc','auto','쌀 ⟨2/5⟩ kg으로 통의 ⟨3/4⟩을 채웠어요. 통의 ⟨1/4⟩을 채울 수 있는 쌀의 양은 몇 kg인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X22','M6-2-u1-X18']::text[],false,'{"seq":2,"concept":"M6-2-u1-C7","difficulty":1,"kind":"mc","stem":"쌀 ⟨2/5⟩ kg으로 통의 ⟨3/4⟩을 채웠어요. 통의 ⟨1/4⟩을 채울 수 있는 쌀의 양은 몇 kg인가요?","options":[{"t":"⟨2/15⟩","correct":true},{"t":"⟨1 1/5⟩","mis":"M6-2-u1-X10"},{"t":"⟨2/5⟩","mis":"M6-2-u1-X22"},{"t":"⟨8/15⟩","mis":"M6-2-u1-X18"}],"explanation":["통의 ⟨1/4⟩은 통의 ⟨3/4⟩을 3으로 나눈 것이에요.","쌀의 양도 3으로 나눠요 — ⟨2/5⟩ ÷ 3 = ⟨2/5⟩ × ⟨1/3⟩ = ⟨2/15⟩.","통의 ⟨1/4⟩을 채우는 쌀은 ⟨2/15⟩ kg이에요(아직 한 통이 아니에요)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_basic#3','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_basic','lesson_basic','M6-2-u1-C7',1,'mc','auto','⟨1/6⟩ ÷ ⟨4/7⟩를 계산해 보세요.',ARRAY['M6-2-u1-X10','M6-2-u1-X12']::text[],true,'{"seq":3,"concept":"M6-2-u1-C7","difficulty":1,"kind":"mc","stem":"⟨1/6⟩ ÷ ⟨4/7⟩를 계산해 보세요.","options":[{"t":"⟨7/24⟩","correct":true},{"t":"⟨2/21⟩","mis":"M6-2-u1-X10"},{"t":"⟨3 3/7⟩","mis":"M6-2-u1-X12"},{"t":"⟨10 1/2⟩","mis":"M6-2-u1-X12"}],"explanation":["나눗셈을 곱셈으로 나타내요 — ⟨1/6⟩ ÷ ⟨4/7⟩ = ⟨1/6⟩ × ⟨7/4⟩.","⟨1/6⟩ × ⟨7/4⟩ = ⟨7/24⟩.","나누는 분수만 분모와 분자를 바꾸고, 나누어지는 분수는 그대로 둬요."],"variant_rule":{"alt":[{"stem":"⟨3/10⟩ ÷ ⟨5/8⟩를 계산해 보세요.","options":[{"t":"⟨12/25⟩","correct":true},{"t":"⟨3/16⟩","mis":"M6-2-u1-X10"},{"t":"⟨2 1/12⟩","mis":"M6-2-u1-X12"},{"t":"⟨5 1/3⟩","mis":"M6-2-u1-X12"}],"explanation":["나눗셈을 곱셈으로 나타내요 — ⟨3/10⟩ ÷ ⟨5/8⟩ = ⟨3/10⟩ × ⟨8/5⟩.","⟨3/10⟩ × ⟨8/5⟩ = ⟨12/25⟩.","나누는 분수만 분모와 분자를 바꾸고, 나누어지는 분수는 그대로 둬요."]},{"stem":"⟨4/5⟩ ÷ ⟨2/11⟩를 계산해 보세요.","options":[{"t":"⟨4 2/5⟩","correct":true},{"t":"⟨8/55⟩","mis":"M6-2-u1-X10"},{"t":"⟨5/22⟩","mis":"M6-2-u1-X12"},{"t":"⟨6 7/8⟩","mis":"M6-2-u1-X12"}],"explanation":["나눗셈을 곱셈으로 나타내요 — ⟨4/5⟩ ÷ ⟨2/11⟩ = ⟨4/5⟩ × ⟨11/2⟩.","⟨4/5⟩ × ⟨11/2⟩ = ⟨4 2/5⟩.","나누는 분수만 분모와 분자를 바꾸고, 나누어지는 분수는 그대로 둬요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_basic#4','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_basic','lesson_basic','M6-2-u1-C7',1,'mc','auto','⟨3/7⟩ ÷ ⟨8/9⟩을 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u1-X12','M6-2-u1-X10']::text[],true,'{"seq":4,"concept":"M6-2-u1-C7","difficulty":1,"kind":"mc","stem":"⟨3/7⟩ ÷ ⟨8/9⟩을 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨3/7⟩ × ⟨9/8⟩","correct":true},{"t":"⟨7/3⟩ × ⟨8/9⟩","mis":"M6-2-u1-X12"},{"t":"⟨3/7⟩ × ⟨8/9⟩","mis":"M6-2-u1-X10"},{"t":"⟨7/3⟩ × ⟨9/8⟩","mis":"M6-2-u1-X12"}],"explanation":["나눗셈을 곱셈으로 나타낼 때는 나누는 분수의 분모와 분자를 바꿔요.","⟨3/7⟩ ÷ ⟨8/9⟩ = ⟨3/7⟩ × ⟨9/8⟩ = ⟨27/56⟩.","나누어지는 분수 ⟨3/7⟩은 그대로 둬요."],"variant_rule":{"alt":[{"stem":"⟨5/7⟩ ÷ ⟨2/9⟩를 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨5/7⟩ × ⟨9/2⟩","correct":true},{"t":"⟨7/5⟩ × ⟨2/9⟩","mis":"M6-2-u1-X12"},{"t":"⟨5/7⟩ × ⟨2/9⟩","mis":"M6-2-u1-X10"},{"t":"⟨7/5⟩ × ⟨9/2⟩","mis":"M6-2-u1-X12"}],"explanation":["나누는 분수 ⟨2/9⟩의 분모와 분자를 바꿔요.","⟨5/7⟩ ÷ ⟨2/9⟩ = ⟨5/7⟩ × ⟨9/2⟩ = ⟨45/14⟩ = ⟨3 3/14⟩.","나누어지는 분수는 그대로 둬요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_basic#5','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_basic','lesson_basic','M6-2-u1-C7',2,'mc','auto','쌀 ⟨2/5⟩ kg으로 통의 ⟨3/4⟩을 채웠어요. 한 통을 가득 채울 수 있는 쌀은 몇 kg인가요?',ARRAY['M6-2-u1-X22','M6-2-u1-X10','M6-2-u1-X01']::text[],false,'{"seq":5,"concept":"M6-2-u1-C7","difficulty":2,"kind":"mc","stem":"쌀 ⟨2/5⟩ kg으로 통의 ⟨3/4⟩을 채웠어요. 한 통을 가득 채울 수 있는 쌀은 몇 kg인가요?","options":[{"t":"⟨8/15⟩","correct":true},{"t":"⟨2/15⟩","mis":"M6-2-u1-X22"},{"t":"⟨3/10⟩","mis":"M6-2-u1-X10"},{"t":"⟨1 7/8⟩","mis":"M6-2-u1-X01"}],"explanation":["통의 ⟨1/4⟩을 채우는 쌀은 ⟨2/5⟩ ÷ 3 = ⟨2/15⟩ kg이에요.","1은 ⟨1/4⟩의 4배 — ⟨2/15⟩ × 4 = ⟨8/15⟩.","⟨2/5⟩ ÷ ⟨3/4⟩ = ⟨2/5⟩ × ⟨4/3⟩ = ⟨8/15⟩, 한 통은 ⟨8/15⟩ kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_basic#6','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_basic','lesson_basic','M6-2-u1-C7',2,'ox','auto','친구가 ⟨8/15⟩ ÷ ⟨4/5⟩ = ⟨8/15⟩ × ⟨4/5⟩ = ⟨32/75⟩라고 계산했어요. 바르게 계산했나요?',ARRAY['M6-2-u1-X10']::text[],false,'{"seq":6,"concept":"M6-2-u1-C7","difficulty":2,"kind":"ox","stem":"친구가 ⟨8/15⟩ ÷ ⟨4/5⟩ = ⟨8/15⟩ × ⟨4/5⟩ = ⟨32/75⟩라고 계산했어요. 바르게 계산했나요?","answer":"X","reason_options":[{"t":"나누는 분수 ⟨4/5⟩의 분모와 분자를 바꾸어 ⟨5/4⟩를 곱해야 해서","correct":true},{"t":"나눗셈을 곱셈으로 바꿀 때는 두 분수를 그대로 곱하면 되어서","mis":"M6-2-u1-X10"}],"mis":"M6-2-u1-X10","explanation":["나누는 분수의 분모와 분자를 바꾸지 않았어요.","⟨8/15⟩ ÷ ⟨4/5⟩ = ⟨8/15⟩ × ⟨5/4⟩ = ⟨2/3⟩.","바른 몫은 ⟨2/3⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_basic#7','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_basic','lesson_basic','M6-2-u1-C7',2,'match','auto','계산 결과에 맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"M6-2-u1-C7","difficulty":2,"kind":"match","stem":"계산 결과에 맞게 이으세요.","pairs":[{"l":"⟨7/10⟩ ÷ ⟨4/5⟩","r":"⟨7/8⟩"},{"l":"⟨12/13⟩ ÷ ⟨2/7⟩","r":"⟨3 3/13⟩"},{"l":"⟨5/12⟩ ÷ ⟨3/4⟩","r":"⟨5/9⟩"},{"l":"⟨14/15⟩ ÷ ⟨4/5⟩","r":"⟨1 1/6⟩"}],"mis":"M6-2-u1-X10","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요.","⟨7/10⟩ × ⟨5/4⟩ = ⟨7/8⟩, ⟨12/13⟩ × ⟨7/2⟩ = ⟨3 3/13⟩.","⟨5/12⟩ × ⟨4/3⟩ = ⟨5/9⟩, ⟨14/15⟩ × ⟨5/4⟩ = ⟨1 1/6⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_basic#8','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_basic','lesson_basic','M6-2-u1-C7',2,'mc','auto','⟨5/8⟩ ÷ ⟨5/9⟩를 계산해 보세요.',ARRAY['M6-2-u1-X10','M6-2-u1-X12']::text[],true,'{"seq":8,"concept":"M6-2-u1-C7","difficulty":2,"kind":"mc","stem":"⟨5/8⟩ ÷ ⟨5/9⟩를 계산해 보세요.","options":[{"t":"⟨1 1/8⟩","correct":true},{"t":"⟨25/72⟩","mis":"M6-2-u1-X10"},{"t":"⟨8/9⟩","mis":"M6-2-u1-X12"},{"t":"⟨2 22/25⟩","mis":"M6-2-u1-X12"}],"explanation":["나눗셈을 곱셈으로 나타내요 — ⟨5/8⟩ ÷ ⟨5/9⟩ = ⟨5/8⟩ × ⟨9/5⟩.","⟨5/8⟩ × ⟨9/5⟩ = ⟨1 1/8⟩.","나누는 분수만 분모와 분자를 바꾸고, 나누어지는 분수는 그대로 둬요."],"variant_rule":{"alt":[{"stem":"⟨4/7⟩ ÷ ⟨11/14⟩을 계산해 보세요.","options":[{"t":"⟨8/11⟩","correct":true},{"t":"⟨22/49⟩","mis":"M6-2-u1-X10"},{"t":"⟨1 3/8⟩","mis":"M6-2-u1-X12"},{"t":"⟨2 5/22⟩","mis":"M6-2-u1-X12"}],"explanation":["나눗셈을 곱셈으로 나타내요 — ⟨4/7⟩ ÷ ⟨11/14⟩ = ⟨4/7⟩ × ⟨14/11⟩.","⟨4/7⟩ × ⟨14/11⟩ = ⟨8/11⟩.","나누는 분수만 분모와 분자를 바꾸고, 나누어지는 분수는 그대로 둬요."]},{"stem":"⟨5/12⟩ ÷ ⟨7/18⟩을 계산해 보세요.","options":[{"t":"⟨1 1/14⟩","correct":true},{"t":"⟨35/216⟩","mis":"M6-2-u1-X10"},{"t":"⟨14/15⟩","mis":"M6-2-u1-X12"},{"t":"⟨6 6/35⟩","mis":"M6-2-u1-X12"}],"explanation":["나눗셈을 곱셈으로 나타내요 — ⟨5/12⟩ ÷ ⟨7/18⟩ = ⟨5/12⟩ × ⟨18/7⟩.","⟨5/12⟩ × ⟨18/7⟩ = ⟨1 1/14⟩.","나누는 분수만 분모와 분자를 바꾸고, 나누어지는 분수는 그대로 둬요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_basic#9','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_basic','lesson_basic','M6-2-u1-C7',2,'mc','auto','효준이가 딸기 ⟨7/9⟩ kg을 따는 데 ⟨2/5⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 딸 수 있는 딸기는 몇 kg인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X22','M6-2-u1-X01']::text[],true,'{"seq":9,"concept":"M6-2-u1-C7","difficulty":2,"kind":"mc","stem":"효준이가 딸기 ⟨7/9⟩ kg을 따는 데 ⟨2/5⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 딸 수 있는 딸기는 몇 kg인가요?","options":[{"t":"⟨1 17/18⟩","correct":true},{"t":"⟨14/45⟩","mis":"M6-2-u1-X10"},{"t":"⟨7/18⟩","mis":"M6-2-u1-X22"},{"t":"⟨18/35⟩","mis":"M6-2-u1-X01"}],"explanation":["⟨1/5⟩시간 동안 ⟨7/9⟩ ÷ 2 = ⟨7/18⟩ kg을 따요.","1시간은 ⟨1/5⟩시간의 5배 — ⟨7/18⟩ × 5 = ⟨35/18⟩.","⟨7/9⟩ ÷ ⟨2/5⟩ = ⟨7/9⟩ × ⟨5/2⟩ = ⟨1 17/18⟩ kg이에요."],"variant_rule":{"alt":[{"stem":"3 km를 걷는 데 ⟨3/4⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 몇 km를 걸을 수 있나요?","options":[{"t":"4","correct":true},{"t":"⟨2 1/4⟩","mis":"M6-2-u1-X10"},{"t":"1","mis":"M6-2-u1-X22"},{"t":"⟨1/4⟩","mis":"M6-2-u1-X01"}],"explanation":["⟨1/4⟩시간 동안 3 ÷ 3 = 1 km를 걸어요.","1시간은 ⟨1/4⟩시간의 4배 — 1 × 4 = 4.","3 ÷ ⟨3/4⟩ = 3 × ⟨4/3⟩ = 4, 1시간 동안 4 km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_basic#10','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_basic','lesson_basic','M6-2-u1-C7',3,'mc','auto','계산 결과에 맞는 글자를 찾아 낱말을 완성해요. ⟨7/10⟩ ÷ ⟨4/5⟩ → 포, ⟨12/13⟩ ÷ ⟨2/7⟩ → 교, ⟨5/12⟩ ÷ ⟨3/4⟩ → 관, ⟨14/15⟩ ÷ ⟨4/5⟩ → 지예요. 계산 결과가 ⟨5/9⟩, ⟨7/8⟩, ⟨1 1/6⟩, ⟨3 3/13⟩ 순서일 때 완성한 낱말은 무엇인가요?',ARRAY['M6-2-u1-X20','M6-2-u1-X10']::text[],false,'{"seq":10,"concept":"M6-2-u1-C7","difficulty":3,"kind":"mc","stem":"계산 결과에 맞는 글자를 찾아 낱말을 완성해요. ⟨7/10⟩ ÷ ⟨4/5⟩ → 포, ⟨12/13⟩ ÷ ⟨2/7⟩ → 교, ⟨5/12⟩ ÷ ⟨3/4⟩ → 관, ⟨14/15⟩ ÷ ⟨4/5⟩ → 지예요. 계산 결과가 ⟨5/9⟩, ⟨7/8⟩, ⟨1 1/6⟩, ⟨3 3/13⟩ 순서일 때 완성한 낱말은 무엇인가요?","options":[{"t":"관포지교","correct":true},{"t":"포교관지","mis":"M6-2-u1-X20"},{"t":"교관포지","mis":"M6-2-u1-X10"},{"t":"지포관교","mis":"M6-2-u1-X10"}],"explanation":["⟨5/12⟩ ÷ ⟨3/4⟩ = ⟨5/9⟩ 관, ⟨7/10⟩ ÷ ⟨4/5⟩ = ⟨7/8⟩ 포예요.","⟨14/15⟩ ÷ ⟨4/5⟩ = ⟨1 1/6⟩ 지, ⟨12/13⟩ ÷ ⟨2/7⟩ = ⟨3 3/13⟩ 교예요.","관포지교는 우정이 아주 돈독한 친구 관계를 뜻하는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_challenge#1','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',2,'mc','auto','⟨4/9⟩ ÷ ⟨5/13⟩를 계산해 보세요.',ARRAY['M6-2-u1-X10','M6-2-u1-X12']::text[],true,'{"seq":1,"concept":"M6-2-u1-C7","difficulty":2,"kind":"mc","stem":"⟨4/9⟩ ÷ ⟨5/13⟩를 계산해 보세요.","options":[{"t":"⟨1 7/45⟩","correct":true},{"t":"⟨20/117⟩","mis":"M6-2-u1-X10"},{"t":"⟨45/52⟩","mis":"M6-2-u1-X12"},{"t":"⟨5 17/20⟩","mis":"M6-2-u1-X12"}],"explanation":["나눗셈을 곱셈으로 나타내요 — ⟨4/9⟩ ÷ ⟨5/13⟩ = ⟨4/9⟩ × ⟨13/5⟩.","⟨4/9⟩ × ⟨13/5⟩ = ⟨1 7/45⟩.","나누는 분수만 분모와 분자를 바꾸고, 나누어지는 분수는 그대로 둬요."],"variant_rule":{"alt":[{"stem":"⟨5/11⟩ ÷ ⟨6/7⟩을 계산해 보세요.","options":[{"t":"⟨35/66⟩","correct":true},{"t":"⟨30/77⟩","mis":"M6-2-u1-X10"},{"t":"⟨1 31/35⟩","mis":"M6-2-u1-X12"},{"t":"⟨2 17/30⟩","mis":"M6-2-u1-X12"}],"explanation":["나눗셈을 곱셈으로 나타내요 — ⟨5/11⟩ ÷ ⟨6/7⟩ = ⟨5/11⟩ × ⟨7/6⟩.","⟨5/11⟩ × ⟨7/6⟩ = ⟨35/66⟩.","나누는 분수만 분모와 분자를 바꾸고, 나누어지는 분수는 그대로 둬요."]},{"stem":"⟨3/8⟩ ÷ ⟨5/7⟩를 계산해 보세요.","options":[{"t":"⟨21/40⟩","correct":true},{"t":"⟨15/56⟩","mis":"M6-2-u1-X10"},{"t":"⟨1 19/21⟩","mis":"M6-2-u1-X12"},{"t":"⟨3 11/15⟩","mis":"M6-2-u1-X12"}],"explanation":["나눗셈을 곱셈으로 나타내요 — ⟨3/8⟩ ÷ ⟨5/7⟩ = ⟨3/8⟩ × ⟨7/5⟩.","⟨3/8⟩ × ⟨7/5⟩ = ⟨21/40⟩.","나누는 분수만 분모와 분자를 바꾸고, 나누어지는 분수는 그대로 둬요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_challenge#2','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',2,'sa','auto','⟨2/5⟩ ÷ ⟨3/4⟩ = ⟨2/5⟩ × ⟨□/3⟩이에요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-2-u1-C7","difficulty":2,"kind":"sa","stem":"⟨2/5⟩ ÷ ⟨3/4⟩ = ⟨2/5⟩ × ⟨□/3⟩이에요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["4"],"explanation":["⟨2/5⟩ ÷ ⟨3/4⟩ = ⟨2/5⟩ ÷ 3 × 4 = ⟨2/5⟩ × ⟨1/3⟩ × 4예요.","⟨1/3⟩ × 4 = ⟨4/3⟩라 ⟨2/5⟩ × ⟨4/3⟩예요.","그래서 □는 4예요."],"variant_rule":{"alt":[{"stem":"⟨4/7⟩ ÷ ⟨11/14⟩ = ⟨4/7⟩ × ⟨□/11⟩이에요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["14"],"explanation":["나누는 분수 ⟨11/14⟩의 분모와 분자를 바꿔요.","⟨4/7⟩ ÷ ⟨11/14⟩ = ⟨4/7⟩ × ⟨14/11⟩ = ⟨8/11⟩.","그래서 □는 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_challenge#3','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',3,'error','auto','두 친구가 계산한 것을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요? (아진: ⟨8/11⟩ ÷ ⟨2/3⟩ = ⟨8/11⟩ × ⟨3/2⟩ = ⟨1 1/11⟩, 세호: ⟨3/4⟩ ÷ ⟨8/9⟩ = ⟨3/4⟩ × ⟨8/9⟩ = ⟨2/3⟩)',ARRAY['M6-2-u1-X10','M6-2-u1-X20']::text[],false,'{"seq":3,"concept":"M6-2-u1-C7","difficulty":3,"kind":"error","stem":"두 친구가 계산한 것을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요? (아진: ⟨8/11⟩ ÷ ⟨2/3⟩ = ⟨8/11⟩ × ⟨3/2⟩ = ⟨1 1/11⟩, 세호: ⟨3/4⟩ ÷ ⟨8/9⟩ = ⟨3/4⟩ × ⟨8/9⟩ = ⟨2/3⟩)","options":[{"t":"하준 — 세호는 바르게 계산했어. 몫이 ⟨2/3⟩야.","correct":true,"mis_target":"M6-2-u1-X10"},{"t":"유진 — 아진이는 나누는 분수의 분모와 분자를 바꾸어 곱했어.","mis":"M6-2-u1-X20"},{"t":"태오 — 세호는 ⟨3/4⟩ × ⟨9/8⟩를 계산했어야 해.","mis":"M6-2-u1-X20"}],"explanation":["아진: ⟨8/11⟩ × ⟨3/2⟩ = ⟨12/11⟩ = ⟨1 1/11⟩로 바르게 계산했어요.","세호는 나누는 분수를 바꾸지 않았어요 — ⟨3/4⟩ ÷ ⟨8/9⟩ = ⟨3/4⟩ × ⟨9/8⟩ = ⟨27/32⟩.","하준이는 세호의 잘못을 보지 못했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_challenge#4','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',3,'mc','auto','⟨2/5⟩ ÷ ⟨3/4⟩을 ⟨2/5⟩ ÷ 3 × 4로 계산하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u1-X11','M6-2-u1-X22','M6-2-u1-X10']::text[],false,'{"seq":4,"concept":"M6-2-u1-C7","difficulty":3,"kind":"mc","stem":"⟨2/5⟩ ÷ ⟨3/4⟩을 ⟨2/5⟩ ÷ 3 × 4로 계산하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"통의 ⟨3/4⟩을 3으로 나누면 ⟨1/4⟩이고, 1은 ⟨1/4⟩의 4배라서","correct":true},{"t":"통의 ⟨3/4⟩을 4로 나누고 3배 하면 1이라서","mis":"M6-2-u1-X11"},{"t":"⟨3/4⟩을 3으로 나누면 1이 되어서","mis":"M6-2-u1-X22"},{"t":"⟨2/5⟩와 ⟨3/4⟩을 곱해야 해서","mis":"M6-2-u1-X10"}],"explanation":["⟨2/5⟩ kg으로 통의 ⟨3/4⟩을 채웠어요.","÷ 3으로 통의 ⟨1/4⟩, × 4로 한 통이 돼요.","그래서 ⟨2/5⟩ ÷ ⟨3/4⟩ = ⟨2/5⟩ ÷ 3 × 4 = ⟨8/15⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_challenge#5','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',3,'mc','auto','친구가 ⟨7/15⟩ ÷ ⟨10/21⟩을 앞의 분수를 뒤집어 ⟨15/7⟩ × ⟨10/21⟩으로 계산했어요. 바르게 계산한 몫은 얼마인가요?',ARRAY['M6-2-u1-X12','M6-2-u1-X10','M6-2-u1-X06']::text[],false,'{"seq":5,"concept":"M6-2-u1-C7","difficulty":3,"kind":"mc","stem":"친구가 ⟨7/15⟩ ÷ ⟨10/21⟩을 앞의 분수를 뒤집어 ⟨15/7⟩ × ⟨10/21⟩으로 계산했어요. 바르게 계산한 몫은 얼마인가요?","options":[{"t":"⟨49/50⟩","correct":true},{"t":"⟨1 1/49⟩","mis":"M6-2-u1-X12"},{"t":"⟨2/9⟩","mis":"M6-2-u1-X10"},{"t":"⟨7/10⟩","mis":"M6-2-u1-X06"}],"explanation":["뒤집는 것은 나누는 분수 하나뿐이에요.","⟨7/15⟩ ÷ ⟨10/21⟩ = ⟨7/15⟩ × ⟨21/10⟩ = ⟨49/50⟩.","나누어지는 분수 ⟨7/15⟩은 그대로 둬요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_challenge#6','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',3,'mc','auto','⟨4/9⟩ ÷ ⟨6/7⟩을 계산해 보세요.',ARRAY['M6-2-u1-X10','M6-2-u1-X12']::text[],true,'{"seq":6,"concept":"M6-2-u1-C7","difficulty":3,"kind":"mc","stem":"⟨4/9⟩ ÷ ⟨6/7⟩을 계산해 보세요.","options":[{"t":"⟨14/27⟩","correct":true},{"t":"⟨8/21⟩","mis":"M6-2-u1-X10"},{"t":"⟨1 13/14⟩","mis":"M6-2-u1-X12"},{"t":"⟨2 5/8⟩","mis":"M6-2-u1-X12"}],"explanation":["나눗셈을 곱셈으로 나타내요 — ⟨4/9⟩ ÷ ⟨6/7⟩ = ⟨4/9⟩ × ⟨7/6⟩.","⟨4/9⟩ × ⟨7/6⟩ = ⟨14/27⟩.","나누는 분수만 분모와 분자를 바꾸고, 나누어지는 분수는 그대로 둬요."],"variant_rule":{"alt":[{"stem":"⟨7/8⟩ ÷ ⟨2/3⟩를 계산해 보세요.","options":[{"t":"⟨1 5/16⟩","correct":true},{"t":"⟨7/12⟩","mis":"M6-2-u1-X10"},{"t":"⟨16/21⟩","mis":"M6-2-u1-X12"},{"t":"⟨1 5/7⟩","mis":"M6-2-u1-X12"}],"explanation":["나눗셈을 곱셈으로 나타내요 — ⟨7/8⟩ ÷ ⟨2/3⟩ = ⟨7/8⟩ × ⟨3/2⟩.","⟨7/8⟩ × ⟨3/2⟩ = ⟨1 5/16⟩.","나누는 분수만 분모와 분자를 바꾸고, 나누어지는 분수는 그대로 둬요."]},{"stem":"⟨4/5⟩ ÷ ⟨5/6⟩를 계산해 보세요.","options":[{"t":"⟨24/25⟩","correct":true},{"t":"⟨2/3⟩","mis":"M6-2-u1-X10"},{"t":"⟨1 1/24⟩","mis":"M6-2-u1-X12"},{"t":"⟨1 1/2⟩","mis":"M6-2-u1-X12"}],"explanation":["나눗셈을 곱셈으로 나타내요 — ⟨4/5⟩ ÷ ⟨5/6⟩ = ⟨4/5⟩ × ⟨6/5⟩.","⟨4/5⟩ × ⟨6/5⟩ = ⟨24/25⟩.","나누는 분수만 분모와 분자를 바꾸고, 나누어지는 분수는 그대로 둬요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_challenge#7','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',3,'mc','auto','주사위를 던져 (진분수)÷(진분수)를 만드는 놀이에서 몫이 더 큰 문제를 만든 사람이 1점을 얻어요. ⟨5/8⟩ ÷ ⟨5/9⟩와 ⟨1/6⟩ ÷ ⟨4/7⟩ 가운데 몫이 더 큰 것은 어느 것인가요?',ARRAY['M6-2-u1-X16','M6-2-u1-X10']::text[],false,'{"seq":7,"concept":"M6-2-u1-C7","difficulty":3,"kind":"mc","stem":"주사위를 던져 (진분수)÷(진분수)를 만드는 놀이에서 몫이 더 큰 문제를 만든 사람이 1점을 얻어요. ⟨5/8⟩ ÷ ⟨5/9⟩와 ⟨1/6⟩ ÷ ⟨4/7⟩ 가운데 몫이 더 큰 것은 어느 것인가요?","options":[{"t":"⟨5/8⟩ ÷ ⟨5/9⟩","correct":true},{"t":"⟨1/6⟩ ÷ ⟨4/7⟩","mis":"M6-2-u1-X16"},{"t":"두 몫이 같다","mis":"M6-2-u1-X10"}],"explanation":["⟨5/8⟩ ÷ ⟨5/9⟩ = ⟨5/8⟩ × ⟨9/5⟩ = ⟨1 1/8⟩.","⟨1/6⟩ ÷ ⟨4/7⟩ = ⟨1/6⟩ × ⟨7/4⟩ = ⟨7/24⟩.","⟨1 1/8⟩이 더 커서 ⟨5/8⟩ ÷ ⟨5/9⟩를 만든 사람이 1점을 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_challenge#8','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',4,'essay','teacher','친구가 ⟨8/15⟩ ÷ ⟨4/5⟩ = ⟨8/15⟩ × ⟨4/5⟩ = ⟨32/75⟩라고 계산했어요. 잘못 계산한 이유를 쓰고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u1-C7","difficulty":4,"kind":"essay","stem":"친구가 ⟨8/15⟩ ÷ ⟨4/5⟩ = ⟨8/15⟩ × ⟨4/5⟩ = ⟨32/75⟩라고 계산했어요. 잘못 계산한 이유를 쓰고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 나눗셈을 곱셈으로 나타낼 때 나누는 분수의 분모와 분자를 바꾸지 않았다. ⟨8/15⟩ ÷ ⟨4/5⟩ = ⟨8/15⟩ × ⟨5/4⟩ = ⟨2/3⟩이다.","scoring_points":["나누는 분수를 바꾸지 않은 것을 이유로 썼는가","⟨8/15⟩ × ⟨5/4⟩로 고쳤는가","⟨2/3⟩를 구했는가"]},"explanation":["나누는 분수 ⟨4/5⟩의 분모와 분자를 바꿔야 해요.","⟨8/15⟩ ÷ ⟨4/5⟩ = ⟨8/15⟩ × ⟨5/4⟩ = ⟨2/3⟩.","나누어지는 분수는 그대로 둬요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_challenge#9','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',4,'essay','teacher','쌀 ⟨2/5⟩ kg으로 통의 ⟨3/4⟩을 채웠어요. 한 통을 가득 채우는 쌀의 양을 이중수직선의 두 단계로 구하고, 이것이 ⟨2/5⟩ × ⟨4/3⟩와 같은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u1-C7","difficulty":4,"kind":"essay","stem":"쌀 ⟨2/5⟩ kg으로 통의 ⟨3/4⟩을 채웠어요. 한 통을 가득 채우는 쌀의 양을 이중수직선의 두 단계로 구하고, 이것이 ⟨2/5⟩ × ⟨4/3⟩와 같은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 통의 ⟨1/4⟩은 ⟨3/4⟩을 3으로 나눈 것이므로 쌀은 ⟨2/5⟩ ÷ 3 = ⟨2/15⟩ kg이다. 한 통은 ⟨1/4⟩의 4배이므로 ⟨2/15⟩ × 4 = ⟨8/15⟩ kg이다. ÷ 3과 × 4를 함께 하면 × ⟨4/3⟩이므로 ⟨2/5⟩ ÷ ⟨3/4⟩ = ⟨2/5⟩ × ⟨4/3⟩ = ⟨8/15⟩이다.","scoring_points":["통의 ⟨1/4⟩을 채우는 쌀 ⟨2/15⟩ kg을 구했는가","4배 하여 ⟨8/15⟩ kg을 구했는가","÷ 3 × 4가 × ⟨4/3⟩임을 설명했는가"]},"explanation":["통의 ⟨1/4⟩: ⟨2/5⟩ ÷ 3 = ⟨2/15⟩ kg.","한 통: ⟨2/15⟩ × 4 = ⟨8/15⟩ kg.","÷ 3 × 4는 × ⟨4/3⟩와 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L07_challenge#10','math',6,2,'u1','L07','tb_g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',4,'mc','auto','□ × ⟨4/5⟩ = ⟨1/3⟩일 때 □는 어떤 수인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X01','M6-2-u1-X19']::text[],false,'{"seq":10,"concept":"M6-2-u1-C7","difficulty":4,"kind":"mc","stem":"□ × ⟨4/5⟩ = ⟨1/3⟩일 때 □는 어떤 수인가요?","options":[{"t":"⟨5/12⟩","correct":true},{"t":"⟨4/15⟩","mis":"M6-2-u1-X10"},{"t":"⟨2 2/5⟩","mis":"M6-2-u1-X01"},{"t":"⟨1/3⟩","mis":"M6-2-u1-X19"}],"explanation":["□ × 3 = 6이면 □는 6을 3으로 나누어 구해요.","마찬가지로 □ = ⟨1/3⟩ ÷ ⟨4/5⟩ = ⟨1/3⟩ × ⟨5/4⟩ = ⟨5/12⟩.","곱해진 수로 나누어 □를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_basic#1','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',1,'mc','auto','감물로 염색한 직사각형 모양 천의 넓이가 ⟨1 4/5⟩ m²이고 가로가 ⟨1 1/2⟩ m예요. 천의 세로를 구하는 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X03']::text[],false,'{"seq":1,"concept":"M6-2-u1-C8","difficulty":1,"kind":"mc","stem":"감물로 염색한 직사각형 모양 천의 넓이가 ⟨1 4/5⟩ m²이고 가로가 ⟨1 1/2⟩ m예요. 천의 세로를 구하는 식은 어느 것인가요?","options":[{"t":"⟨1 4/5⟩ ÷ ⟨1 1/2⟩","correct":true},{"t":"⟨1 1/2⟩ ÷ ⟨1 4/5⟩","mis":"M6-2-u1-X01"},{"t":"⟨1 4/5⟩ × ⟨1 1/2⟩","mis":"M6-2-u1-X03"},{"t":"⟨1 4/5⟩ − ⟨1 1/2⟩","mis":"M6-2-u1-X03"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)예요.","그래서 (세로) = (넓이) ÷ (가로)예요.","천의 세로는 ⟨1 4/5⟩ ÷ ⟨1 1/2⟩로 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_basic#2','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',1,'mc','auto','⟨1 4/5⟩ ÷ ⟨1 1/2⟩을 가분수의 나눗셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u1-X14','M6-2-u1-X13','M6-2-u1-X12']::text[],true,'{"seq":2,"concept":"M6-2-u1-C8","difficulty":1,"kind":"mc","stem":"⟨1 4/5⟩ ÷ ⟨1 1/2⟩을 가분수의 나눗셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨9/5⟩ ÷ ⟨3/2⟩","correct":true},{"t":"⟨5/5⟩ ÷ ⟨2/2⟩","mis":"M6-2-u1-X14"},{"t":"⟨4/5⟩ ÷ ⟨1/2⟩","mis":"M6-2-u1-X13"},{"t":"⟨9/5⟩ ÷ ⟨2/3⟩","mis":"M6-2-u1-X12"}],"explanation":["⟨1 4/5⟩ = ⟨9/5⟩ — 1 × 5 + 4 = 9가 분자예요.","⟨1 1/2⟩ = ⟨3/2⟩ — 1 × 2 + 1 = 3이 분자예요.","그래서 ⟨9/5⟩ ÷ ⟨3/2⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 5/6⟩ ÷ ⟨2/3⟩를 가분수의 나눗셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨17/6⟩ ÷ ⟨2/3⟩","correct":true},{"t":"⟨7/6⟩ ÷ ⟨2/3⟩","mis":"M6-2-u1-X14"},{"t":"⟨5/6⟩ ÷ ⟨2/3⟩","mis":"M6-2-u1-X13"},{"t":"⟨17/6⟩ ÷ ⟨3/2⟩","mis":"M6-2-u1-X12"}],"explanation":["⟨2 5/6⟩ = ⟨17/6⟩ — 2 × 6 + 5 = 17이 분자예요.","진분수 ⟨2/3⟩는 그대로예요.","그래서 ⟨17/6⟩ ÷ ⟨2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_basic#3','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',1,'mc','auto','⟨1 1/3⟩ ÷ ⟨2/7⟩를 계산해 보세요.',ARRAY['M6-2-u1-X14','M6-2-u1-X13','M6-2-u1-X10']::text[],true,'{"seq":3,"concept":"M6-2-u1-C8","difficulty":1,"kind":"mc","stem":"⟨1 1/3⟩ ÷ ⟨2/7⟩를 계산해 보세요.","options":[{"t":"⟨4 2/3⟩","correct":true},{"t":"⟨2 1/3⟩","mis":"M6-2-u1-X14"},{"t":"⟨2 1/6⟩","mis":"M6-2-u1-X13"},{"t":"⟨8/21⟩","mis":"M6-2-u1-X10"}],"explanation":["대분수를 가분수로 고쳐요 — ⟨1 1/3⟩ ÷ ⟨2/7⟩ = ⟨4/3⟩ ÷ ⟨2/7⟩.","곱셈으로 나타내면 ⟨4/3⟩ × ⟨7/2⟩ = ⟨4 2/3⟩.","대분수는 먼저 가분수로 고친 뒤 분수의 나눗셈을 해요."],"variant_rule":{"alt":[{"stem":"⟨2 3/5⟩ ÷ ⟨1 2/5⟩를 계산해 보세요.","options":[{"t":"⟨1 6/7⟩","correct":true},{"t":"⟨1 2/3⟩","mis":"M6-2-u1-X14"},{"t":"⟨3 1/2⟩","mis":"M6-2-u1-X13"},{"t":"⟨3 16/25⟩","mis":"M6-2-u1-X10"}],"explanation":["대분수를 가분수로 고쳐요 — ⟨2 3/5⟩ ÷ ⟨1 2/5⟩ = ⟨13/5⟩ ÷ ⟨7/5⟩.","곱셈으로 나타내면 ⟨13/5⟩ × ⟨5/7⟩ = ⟨1 6/7⟩.","대분수는 먼저 가분수로 고친 뒤 분수의 나눗셈을 해요."]},{"stem":"7 ÷ ⟨2 5/8⟩를 계산해 보세요.","options":[{"t":"⟨2 2/3⟩","correct":true},{"t":"8","mis":"M6-2-u1-X14"},{"t":"⟨14 7/10⟩","mis":"M6-2-u1-X13"},{"t":"⟨18 3/8⟩","mis":"M6-2-u1-X10"}],"explanation":["대분수를 가분수로 고쳐요 — 7 ÷ ⟨2 5/8⟩ = 7 ÷ ⟨21/8⟩.","곱셈으로 나타내면 7 × ⟨8/21⟩ = ⟨2 2/3⟩.","대분수는 먼저 가분수로 고친 뒤 분수의 나눗셈을 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_basic#4','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',1,'mc','auto','넓이가 ⟨1 4/5⟩ m²이고 가로가 ⟨1 1/2⟩ m인 직사각형 모양 천의 세로는 몇 m인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X01','M6-2-u1-X03']::text[],true,'{"seq":4,"concept":"M6-2-u1-C8","difficulty":1,"kind":"mc","stem":"넓이가 ⟨1 4/5⟩ m²이고 가로가 ⟨1 1/2⟩ m인 직사각형 모양 천의 세로는 몇 m인가요?","options":[{"t":"⟨1 1/5⟩","correct":true},{"t":"⟨2 3/5⟩","mis":"M6-2-u1-X13"},{"t":"⟨5/6⟩","mis":"M6-2-u1-X01"},{"t":"⟨2 7/10⟩","mis":"M6-2-u1-X03"}],"explanation":["세로 = ⟨1 4/5⟩ ÷ ⟨1 1/2⟩ = ⟨9/5⟩ ÷ ⟨3/2⟩이에요.","⟨9/5⟩ × ⟨2/3⟩ = ⟨6/5⟩ = ⟨1 1/5⟩.","천의 세로는 ⟨1 1/5⟩ m예요."],"variant_rule":{"alt":[{"stem":"넓이가 ⟨4 2/5⟩ m²이고 가로가 ⟨2 2/5⟩ m인 직사각형의 세로는 몇 m인가요?","options":[{"t":"⟨1 5/6⟩","correct":true},{"t":"3","mis":"M6-2-u1-X13"},{"t":"⟨6/11⟩","mis":"M6-2-u1-X01"},{"t":"⟨10 14/25⟩","mis":"M6-2-u1-X03"}],"explanation":["세로 = ⟨4 2/5⟩ ÷ ⟨2 2/5⟩ = ⟨22/5⟩ ÷ ⟨12/5⟩예요.","분모가 같으니 22 ÷ 12 = ⟨22/12⟩ = ⟨1 5/6⟩.","직사각형의 세로는 ⟨1 5/6⟩ m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_basic#5','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',2,'sa','auto','유나는 ⟨1 4/5⟩ ÷ ⟨1 1/2⟩ = ⟨9/5⟩ ÷ ⟨3/2⟩ = ⟨18/10⟩ ÷ ⟨15/10⟩ = 18 ÷ □로 계산했어요. □ 안에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u1-C8","difficulty":2,"kind":"sa","stem":"유나는 ⟨1 4/5⟩ ÷ ⟨1 1/2⟩ = ⟨9/5⟩ ÷ ⟨3/2⟩ = ⟨18/10⟩ ÷ ⟨15/10⟩ = 18 ÷ □로 계산했어요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["15"],"explanation":["⟨3/2⟩ = ⟨15/10⟩예요.","분모가 같아졌으니 18 ÷ 15로 계산해요.","18 ÷ 15 = ⟨18/15⟩ = ⟨1 3/15⟩ = ⟨1 1/5⟩ — □는 15예요."],"variant_rule":{"alt":[{"stem":"⟨2 5/6⟩ ÷ ⟨2/3⟩ = ⟨17/6⟩ ÷ ⟨□/6⟩ = 17 ÷ 4예요. □ 안에 알맞은 수를 숫자로 쓰세요.","answer":["4"],"explanation":["⟨2/3⟩ = ⟨4/6⟩예요.","⟨17/6⟩ ÷ ⟨4/6⟩ = 17 ÷ 4 = ⟨17/4⟩ = ⟨4 1/4⟩.","그래서 □는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_basic#6','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',2,'mc','auto','유나는 통분하여, 지호는 분수의 곱셈으로 나타내어 ⟨1 4/5⟩ ÷ ⟨1 1/2⟩을 계산했어요. 두 친구의 계산을 비교한 것으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u1-X15','M6-2-u1-X13']::text[],false,'{"seq":6,"concept":"M6-2-u1-C8","difficulty":2,"kind":"mc","stem":"유나는 통분하여, 지호는 분수의 곱셈으로 나타내어 ⟨1 4/5⟩ ÷ ⟨1 1/2⟩을 계산했어요. 두 친구의 계산을 비교한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 대분수를 가분수로 고쳤고, 계산 결과는 ⟨1 1/5⟩로 같다","correct":true},{"t":"유나의 결과 ⟨1 3/15⟩이 지호의 결과보다 크다","mis":"M6-2-u1-X15"},{"t":"지호의 결과 ⟨6/5⟩이 유나의 결과보다 크다","mis":"M6-2-u1-X15"},{"t":"대분수의 나눗셈은 통분으로만 할 수 있다","mis":"M6-2-u1-X13"}],"explanation":["유나: ⟨18/10⟩ ÷ ⟨15/10⟩ = 18 ÷ 15 = ⟨1 1/5⟩.","지호: ⟨9/5⟩ × ⟨2/3⟩ = ⟨6/5⟩ = ⟨1 1/5⟩.","방법은 달라도 결과는 같아요 — 원하는 방법으로 계산해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_basic#7','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',2,'ox','auto','친구가 ⟨1 1/9⟩ ÷ ⟨3/4⟩ = ⟨1 1/9⟩ × ⟨4/3⟩ = ⟨1 4/27⟩이라고 계산했어요. 바르게 계산했나요?',ARRAY['M6-2-u1-X13']::text[],false,'{"seq":7,"concept":"M6-2-u1-C8","difficulty":2,"kind":"ox","stem":"친구가 ⟨1 1/9⟩ ÷ ⟨3/4⟩ = ⟨1 1/9⟩ × ⟨4/3⟩ = ⟨1 4/27⟩이라고 계산했어요. 바르게 계산했나요?","answer":"X","reason_options":[{"t":"대분수를 가분수로 고치지 않고 분수 부분만 곱해서","correct":true},{"t":"나누는 분수를 바꾸어 곱했으니 맞아서","mis":"M6-2-u1-X13"}],"mis":"M6-2-u1-X13","explanation":["대분수 ⟨1 1/9⟩을 먼저 가분수 ⟨10/9⟩으로 고쳐야 해요.","⟨1 1/9⟩ ÷ ⟨3/4⟩ = ⟨10/9⟩ × ⟨4/3⟩ = ⟨40/27⟩ = ⟨1 13/27⟩.","바른 몫은 ⟨1 13/27⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_basic#8','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',2,'mc','auto','무게가 ⟨3/4⟩ kg인 천 ⟨3 1/6⟩ m가 있어요. 천 1 m의 무게는 몇 kg인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X10','M6-2-u1-X13']::text[],false,'{"seq":8,"concept":"M6-2-u1-C8","difficulty":2,"kind":"mc","stem":"무게가 ⟨3/4⟩ kg인 천 ⟨3 1/6⟩ m가 있어요. 천 1 m의 무게는 몇 kg인가요?","options":[{"t":"⟨9/38⟩","correct":true},{"t":"⟨4 2/9⟩","mis":"M6-2-u1-X01"},{"t":"⟨2 3/8⟩","mis":"M6-2-u1-X10"},{"t":"⟨1/4⟩","mis":"M6-2-u1-X13"}],"explanation":["1 m의 무게는 무게를 길이로 나누어 구해요 — ⟨3/4⟩ ÷ ⟨3 1/6⟩.","⟨3/4⟩ ÷ ⟨19/6⟩ = ⟨3/4⟩ × ⟨6/19⟩ = ⟨9/38⟩.","천 1 m의 무게는 ⟨9/38⟩ kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_basic#9','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u1-C8","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨1 1/3⟩ ÷ ⟨2/7⟩","r":"⟨4 2/3⟩"},{"l":"⟨2 3/5⟩ ÷ ⟨1 2/5⟩","r":"⟨1 6/7⟩"},{"l":"7 ÷ ⟨2 5/8⟩","r":"⟨2 2/3⟩"}],"mis":"M6-2-u1-X13","explanation":["대분수를 가분수로 고쳐 계산해요.","⟨4/3⟩ × ⟨7/2⟩ = ⟨4 2/3⟩, ⟨13/5⟩ ÷ ⟨7/5⟩ = 13 ÷ 7 = ⟨1 6/7⟩.","7 × ⟨8/21⟩ = ⟨8/3⟩ = ⟨2 2/3⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_basic#10','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',3,'sa','auto','⟨5/14⟩ ÷ ⟨1 3/7⟩과 ⟨2 2/5⟩ ÷ ⟨3 1/5⟩의 몫의 합을 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u1-C8","difficulty":3,"kind":"sa","stem":"⟨5/14⟩ ÷ ⟨1 3/7⟩과 ⟨2 2/5⟩ ÷ ⟨3 1/5⟩의 몫의 합을 숫자로 쓰세요.","answer":["1"],"explanation":["⟨5/14⟩ ÷ ⟨1 3/7⟩ = ⟨5/14⟩ × ⟨7/10⟩ = ⟨1/4⟩.","⟨2 2/5⟩ ÷ ⟨3 1/5⟩ = ⟨12/5⟩ × ⟨5/16⟩ = ⟨3/4⟩.","두 몫의 합은 ⟨1/4⟩ + ⟨3/4⟩ = 1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_challenge#1','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',2,'mc','auto','⟨1 2/5⟩ ÷ ⟨4 1/3⟩을 계산해 보세요.',ARRAY['M6-2-u1-X14','M6-2-u1-X13','M6-2-u1-X10']::text[],true,'{"seq":1,"concept":"M6-2-u1-C8","difficulty":2,"kind":"mc","stem":"⟨1 2/5⟩ ÷ ⟨4 1/3⟩을 계산해 보세요.","options":[{"t":"⟨21/65⟩","correct":true},{"t":"⟨9/25⟩","mis":"M6-2-u1-X14"},{"t":"⟨1 9/20⟩","mis":"M6-2-u1-X13"},{"t":"⟨6 1/15⟩","mis":"M6-2-u1-X10"}],"explanation":["대분수를 가분수로 고쳐요 — ⟨1 2/5⟩ ÷ ⟨4 1/3⟩ = ⟨7/5⟩ ÷ ⟨13/3⟩.","곱셈으로 나타내면 ⟨7/5⟩ × ⟨3/13⟩ = ⟨21/65⟩.","대분수는 먼저 가분수로 고친 뒤 분수의 나눗셈을 해요."],"variant_rule":{"alt":[{"stem":"⟨2 1/4⟩ ÷ ⟨2/7⟩를 계산해 보세요.","options":[{"t":"⟨7 7/8⟩","correct":true},{"t":"⟨2 5/8⟩","mis":"M6-2-u1-X14"},{"t":"⟨2 7/8⟩","mis":"M6-2-u1-X13"},{"t":"⟨9/14⟩","mis":"M6-2-u1-X10"}],"explanation":["대분수를 가분수로 고쳐요 — ⟨2 1/4⟩ ÷ ⟨2/7⟩ = ⟨9/4⟩ ÷ ⟨2/7⟩.","곱셈으로 나타내면 ⟨9/4⟩ × ⟨7/2⟩ = ⟨7 7/8⟩.","대분수는 먼저 가분수로 고친 뒤 분수의 나눗셈을 해요."]},{"stem":"⟨1 2/5⟩ ÷ ⟨3/7⟩을 계산해 보세요.","options":[{"t":"⟨3 4/15⟩","correct":true},{"t":"⟨1 2/5⟩","mis":"M6-2-u1-X14"},{"t":"⟨1 14/15⟩","mis":"M6-2-u1-X13"},{"t":"⟨3/5⟩","mis":"M6-2-u1-X10"}],"explanation":["대분수를 가분수로 고쳐요 — ⟨1 2/5⟩ ÷ ⟨3/7⟩ = ⟨7/5⟩ ÷ ⟨3/7⟩.","곱셈으로 나타내면 ⟨7/5⟩ × ⟨7/3⟩ = ⟨3 4/15⟩.","대분수는 먼저 가분수로 고친 뒤 분수의 나눗셈을 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_challenge#2','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',2,'mc','auto','9 ÷ ⟨1 2/3⟩를 계산해 보세요.',ARRAY['M6-2-u1-X14','M6-2-u1-X13','M6-2-u1-X10']::text[],true,'{"seq":2,"concept":"M6-2-u1-C8","difficulty":2,"kind":"mc","stem":"9 ÷ ⟨1 2/3⟩를 계산해 보세요.","options":[{"t":"⟨5 2/5⟩","correct":true},{"t":"9","mis":"M6-2-u1-X14"},{"t":"⟨22 1/2⟩","mis":"M6-2-u1-X13"},{"t":"15","mis":"M6-2-u1-X10"}],"explanation":["대분수를 가분수로 고쳐요 — 9 ÷ ⟨1 2/3⟩ = 9 ÷ ⟨5/3⟩.","곱셈으로 나타내면 9 × ⟨3/5⟩ = ⟨5 2/5⟩.","대분수는 먼저 가분수로 고친 뒤 분수의 나눗셈을 해요."],"variant_rule":{"alt":[{"stem":"⟨9/10⟩ ÷ ⟨1 4/5⟩를 계산해 보세요.","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨9/10⟩","mis":"M6-2-u1-X14"},{"t":"⟨2 1/40⟩","mis":"M6-2-u1-X13"},{"t":"⟨1 31/50⟩","mis":"M6-2-u1-X10"}],"explanation":["대분수를 가분수로 고쳐요 — ⟨9/10⟩ ÷ ⟨1 4/5⟩ = ⟨9/10⟩ ÷ ⟨9/5⟩.","곱셈으로 나타내면 ⟨9/10⟩ × ⟨5/9⟩ = ⟨1/2⟩.","대분수는 먼저 가분수로 고친 뒤 분수의 나눗셈을 해요."]},{"stem":"⟨1 2/9⟩ ÷ ⟨4/5⟩를 계산해 보세요.","options":[{"t":"⟨1 19/36⟩","correct":true},{"t":"⟨5/12⟩","mis":"M6-2-u1-X14"},{"t":"⟨1 5/18⟩","mis":"M6-2-u1-X13"},{"t":"⟨44/45⟩","mis":"M6-2-u1-X10"}],"explanation":["대분수를 가분수로 고쳐요 — ⟨1 2/9⟩ ÷ ⟨4/5⟩ = ⟨11/9⟩ ÷ ⟨4/5⟩.","곱셈으로 나타내면 ⟨11/9⟩ × ⟨5/4⟩ = ⟨1 19/36⟩.","대분수는 먼저 가분수로 고친 뒤 분수의 나눗셈을 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_challenge#3','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',3,'mc','auto','「알쏭달쏭 가로세로 나눗셈」의 한 줄이에요. 4 ÷ ⟨2/9⟩의 몫을 ⟨2 1/4⟩로 나누면 얼마인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X10','M6-2-u1-X01']::text[],false,'{"seq":3,"concept":"M6-2-u1-C8","difficulty":3,"kind":"mc","stem":"「알쏭달쏭 가로세로 나눗셈」의 한 줄이에요. 4 ÷ ⟨2/9⟩의 몫을 ⟨2 1/4⟩로 나누면 얼마인가요?","options":[{"t":"8","correct":true},{"t":"9","mis":"M6-2-u1-X13"},{"t":"⟨40 1/2⟩","mis":"M6-2-u1-X10"},{"t":"⟨1/8⟩","mis":"M6-2-u1-X01"}],"explanation":["4 ÷ ⟨2/9⟩ = 4 × ⟨9/2⟩ = 18이에요.","18 ÷ ⟨2 1/4⟩ = 18 ÷ ⟨9/4⟩ = 18 × ⟨4/9⟩ = 8.","앞 식의 몫이 다음 식의 나누어지는 수가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_challenge#4','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',3,'sa','auto','넓이가 ⟨5 3/5⟩ m²인 평행사변형의 밑변의 길이가 ⟨7/10⟩ m일 때 높이는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M6-2-u1-C8","difficulty":3,"kind":"sa","stem":"넓이가 ⟨5 3/5⟩ m²인 평행사변형의 밑변의 길이가 ⟨7/10⟩ m일 때 높이는 몇 m인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["(평행사변형의 넓이) = (밑변의 길이) × (높이)예요.","높이 = ⟨5 3/5⟩ ÷ ⟨7/10⟩ = ⟨28/5⟩ × ⟨10/7⟩ = 8.","평행사변형의 높이는 8 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_challenge#5','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',3,'error','auto','⟨1 4/5⟩ ÷ ⟨1 1/2⟩을 계산하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X20']::text[],false,'{"seq":5,"concept":"M6-2-u1-C8","difficulty":3,"kind":"error","stem":"⟨1 4/5⟩ ÷ ⟨1 1/2⟩을 계산하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 1 ÷ 1과 ⟨4/5⟩ ÷ ⟨1/2⟩을 따로 계산해서 더하면 돼.","correct":true,"mis_target":"M6-2-u1-X13"},{"t":"유나 — 가분수로 고친 다음 통분해서 분자끼리 나눌 수 있어.","mis":"M6-2-u1-X20"},{"t":"지호 — 가분수로 고친 다음 분수의 곱셈으로 나타낼 수 있어.","mis":"M6-2-u1-X20"}],"explanation":["대분수의 나눗셈은 먼저 가분수로 고쳐요 — ⟨9/5⟩ ÷ ⟨3/2⟩.","⟨9/5⟩ × ⟨2/3⟩ = ⟨6/5⟩ = ⟨1 1/5⟩.","자연수 부분과 분수 부분을 따로 나누면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_challenge#6','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',3,'mc','auto','⟨2 2/9⟩를 ⟨4/5⟩로 나눈 몫을 다시 ⟨1 2/3⟩로 나누면 얼마인가요?',ARRAY['M6-2-u1-X18','M6-2-u1-X10','M6-2-u1-X13']::text[],false,'{"seq":6,"concept":"M6-2-u1-C8","difficulty":3,"kind":"mc","stem":"⟨2 2/9⟩를 ⟨4/5⟩로 나눈 몫을 다시 ⟨1 2/3⟩로 나누면 얼마인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨2 7/9⟩","mis":"M6-2-u1-X18"},{"t":"⟨4 17/27⟩","mis":"M6-2-u1-X10"},{"t":"⟨2/3⟩","mis":"M6-2-u1-X13"}],"explanation":["⟨2 2/9⟩ ÷ ⟨4/5⟩ = ⟨20/9⟩ × ⟨5/4⟩ = ⟨25/9⟩ = ⟨2 7/9⟩.","⟨2 7/9⟩ ÷ ⟨1 2/3⟩ = ⟨25/9⟩ × ⟨3/5⟩ = ⟨5/3⟩ = ⟨1 2/3⟩.","첫 번째 몫에서 멈추지 말고 두 번 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_challenge#7','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',3,'mc','auto','넓이가 ⟨6 1/4⟩ m²인 직사각형 모양의 벽을 칠하는 데 페인트 ⟨2 1/2⟩ L를 썼어요. 페인트 1 L로 몇 m²의 벽을 칠한 셈인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X10','M6-2-u1-X13']::text[],false,'{"seq":7,"concept":"M6-2-u1-C8","difficulty":3,"kind":"mc","stem":"넓이가 ⟨6 1/4⟩ m²인 직사각형 모양의 벽을 칠하는 데 페인트 ⟨2 1/2⟩ L를 썼어요. 페인트 1 L로 몇 m²의 벽을 칠한 셈인가요?","options":[{"t":"⟨2 1/2⟩","correct":true},{"t":"⟨2/5⟩","mis":"M6-2-u1-X01"},{"t":"⟨15 5/8⟩","mis":"M6-2-u1-X10"},{"t":"3","mis":"M6-2-u1-X13"}],"explanation":["1 L로 칠한 넓이는 넓이를 페인트 양으로 나눠요 — ⟨6 1/4⟩ ÷ ⟨2 1/2⟩.","⟨25/4⟩ ÷ ⟨5/2⟩ = ⟨25/4⟩ × ⟨2/5⟩ = ⟨5/2⟩ = ⟨2 1/2⟩.","페인트 1 L로 ⟨2 1/2⟩ m²를 칠한 셈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_challenge#8','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',4,'mc','auto','수 카드 4, 1, 5를 한 번씩 모두 이용하여 만들 수 있는 대분수 가운데 가장 큰 대분수를 가장 작은 대분수로 나눈 몫은 얼마인가요?',ARRAY['M6-2-u1-X21','M6-2-u1-X13','M6-2-u1-X14']::text[],false,'{"seq":8,"concept":"M6-2-u1-C8","difficulty":4,"kind":"mc","stem":"수 카드 4, 1, 5를 한 번씩 모두 이용하여 만들 수 있는 대분수 가운데 가장 큰 대분수를 가장 작은 대분수로 나눈 몫은 얼마인가요?","options":[{"t":"⟨2 11/12⟩","correct":true},{"t":"⟨12/35⟩","mis":"M6-2-u1-X21"},{"t":"⟨5 5/16⟩","mis":"M6-2-u1-X13"},{"t":"⟨1 1/2⟩","mis":"M6-2-u1-X14"}],"explanation":["가장 큰 대분수는 ⟨5 1/4⟩, 가장 작은 대분수는 ⟨1 4/5⟩예요.","⟨5 1/4⟩ ÷ ⟨1 4/5⟩ = ⟨21/4⟩ × ⟨5/9⟩ = ⟨35/12⟩ = ⟨2 11/12⟩.","가장 큰 수를 가장 작은 수로 나누어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_challenge#9','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',4,'essay','teacher','친구가 ⟨1 1/9⟩ ÷ ⟨3/4⟩ = ⟨1 1/9⟩ × ⟨4/3⟩ = ⟨1 4/27⟩로 계산했어요. 잘못된 곳을 찾아 까닭을 쓰고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u1-C8","difficulty":4,"kind":"essay","stem":"친구가 ⟨1 1/9⟩ ÷ ⟨3/4⟩ = ⟨1 1/9⟩ × ⟨4/3⟩ = ⟨1 4/27⟩로 계산했어요. 잘못된 곳을 찾아 까닭을 쓰고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 대분수 ⟨1 1/9⟩을 가분수로 고치지 않고 분수 부분 ⟨1/9⟩에만 ⟨4/3⟩을 곱했다. ⟨1 1/9⟩ = ⟨10/9⟩이므로 ⟨1 1/9⟩ ÷ ⟨3/4⟩ = ⟨10/9⟩ × ⟨4/3⟩ = ⟨40/27⟩ = ⟨1 13/27⟩이다.","scoring_points":["대분수를 가분수로 고치지 않은 것을 찾았는가","⟨10/9⟩ × ⟨4/3⟩로 고쳐 계산했는가","⟨1 13/27⟩을 구했는가"]},"explanation":["대분수는 먼저 가분수로 고쳐요 — ⟨1 1/9⟩ = ⟨10/9⟩.","⟨10/9⟩ × ⟨4/3⟩ = ⟨40/27⟩ = ⟨1 13/27⟩.","자연수 1에도 ⟨4/3⟩를 곱해야 하기 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L08_challenge#10','math',6,2,'u1','L08','tb_g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',4,'essay','teacher','⟨2 5/6⟩ ÷ ⟨2/3⟩를 통분하는 방법과 분수의 곱셈으로 나타내는 방법으로 각각 계산하고, 두 방법을 비교해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u1-C8","difficulty":4,"kind":"essay","stem":"⟨2 5/6⟩ ÷ ⟨2/3⟩를 통분하는 방법과 분수의 곱셈으로 나타내는 방법으로 각각 계산하고, 두 방법을 비교해 보세요.","answer_guide":{"answer":"예: 통분 — ⟨2 5/6⟩ ÷ ⟨2/3⟩ = ⟨17/6⟩ ÷ ⟨4/6⟩ = 17 ÷ 4 = ⟨17/4⟩ = ⟨4 1/4⟩. 곱셈 — ⟨17/6⟩ × ⟨3/2⟩ = ⟨17/4⟩ = ⟨4 1/4⟩. 두 방법 모두 대분수를 가분수로 고친 뒤 계산하고 결과는 ⟨4 1/4⟩로 같다.","scoring_points":["통분하여 ⟨4 1/4⟩을 구했는가","곱셈으로 ⟨4 1/4⟩을 구했는가","가분수로 고친다는 공통점과 결과가 같음을 썼는가"]},"explanation":["통분: ⟨17/6⟩ ÷ ⟨4/6⟩ = 17 ÷ 4 = ⟨4 1/4⟩.","곱셈: ⟨17/6⟩ × ⟨3/2⟩ = ⟨4 1/4⟩.","두 방법의 결과는 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_basic#1','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',1,'mc','auto','폐비닐을 새 활용 해 만든 정사각형 타일(한 변 ⟨7 1/2⟩ cm)로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 직사각형 벽을 겹치지 않게 가득 붙이려고 해요. 타일 100개로 벽을 가득 붙일 수 있는지 알아보려고 해요. 구하려는 것은 무엇인가요?',ARRAY['M6-2-u1-X18']::text[],false,'{"seq":1,"concept":"M6-2-u1-C9","difficulty":1,"kind":"mc","stem":"폐비닐을 새 활용 해 만든 정사각형 타일(한 변 ⟨7 1/2⟩ cm)로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 직사각형 벽을 겹치지 않게 가득 붙이려고 해요. 타일 100개로 벽을 가득 붙일 수 있는지 알아보려고 해요. 구하려는 것은 무엇인가요?","options":[{"t":"타일 100개로 벽을 겹치지 않게 가득 붙일 수 있는지","correct":true},{"t":"타일 한 변의 길이","mis":"M6-2-u1-X18"},{"t":"벽의 가로와 세로의 합","mis":"M6-2-u1-X18"},{"t":"타일 100개를 한 줄로 늘어놓은 길이","mis":"M6-2-u1-X18"}],"explanation":["문제를 풀기 전에 구하려는 것부터 찾아요.","물음은 「타일 100개로 가득 붙일 수 있는지」예요.","타일 한 변의 길이와 벽의 가로·세로는 알고 있는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_basic#2','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',1,'mc','auto','폐비닐을 새 활용 해 만든 정사각형 타일(한 변 ⟨7 1/2⟩ cm)로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 직사각형 벽을 겹치지 않게 가득 붙이려고 해요. 이 문제에서 알고 있는 것은 무엇인가요?',ARRAY['M6-2-u1-X18']::text[],false,'{"seq":2,"concept":"M6-2-u1-C9","difficulty":1,"kind":"mc","stem":"폐비닐을 새 활용 해 만든 정사각형 타일(한 변 ⟨7 1/2⟩ cm)로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 직사각형 벽을 겹치지 않게 가득 붙이려고 해요. 이 문제에서 알고 있는 것은 무엇인가요?","options":[{"t":"타일 한 변의 길이, 꾸미려는 벽의 가로와 세로","correct":true},{"t":"필요한 타일 수","mis":"M6-2-u1-X18"},{"t":"벽에 붙일 타일의 무게","mis":"M6-2-u1-X18"},{"t":"타일 한 장의 넓이만","mis":"M6-2-u1-X18"}],"explanation":["알고 있는 것은 문제에 주어진 수예요.","타일 한 변 ⟨7 1/2⟩ cm, 벽의 가로 60 cm, 세로 ⟨82 1/2⟩ cm예요.","필요한 타일 수는 이 수들로 구해야 하는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_basic#3','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',1,'mc','auto','폐비닐을 새 활용 해 만든 정사각형 타일(한 변 ⟨7 1/2⟩ cm)로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 직사각형 벽을 겹치지 않게 가득 붙이려고 해요. 벽의 가로에 붙일 수 있는 타일 수를 구하는 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X10','M6-2-u1-X03']::text[],true,'{"seq":3,"concept":"M6-2-u1-C9","difficulty":1,"kind":"mc","stem":"폐비닐을 새 활용 해 만든 정사각형 타일(한 변 ⟨7 1/2⟩ cm)로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 직사각형 벽을 겹치지 않게 가득 붙이려고 해요. 벽의 가로에 붙일 수 있는 타일 수를 구하는 식은 어느 것인가요?","options":[{"t":"60 ÷ ⟨7 1/2⟩","correct":true},{"t":"⟨7 1/2⟩ ÷ 60","mis":"M6-2-u1-X01"},{"t":"60 × ⟨7 1/2⟩","mis":"M6-2-u1-X10"},{"t":"60 − ⟨7 1/2⟩","mis":"M6-2-u1-X03"}],"explanation":["가로 60 cm에 한 변 ⟨7 1/2⟩ cm인 타일이 몇 번 들어가는지 묻고 있어요.","몇 번 들어가는지는 나눗셈 — 길이 ÷ 타일 한 변이에요.","식은 60 ÷ ⟨7 1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"한 변이 ⟨8 3/4⟩ cm인 정사각형 타일을 가로 350 cm, 세로 140 cm인 직사각형 게시판에 겹치지 않게 가득 붙이려고 해요. 게시판의 가로에 붙일 수 있는 타일 수를 구하는 식은 어느 것인가요?","options":[{"t":"350 ÷ ⟨8 3/4⟩","correct":true},{"t":"⟨8 3/4⟩ ÷ 350","mis":"M6-2-u1-X01"},{"t":"350 × ⟨8 3/4⟩","mis":"M6-2-u1-X10"},{"t":"350 − ⟨8 3/4⟩","mis":"M6-2-u1-X03"}],"explanation":["가로 350 cm에 타일 한 변 ⟨8 3/4⟩ cm가 몇 번 들어가는지예요.","길이 ÷ 타일 한 변으로 구해요.","식은 350 ÷ ⟨8 3/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_basic#4','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',1,'sa','auto','60 ÷ ⟨7 1/2⟩을 계산하여 벽의 가로에 붙일 수 있는 타일 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u1-C9","difficulty":1,"kind":"sa","stem":"60 ÷ ⟨7 1/2⟩을 계산하여 벽의 가로에 붙일 수 있는 타일 수를 숫자로 쓰세요.","answer":["8"],"explanation":["⟨7 1/2⟩ = ⟨15/2⟩예요.","60 ÷ ⟨15/2⟩ = 60 × ⟨2/15⟩ = 8.","벽의 가로에 타일 8개를 붙일 수 있어요."],"variant_rule":{"alt":[{"stem":"350 ÷ ⟨8 3/4⟩을 계산하여 게시판의 가로에 붙일 수 있는 타일 수를 숫자로 쓰세요.","answer":["40"],"explanation":["⟨8 3/4⟩ = ⟨35/4⟩예요.","350 ÷ ⟨35/4⟩ = 350 × ⟨4/35⟩ = 40.","게시판의 가로에 타일 40개를 붙일 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_basic#5','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',2,'sa','auto','폐비닐을 새 활용 해 만든 정사각형 타일(한 변 ⟨7 1/2⟩ cm)로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 직사각형 벽을 겹치지 않게 가득 붙이려고 해요. 벽의 세로에 붙일 수 있는 타일은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u1-C9","difficulty":2,"kind":"sa","stem":"폐비닐을 새 활용 해 만든 정사각형 타일(한 변 ⟨7 1/2⟩ cm)로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 직사각형 벽을 겹치지 않게 가득 붙이려고 해요. 벽의 세로에 붙일 수 있는 타일은 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["세로 ⟨82 1/2⟩ cm에 타일 한 변 ⟨7 1/2⟩ cm가 몇 번 들어가는지예요.","⟨82 1/2⟩ ÷ ⟨7 1/2⟩ = ⟨165/2⟩ ÷ ⟨15/2⟩ = 165 ÷ 15 = 11.","벽의 세로에 타일 11개를 붙일 수 있어요."],"variant_rule":{"alt":[{"stem":"한 변이 ⟨8 3/4⟩ cm인 타일을 세로 140 cm인 게시판에 붙여요. 게시판의 세로에 붙일 수 있는 타일은 몇 개인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["140 ÷ ⟨8 3/4⟩ = 140 ÷ ⟨35/4⟩예요.","140 × ⟨4/35⟩ = 16.","게시판의 세로에 타일 16개를 붙일 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_basic#6','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',2,'mc','auto','벽의 가로에 타일 8개, 세로에 타일 11개를 붙일 수 있어요. 벽을 가득 붙이는 데 필요한 타일은 모두 몇 개인가요?',ARRAY['M6-2-u1-X17','M6-2-u1-X18']::text[],true,'{"seq":6,"concept":"M6-2-u1-C9","difficulty":2,"kind":"mc","stem":"벽의 가로에 타일 8개, 세로에 타일 11개를 붙일 수 있어요. 벽을 가득 붙이는 데 필요한 타일은 모두 몇 개인가요?","options":[{"t":"88개","correct":true},{"t":"19개","mis":"M6-2-u1-X17"},{"t":"100개","mis":"M6-2-u1-X18"},{"t":"8개","mis":"M6-2-u1-X18"}],"explanation":["가로 한 줄에 8개씩, 그런 줄이 세로로 11줄이에요.","필요한 타일 수는 8 × 11 = 88(개)예요.","가로 수와 세로 수를 더하면 안 돼요."],"variant_rule":{"alt":[{"stem":"게시판의 가로에 타일 40개, 세로에 타일 16개를 붙일 수 있어요. 게시판을 가득 붙이는 데 필요한 타일은 모두 몇 개인가요?","options":[{"t":"640개","correct":true},{"t":"56개","mis":"M6-2-u1-X17"},{"t":"40개","mis":"M6-2-u1-X18"},{"t":"16개","mis":"M6-2-u1-X18"}],"explanation":["가로 한 줄에 40개씩, 그런 줄이 16줄이에요.","필요한 타일 수는 40 × 16 = 640(개)예요.","가로 수와 세로 수를 곱해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_basic#7','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',2,'ox','auto','벽의 가로에 타일 8개, 세로에 11개를 붙일 수 있으니 필요한 타일은 8 + 11 = 19개예요.',ARRAY['M6-2-u1-X17']::text[],false,'{"seq":7,"concept":"M6-2-u1-C9","difficulty":2,"kind":"ox","stem":"벽의 가로에 타일 8개, 세로에 11개를 붙일 수 있으니 필요한 타일은 8 + 11 = 19개예요.","answer":"X","reason_options":[{"t":"가로 8개씩 11줄을 붙이므로 8 × 11 = 88개가 필요해서","correct":true},{"t":"가로와 세로에 붙이는 타일을 모두 세면 19개라서","mis":"M6-2-u1-X17"}],"mis":"M6-2-u1-X17","explanation":["벽을 가득 덮으려면 가로 한 줄이 세로 줄 수만큼 있어야 해요.","8 × 11 = 88(개)예요.","더하면 가장자리 두 줄만 센 셈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_basic#8','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',2,'mc','auto','타일 100개로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 벽을 겹치지 않게 가득 붙일 수 있나요?',ARRAY['M6-2-u1-X18','M6-2-u1-X17']::text[],false,'{"seq":8,"concept":"M6-2-u1-C9","difficulty":2,"kind":"mc","stem":"타일 100개로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 벽을 겹치지 않게 가득 붙일 수 있나요?","options":[{"t":"붙일 수 있다 — 필요한 타일이 88개라 100개보다 적어서","correct":true},{"t":"붙일 수 없다 — 벽의 가로가 60 cm라서 타일이 모자라서","mis":"M6-2-u1-X18"},{"t":"붙일 수 없다 — 필요한 타일이 100개보다 많아서","mis":"M6-2-u1-X17"},{"t":"알 수 없다 — 타일의 넓이를 몰라서","mis":"M6-2-u1-X18"}],"explanation":["가로 60 ÷ ⟨7 1/2⟩ = 8개, 세로 ⟨82 1/2⟩ ÷ ⟨7 1/2⟩ = 11개예요.","필요한 타일은 8 × 11 = 88(개)예요.","88개는 100개보다 적으니 타일 100개로 가득 붙일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_basic#9','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',2,'mc','auto','60 ÷ ⟨7 1/2⟩을 계산하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X14','M6-2-u1-X13']::text[],true,'{"seq":9,"concept":"M6-2-u1-C9","difficulty":2,"kind":"mc","stem":"60 ÷ ⟨7 1/2⟩을 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"60 × ⟨2/15⟩","correct":true},{"t":"60 × ⟨15/2⟩","mis":"M6-2-u1-X10"},{"t":"60 × ⟨2/7⟩","mis":"M6-2-u1-X14"},{"t":"60 × ⟨1/2⟩","mis":"M6-2-u1-X13"}],"explanation":["대분수를 가분수로 고쳐요 — ⟨7 1/2⟩ = ⟨15/2⟩.","60 ÷ ⟨15/2⟩ = 60 × ⟨2/15⟩ = 8.","나누는 분수를 뒤집어 곱해요."],"variant_rule":{"alt":[{"stem":"350 ÷ ⟨8 3/4⟩을 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"350 × ⟨4/35⟩","correct":true},{"t":"350 × ⟨35/4⟩","mis":"M6-2-u1-X10"},{"t":"350 × ⟨4/11⟩","mis":"M6-2-u1-X14"},{"t":"350 × ⟨4/3⟩","mis":"M6-2-u1-X13"}],"explanation":["대분수를 가분수로 고쳐요 — ⟨8 3/4⟩ = ⟨35/4⟩.","350 ÷ ⟨35/4⟩ = 350 × ⟨4/35⟩ = 40.","나누는 분수를 뒤집어 곱해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_basic#10','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',3,'sa','auto','한 변이 ⟨8 3/4⟩ cm인 정사각형 타일을 한 변이 ⟨52 1/2⟩ cm인 정사각형 모양 사물함 문에 겹치지 않게 가득 붙이려고 해요. 필요한 타일은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u1-C9","difficulty":3,"kind":"sa","stem":"한 변이 ⟨8 3/4⟩ cm인 정사각형 타일을 한 변이 ⟨52 1/2⟩ cm인 정사각형 모양 사물함 문에 겹치지 않게 가득 붙이려고 해요. 필요한 타일은 몇 개인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["한 변에 붙일 타일 수는 ⟨52 1/2⟩ ÷ ⟨8 3/4⟩ = ⟨105/2⟩ × ⟨4/35⟩ = 6이에요.","정사각형이라 가로와 세로에 6개씩 붙여요.","필요한 타일은 6 × 6 = 36(개)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_challenge#1','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C9',2,'mc','auto','폐비닐을 새 활용 해 만든 정사각형 타일(한 변 ⟨7 1/2⟩ cm)로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 직사각형 벽을 겹치지 않게 가득 붙이려고 해요. 필요한 타일 수를 구하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u1-X17','M6-2-u1-X18']::text[],false,'{"seq":1,"concept":"M6-2-u1-C9","difficulty":2,"kind":"mc","stem":"폐비닐을 새 활용 해 만든 정사각형 타일(한 변 ⟨7 1/2⟩ cm)로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 직사각형 벽을 겹치지 않게 가득 붙이려고 해요. 필요한 타일 수를 구하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"가로에 붙일 타일 수와 세로에 붙일 타일 수를 구해 곱한다","correct":true},{"t":"가로에 붙일 타일 수와 세로에 붙일 타일 수를 더한다","mis":"M6-2-u1-X17"},{"t":"벽의 가로와 세로를 더한 길이를 타일 한 변으로 나눈다","mis":"M6-2-u1-X17"},{"t":"벽의 가로를 타일 수 100으로 나눈다","mis":"M6-2-u1-X18"}],"explanation":["벽의 가로에 붙일 타일 수, 세로에 붙일 타일 수를 먼저 구해요.","가로 한 줄이 세로 줄 수만큼 있으니 두 수를 곱해요.","60 ÷ ⟨7 1/2⟩ = 8, ⟨82 1/2⟩ ÷ ⟨7 1/2⟩ = 11 → 8 × 11 = 88(개)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_challenge#2','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C9',2,'mc','auto','⟨82 1/2⟩ ÷ ⟨7 1/2⟩을 통분하는 방법으로 계산한 것으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X14','M6-2-u1-X10']::text[],false,'{"seq":2,"concept":"M6-2-u1-C9","difficulty":2,"kind":"mc","stem":"⟨82 1/2⟩ ÷ ⟨7 1/2⟩을 통분하는 방법으로 계산한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨165/2⟩ ÷ ⟨15/2⟩ = 165 ÷ 15 = 11","correct":true},{"t":"82 ÷ 7과 ⟨1/2⟩ ÷ ⟨1/2⟩을 따로 계산한다","mis":"M6-2-u1-X13"},{"t":"⟨83/2⟩ ÷ ⟨8/2⟩ = 83 ÷ 8","mis":"M6-2-u1-X14"},{"t":"⟨165/2⟩ × ⟨15/2⟩","mis":"M6-2-u1-X10"}],"explanation":["대분수를 가분수로 고쳐요 — ⟨82 1/2⟩ = ⟨165/2⟩, ⟨7 1/2⟩ = ⟨15/2⟩.","분모가 같으니 분자끼리 나눠요 — 165 ÷ 15 = 11.","벽의 세로에 타일 11개를 붙일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_challenge#3','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C9',3,'sa','auto','한 변이 ⟨8 3/4⟩ cm인 정사각형 타일을 가로 350 cm, 세로 140 cm인 게시판에 겹치지 않게 가득 붙이려고 해요. 필요한 타일은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M6-2-u1-C9","difficulty":3,"kind":"sa","stem":"한 변이 ⟨8 3/4⟩ cm인 정사각형 타일을 가로 350 cm, 세로 140 cm인 게시판에 겹치지 않게 가득 붙이려고 해요. 필요한 타일은 몇 개인가요? 숫자로 쓰세요.","answer":["640"],"explanation":["가로: 350 ÷ ⟨8 3/4⟩ = 350 × ⟨4/35⟩ = 40(개).","세로: 140 ÷ ⟨8 3/4⟩ = 140 × ⟨4/35⟩ = 16(개).","필요한 타일은 40 × 16 = 640(개)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_challenge#4','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C9',3,'error','auto','벽(가로 60 cm, 세로 ⟨82 1/2⟩ cm)에 한 변 ⟨7 1/2⟩ cm 타일을 붙이는 문제를 친구들이 설명했어요. 잘못 설명한 친구는 누구인가요?',ARRAY['M6-2-u1-X17','M6-2-u1-X20']::text[],false,'{"seq":4,"concept":"M6-2-u1-C9","difficulty":3,"kind":"error","stem":"벽(가로 60 cm, 세로 ⟨82 1/2⟩ cm)에 한 변 ⟨7 1/2⟩ cm 타일을 붙이는 문제를 친구들이 설명했어요. 잘못 설명한 친구는 누구인가요?","options":[{"t":"도하 — 가로에 8개, 세로에 11개니까 타일 19개면 벽을 다 덮을 수 있어.","correct":true,"mis_target":"M6-2-u1-X17"},{"t":"세아 — 60 ÷ ⟨7 1/2⟩ = 8이라 가로 한 줄에 8개가 들어가.","mis":"M6-2-u1-X20"},{"t":"윤재 — 8개씩 11줄이니까 8 × 11 = 88개가 필요해.","mis":"M6-2-u1-X20"}],"explanation":["가로 한 줄에 8개씩, 세로로 11줄이에요.","필요한 타일은 8 × 11 = 88(개)예요.","도하는 가로 수와 세로 수를 더했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_challenge#5','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C9',3,'ox','auto','한 변이 ⟨8 3/4⟩ cm인 타일 100개로 한 변이 ⟨52 1/2⟩ cm인 정사각형 사물함 문을 겹치지 않게 가득 붙일 수 있어요.',ARRAY['M6-2-u1-X18']::text[],false,'{"seq":5,"concept":"M6-2-u1-C9","difficulty":3,"kind":"ox","stem":"한 변이 ⟨8 3/4⟩ cm인 타일 100개로 한 변이 ⟨52 1/2⟩ cm인 정사각형 사물함 문을 겹치지 않게 가득 붙일 수 있어요.","answer":"O","reason_options":[{"t":"한 변에 ⟨52 1/2⟩ ÷ ⟨8 3/4⟩ = 6개씩, 6 × 6 = 36개만 필요해서","correct":true},{"t":"타일이 사물함 문보다 작아서 100개로는 모자라서","mis":"M6-2-u1-X18"}],"mis":"M6-2-u1-X18","explanation":["⟨52 1/2⟩ ÷ ⟨8 3/4⟩ = ⟨105/2⟩ × ⟨4/35⟩ = 6이에요.","필요한 타일은 6 × 6 = 36(개)예요.","36개는 100개보다 적어 가득 붙일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_challenge#6','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C9',3,'mc','auto','타일 문제에서 꾸미고 싶은 것(벽 → 게시판 → 사물함 문)을 바꾸어 새로운 문제를 만들었어요. 바꾸어도 그대로인 것은 무엇인가요?',ARRAY['M6-2-u1-X18','M6-2-u1-X17']::text[],false,'{"seq":6,"concept":"M6-2-u1-C9","difficulty":3,"kind":"mc","stem":"타일 문제에서 꾸미고 싶은 것(벽 → 게시판 → 사물함 문)을 바꾸어 새로운 문제를 만들었어요. 바꾸어도 그대로인 것은 무엇인가요?","options":[{"t":"길이 ÷ 타일 한 변으로 가로·세로 타일 수를 구해 곱하는 방법","correct":true},{"t":"필요한 타일 수 88개","mis":"M6-2-u1-X18"},{"t":"타일 한 변의 길이 ⟨7 1/2⟩ cm","mis":"M6-2-u1-X18"},{"t":"가로 타일 수와 세로 타일 수를 더하는 방법","mis":"M6-2-u1-X17"}],"explanation":["조건(타일 크기·꾸밀 곳의 길이)이 바뀌면 답은 달라져요.","하지만 해결 방법은 같아요 — 길이 ÷ 타일 한 변, 그리고 가로 수 × 세로 수.","게시판은 40 × 16 = 640(개), 사물함 문은 6 × 6 = 36(개)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_challenge#7','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C6',3,'sa','auto','「알쏭달쏭 가로세로 나눗셈」의 한 줄이에요. 6 ÷ ⟨1/6⟩의 몫을 다시 ⟨9/10⟩로 나누면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M6-2-u1-C6","difficulty":3,"kind":"sa","stem":"「알쏭달쏭 가로세로 나눗셈」의 한 줄이에요. 6 ÷ ⟨1/6⟩의 몫을 다시 ⟨9/10⟩로 나누면 얼마인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["6 ÷ ⟨1/6⟩ = 6 × 6 = 36이에요.","36 ÷ ⟨9/10⟩ = 36 × ⟨10/9⟩ = 40.","앞 식의 몫이 다음 식의 나누어지는 수가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_challenge#8','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C9',4,'essay','teacher','한 변이 ⟨8 3/4⟩ cm인 정사각형 타일로 한 변이 ⟨52 1/2⟩ cm인 정사각형 모양 사물함 문을 꾸미는 문제를 만들고, 필요한 타일 수를 구하는 과정을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u1-C9","difficulty":4,"kind":"essay","stem":"한 변이 ⟨8 3/4⟩ cm인 정사각형 타일로 한 변이 ⟨52 1/2⟩ cm인 정사각형 모양 사물함 문을 꾸미는 문제를 만들고, 필요한 타일 수를 구하는 과정을 써 보세요.","answer_guide":{"answer":"예: 문제 — 한 변이 ⟨8 3/4⟩ cm인 타일로 한 변이 ⟨52 1/2⟩ cm인 사물함 문을 겹치지 않게 가득 붙이려면 타일은 몇 개 필요한가요? 풀이 — 한 변에 붙일 타일 수는 ⟨52 1/2⟩ ÷ ⟨8 3/4⟩ = ⟨105/2⟩ × ⟨4/35⟩ = 6(개)이고, 필요한 타일은 6 × 6 = 36(개)이다.","scoring_points":["꾸미고 싶은 것과 조건을 넣어 문제를 만들었는가","⟨52 1/2⟩ ÷ ⟨8 3/4⟩ = 6을 구했는가","6 × 6 = 36(개)로 답했는가"]},"explanation":["한 변에 붙일 타일 수: ⟨52 1/2⟩ ÷ ⟨8 3/4⟩ = 6(개).","정사각형이라 6 × 6 = 36(개)예요.","조건이 바뀌어도 해결 방법은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_challenge#9','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C2',4,'mc','auto','길이가 ⟨16/17⟩ m인 철사를 모두 사용하여 한 변의 길이가 ⟨2/17⟩ m인 정다각형을 한 개 만들었어요. 만든 정다각형의 이름은 무엇인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X03','M6-2-u1-X05']::text[],false,'{"seq":9,"concept":"M6-2-u1-C2","difficulty":4,"kind":"mc","stem":"길이가 ⟨16/17⟩ m인 철사를 모두 사용하여 한 변의 길이가 ⟨2/17⟩ m인 정다각형을 한 개 만들었어요. 만든 정다각형의 이름은 무엇인가요?","options":[{"t":"정팔각형","correct":true},{"t":"정육각형","mis":"M6-2-u1-X02"},{"t":"정칠각형","mis":"M6-2-u1-X03"},{"t":"정사각형","mis":"M6-2-u1-X05"}],"explanation":["변의 수는 철사의 길이를 한 변의 길이로 나누어 구해요.","⟨16/17⟩ ÷ ⟨2/17⟩ = 16 ÷ 2 = 8.","변이 8개인 정다각형 — 정팔각형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_L09_challenge#10','math',6,2,'u1','L09','tb_g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C8',4,'mc','auto','길이가 ⟨3 1/3⟩ km인 산책로의 한쪽에 처음부터 끝까지 ⟨5/18⟩ km 간격으로 나무를 심으려고 해요. 필요한 나무는 몇 그루인가요? (나무의 두께는 생각하지 않아요.)',ARRAY['M6-2-u1-X18']::text[],false,'{"seq":10,"concept":"M6-2-u1-C8","difficulty":4,"kind":"mc","stem":"길이가 ⟨3 1/3⟩ km인 산책로의 한쪽에 처음부터 끝까지 ⟨5/18⟩ km 간격으로 나무를 심으려고 해요. 필요한 나무는 몇 그루인가요? (나무의 두께는 생각하지 않아요.)","options":[{"t":"13그루","correct":true},{"t":"12그루","mis":"M6-2-u1-X18"},{"t":"11그루","mis":"M6-2-u1-X18"},{"t":"14그루","mis":"M6-2-u1-X18"}],"explanation":["간격의 수는 ⟨3 1/3⟩ ÷ ⟨5/18⟩ = ⟨10/3⟩ × ⟨18/5⟩ = 12예요.","처음부터 끝까지 심으니 나무는 간격 수보다 1 많아요.","필요한 나무는 12 + 1 = 13(그루)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#1','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C2',1,'sa','auto','그림을 보고 ⟨5/6⟩ ÷ ⟨1/6⟩을 계산해 보세요. 몫을 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M6-2-u1-C2","difficulty":1,"kind":"sa","stem":"그림을 보고 ⟨5/6⟩ ÷ ⟨1/6⟩을 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["5"],"explanation":["⟨5/6⟩는 ⟨1/6⟩이 5개, ⟨1/6⟩은 ⟨1/6⟩이 1개예요.","분모가 같으니 분자끼리 나눠요 — 5 ÷ 1 = 5.","분모 6은 조각의 크기라 몫에 남지 않아요."],"asset":{"type":"fbar","bars":[{"den":6,"num":5,"grp":1,"label":"⟨5/6⟩에서 ⟨1/6⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#2','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C4',1,'mc','auto','⟨2/3⟩ ÷ ⟨2/7⟩를 계산해 보세요.',ARRAY['M6-2-u1-X06','M6-2-u1-X10','M6-2-u1-X05']::text[],false,'{"seq":2,"concept":"M6-2-u1-C4","difficulty":1,"kind":"mc","stem":"⟨2/3⟩ ÷ ⟨2/7⟩를 계산해 보세요.","options":[{"t":"⟨2 1/3⟩","correct":true},{"t":"1","mis":"M6-2-u1-X06"},{"t":"⟨4/21⟩","mis":"M6-2-u1-X10"},{"t":"⟨3/7⟩","mis":"M6-2-u1-X05"}],"explanation":["분모가 다르니 먼저 통분해요 — ⟨2/3⟩ ÷ ⟨2/7⟩ = ⟨14/21⟩ ÷ ⟨6/21⟩.","분모가 같아졌으니 분자끼리 나눠요 — 14 ÷ 6 = ⟨14/6⟩ = ⟨2 1/3⟩.","조각의 크기를 같게 맞춘 뒤 개수끼리 나눈 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#3','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C5',1,'sa','auto','9 ÷ ⟨1/6⟩을 계산해 보세요. 몫을 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M6-2-u1-C5","difficulty":1,"kind":"sa","stem":"9 ÷ ⟨1/6⟩을 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["54"],"explanation":["1 안에는 ⟨1/6⟩이 6번 들어가요.","9 ÷ ⟨1/6⟩ = 9 × 6 = 54.","1보다 작은 수로 나누니 몫 54는 9보다 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#4','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C6',1,'mc','auto','6 ÷ ⟨5/8⟩를 계산해 보세요.',ARRAY['M6-2-u1-X10','M6-2-u1-X01','M6-2-u1-X22']::text[],false,'{"seq":4,"concept":"M6-2-u1-C6","difficulty":1,"kind":"mc","stem":"6 ÷ ⟨5/8⟩를 계산해 보세요.","options":[{"t":"⟨9 3/5⟩","correct":true},{"t":"⟨3 3/4⟩","mis":"M6-2-u1-X10"},{"t":"⟨5/48⟩","mis":"M6-2-u1-X01"},{"t":"⟨1 1/5⟩","mis":"M6-2-u1-X22"}],"explanation":["분자 5로 나누고 분모 8을 곱해요 — 6 ÷ ⟨5/8⟩ = 6 ÷ 5 × 8 = ⟨9 3/5⟩.","곱셈으로 나타내면 6 × ⟨8/5⟩ = ⟨9 3/5⟩.","나누는 분수의 분모와 분자를 바꾸어 곱한 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#5','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C8',1,'mc','auto','4 ÷ ⟨1 5/9⟩를 계산해 보세요.',ARRAY['M6-2-u1-X14','M6-2-u1-X13','M6-2-u1-X10']::text[],false,'{"seq":5,"concept":"M6-2-u1-C8","difficulty":1,"kind":"mc","stem":"4 ÷ ⟨1 5/9⟩를 계산해 보세요.","options":[{"t":"⟨2 4/7⟩","correct":true},{"t":"6","mis":"M6-2-u1-X14"},{"t":"⟨11 1/5⟩","mis":"M6-2-u1-X13"},{"t":"⟨6 2/9⟩","mis":"M6-2-u1-X10"}],"explanation":["대분수를 가분수로 고쳐요 — 4 ÷ ⟨1 5/9⟩ = 4 ÷ ⟨14/9⟩.","곱셈으로 나타내면 4 × ⟨9/14⟩ = ⟨2 4/7⟩.","대분수는 먼저 가분수로 고친 뒤 분수의 나눗셈을 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#6','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C7',1,'match','auto','나눗셈의 몫이 같은 것끼리 이으세요.','{}'::text[],false,'{"seq":6,"concept":"M6-2-u1-C7","difficulty":1,"kind":"match","stem":"나눗셈의 몫이 같은 것끼리 이으세요.","pairs":[{"l":"⟨2/9⟩ ÷ ⟨3/4⟩","r":"⟨1 1/3⟩ ÷ ⟨4 1/2⟩"},{"l":"⟨3/8⟩ ÷ ⟨5/7⟩","r":"⟨1 2/5⟩ ÷ ⟨2 2/3⟩"},{"l":"⟨1/4⟩ ÷ ⟨3/5⟩","r":"⟨25/36⟩ ÷ ⟨1 2/3⟩"}],"mis":"M6-2-u1-X13","explanation":["⟨2/9⟩ ÷ ⟨3/4⟩ = ⟨8/27⟩, ⟨1 1/3⟩ ÷ ⟨4 1/2⟩ = ⟨4/3⟩ × ⟨2/9⟩ = ⟨8/27⟩.","⟨3/8⟩ ÷ ⟨5/7⟩ = ⟨21/40⟩, ⟨1 2/5⟩ ÷ ⟨2 2/3⟩ = ⟨7/5⟩ × ⟨3/8⟩ = ⟨21/40⟩.","⟨1/4⟩ ÷ ⟨3/5⟩ = ⟨5/12⟩, ⟨25/36⟩ ÷ ⟨1 2/3⟩ = ⟨25/36⟩ × ⟨3/5⟩ = ⟨5/12⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#7','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C6',1,'sa','auto','물 8 L를 한 통에 ⟨2/3⟩ L씩 나누어 담으려고 해요. 물을 담을 통은 몇 개가 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M6-2-u1-C6","difficulty":1,"kind":"sa","stem":"물 8 L를 한 통에 ⟨2/3⟩ L씩 나누어 담으려고 해요. 물을 담을 통은 몇 개가 필요한가요? 숫자로 쓰세요.","answer":["12"],"explanation":["식은 8 ÷ ⟨2/3⟩예요.","8 ÷ ⟨2/3⟩ = 8 × ⟨3/2⟩ = 12.","답은 12개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#8','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C3',1,'mc','auto','⟨10/11⟩, ⟨7/11⟩, ⟨4/11⟩, ⟨3/11⟩, ⟨5/11⟩ 가운데 가장 큰 분수를 가장 작은 분수로 나눈 몫은 얼마인가요?',ARRAY['M6-2-u1-X21']::text[],false,'{"seq":8,"concept":"M6-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨10/11⟩, ⟨7/11⟩, ⟨4/11⟩, ⟨3/11⟩, ⟨5/11⟩ 가운데 가장 큰 분수를 가장 작은 분수로 나눈 몫은 얼마인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨3/10⟩","mis":"M6-2-u1-X21"},{"t":"⟨1 3/7⟩","mis":"M6-2-u1-X21"},{"t":"2","mis":"M6-2-u1-X21"}],"explanation":["가장 큰 분수는 ⟨10/11⟩, 가장 작은 분수는 ⟨3/11⟩이에요.","⟨10/11⟩ ÷ ⟨3/11⟩ = 10 ÷ 3 = ⟨10/3⟩ = ⟨3 1/3⟩.","가장 큰 수를 가장 작은 수로 나누면 몫이 가장 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#9','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C7',2,'mc','auto','세호는 ⟨3/4⟩ ÷ ⟨8/9⟩ = ⟨3/4⟩ × ⟨8/9⟩ = ⟨2/3⟩로 잘못 계산했어요. 바르게 계산한 몫은 얼마인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X12','M6-2-u1-X06']::text[],false,'{"seq":9,"concept":"M6-2-u1-C7","difficulty":2,"kind":"mc","stem":"세호는 ⟨3/4⟩ ÷ ⟨8/9⟩ = ⟨3/4⟩ × ⟨8/9⟩ = ⟨2/3⟩로 잘못 계산했어요. 바르게 계산한 몫은 얼마인가요?","options":[{"t":"⟨27/32⟩","correct":true},{"t":"⟨2/3⟩","mis":"M6-2-u1-X10"},{"t":"⟨1 5/27⟩","mis":"M6-2-u1-X12"},{"t":"⟨3/8⟩","mis":"M6-2-u1-X06"}],"explanation":["세호는 나누는 분수 ⟨8/9⟩의 분모와 분자를 바꾸지 않았어요.","⟨3/4⟩ ÷ ⟨8/9⟩ = ⟨3/4⟩ × ⟨9/8⟩ = ⟨27/32⟩.","아진이처럼 ⟨8/11⟩ ÷ ⟨2/3⟩ = ⟨8/11⟩ × ⟨3/2⟩으로 바꾸어 곱해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#10','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C4',2,'mc','auto','텃밭의 대파 길이는 ⟨3/4⟩ m, 부추 길이는 ⟨3/8⟩ m예요. 대파 길이는 부추 길이의 몇 배인가요?',ARRAY['M6-2-u1-X23','M6-2-u1-X06','M6-2-u1-X10']::text[],false,'{"seq":10,"concept":"M6-2-u1-C4","difficulty":2,"kind":"mc","stem":"텃밭의 대파 길이는 ⟨3/4⟩ m, 부추 길이는 ⟨3/8⟩ m예요. 대파 길이는 부추 길이의 몇 배인가요?","options":[{"t":"2배","correct":true},{"t":"⟨1/2⟩배","mis":"M6-2-u1-X23"},{"t":"1배","mis":"M6-2-u1-X06"},{"t":"⟨9/32⟩배","mis":"M6-2-u1-X10"}],"explanation":["몇 배인지는 기준인 부추 길이로 나눠요 — ⟨3/4⟩ ÷ ⟨3/8⟩.","⟨3/4⟩ ÷ ⟨3/8⟩ = ⟨6/8⟩ ÷ ⟨3/8⟩ = 6 ÷ 3 = 2.","대파는 부추의 2배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#11','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C5',2,'sa','auto','로봇이 주스 5 L를 만드는 데 ⟨1/3⟩시간이 걸렸어요. 1시간 동안 만들 수 있는 주스는 몇 L인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M6-2-u1-C5","difficulty":2,"kind":"sa","stem":"로봇이 주스 5 L를 만드는 데 ⟨1/3⟩시간이 걸렸어요. 1시간 동안 만들 수 있는 주스는 몇 L인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["1시간은 ⟨1/3⟩시간의 3배예요.","5 ÷ ⟨1/3⟩ = 5 × 3 = 15.","1시간 동안 15 L를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#12','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C7',2,'mc','auto','쌀 ⟨2/5⟩ kg을 빈 통에 담았더니 통의 ⟨3/4⟩이 찼어요. 한 통을 가득 채울 수 있는 쌀은 몇 kg인가요?',ARRAY['M6-2-u1-X22','M6-2-u1-X10','M6-2-u1-X01']::text[],false,'{"seq":12,"concept":"M6-2-u1-C7","difficulty":2,"kind":"mc","stem":"쌀 ⟨2/5⟩ kg을 빈 통에 담았더니 통의 ⟨3/4⟩이 찼어요. 한 통을 가득 채울 수 있는 쌀은 몇 kg인가요?","options":[{"t":"⟨8/15⟩","correct":true},{"t":"⟨2/15⟩","mis":"M6-2-u1-X22"},{"t":"⟨3/10⟩","mis":"M6-2-u1-X10"},{"t":"⟨1 7/8⟩","mis":"M6-2-u1-X01"}],"explanation":["통의 ⟨1/4⟩: ⟨2/5⟩ ÷ 3 = ⟨2/15⟩ kg이에요.","한 통: ⟨2/15⟩ × 4 = ⟨8/15⟩ kg이에요.","⟨2/5⟩ ÷ ⟨3/4⟩ = ⟨2/5⟩ × ⟨4/3⟩ = ⟨8/15⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#13','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C8',2,'mc','auto','넓이가 ⟨1 4/5⟩ m²이고 가로가 ⟨1 1/2⟩ m인 직사각형 모양 천의 세로는 몇 m인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X01','M6-2-u1-X03']::text[],false,'{"seq":13,"concept":"M6-2-u1-C8","difficulty":2,"kind":"mc","stem":"넓이가 ⟨1 4/5⟩ m²이고 가로가 ⟨1 1/2⟩ m인 직사각형 모양 천의 세로는 몇 m인가요?","options":[{"t":"⟨1 1/5⟩","correct":true},{"t":"⟨2 3/5⟩","mis":"M6-2-u1-X13"},{"t":"⟨5/6⟩","mis":"M6-2-u1-X01"},{"t":"⟨2 7/10⟩","mis":"M6-2-u1-X03"}],"explanation":["세로 = 넓이 ÷ 가로 = ⟨1 4/5⟩ ÷ ⟨1 1/2⟩.","⟨9/5⟩ ÷ ⟨3/2⟩ = ⟨9/5⟩ × ⟨2/3⟩ = ⟨6/5⟩ = ⟨1 1/5⟩.","천의 세로는 ⟨1 1/5⟩ m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#14','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C2',2,'ox','auto','⟨10/17⟩ ÷ ⟨2/17⟩ = ⟨5/17⟩예요.',ARRAY['M6-2-u1-X02']::text[],false,'{"seq":14,"concept":"M6-2-u1-C2","difficulty":2,"kind":"ox","stem":"⟨10/17⟩ ÷ ⟨2/17⟩ = ⟨5/17⟩예요.","answer":"X","reason_options":[{"t":"분모가 같으면 분자끼리 나누어 몫은 10 ÷ 2 = 5고 분모는 남지 않아서","correct":true},{"t":"분자끼리 나누고 분모는 그대로 두어야 해서","mis":"M6-2-u1-X02"}],"mis":"M6-2-u1-X02","explanation":["⟨10/17⟩은 ⟨1/17⟩이 10개, ⟨2/17⟩는 ⟨1/17⟩이 2개예요.","⟨10/17⟩ ÷ ⟨2/17⟩ = 10 ÷ 2 = 5.","몫은 5 — 분모를 그대로 두면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#15','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C9',2,'sa','auto','한 변이 ⟨7 1/2⟩ cm인 정사각형 타일을 가로 60 cm인 벽에 붙이려고 해요. 벽의 가로에 붙일 수 있는 타일은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M6-2-u1-C9","difficulty":2,"kind":"sa","stem":"한 변이 ⟨7 1/2⟩ cm인 정사각형 타일을 가로 60 cm인 벽에 붙이려고 해요. 벽의 가로에 붙일 수 있는 타일은 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["60 ÷ ⟨7 1/2⟩ = 60 ÷ ⟨15/2⟩예요.","60 × ⟨2/15⟩ = 8.","가로에 타일 8개를 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#16','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C1',2,'mc','auto','엄마가 만든 복숭아잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 들어가는 작은 유리병에 나누어 담으려고 해요. 필요한 유리병의 수를 구하는 알맞은 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X03']::text[],false,'{"seq":16,"concept":"M6-2-u1-C1","difficulty":2,"kind":"mc","stem":"엄마가 만든 복숭아잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 들어가는 작은 유리병에 나누어 담으려고 해요. 필요한 유리병의 수를 구하는 알맞은 식은 어느 것인가요?","options":[{"t":"⟨3/5⟩ ÷ ⟨1/5⟩","correct":true},{"t":"⟨1/5⟩ ÷ ⟨3/5⟩","mis":"M6-2-u1-X01"},{"t":"⟨3/5⟩ × ⟨1/5⟩","mis":"M6-2-u1-X03"},{"t":"⟨3/5⟩ − ⟨1/5⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨3/5⟩ kg에서 ⟨1/5⟩ kg씩 몇 번 덜어 내는지 묻고 있어요.","같은 양씩 덜어 내거나 1에 해당하는 양을 구하는 것은 나눗셈이에요.","나누어지는 양이 앞, 나누는 양이 뒤 — ⟨3/5⟩ ÷ ⟨1/5⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#17','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C9',3,'sa','auto','한 변이 ⟨7 1/2⟩ cm인 정사각형 타일로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 벽을 겹치지 않게 가득 붙이려고 해요. 필요한 타일은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M6-2-u1-C9","difficulty":3,"kind":"sa","stem":"한 변이 ⟨7 1/2⟩ cm인 정사각형 타일로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 벽을 겹치지 않게 가득 붙이려고 해요. 필요한 타일은 몇 개인가요? 숫자로 쓰세요.","answer":["88"],"explanation":["가로: 60 ÷ ⟨7 1/2⟩ = 8(개), 세로: ⟨82 1/2⟩ ÷ ⟨7 1/2⟩ = 11(개).","필요한 타일은 8 × 11 = 88(개)예요.","가로 수와 세로 수를 곱해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#18','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C8',3,'mc','auto','어떤 수를 ⟨5 1/2⟩로 나누어야 할 것을 잘못하여 곱했더니 ⟨2 3/4⟩이 되었어요. 어떤 수는 얼마인가요?',ARRAY['M6-2-u1-X19','M6-2-u1-X01']::text[],false,'{"seq":18,"concept":"M6-2-u1-C8","difficulty":3,"kind":"mc","stem":"어떤 수를 ⟨5 1/2⟩로 나누어야 할 것을 잘못하여 곱했더니 ⟨2 3/4⟩이 되었어요. 어떤 수는 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨15 1/8⟩","mis":"M6-2-u1-X19"},{"t":"2","mis":"M6-2-u1-X01"},{"t":"⟨2 3/4⟩","mis":"M6-2-u1-X19"}],"explanation":["어떤 수를 □라 하면 □ × ⟨5 1/2⟩ = ⟨2 3/4⟩이에요.","□ = ⟨2 3/4⟩ ÷ ⟨5 1/2⟩ = ⟨11/4⟩ × ⟨2/11⟩ = ⟨1/2⟩.","어떤 수는 ⟨1/2⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#19','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C6',3,'mc','auto','몫이 가장 큰 것은 어느 것인가요?',ARRAY['M6-2-u1-X16']::text[],false,'{"seq":19,"concept":"M6-2-u1-C6","difficulty":3,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"7 ÷ ⟨3/7⟩","correct":true},{"t":"12 ÷ ⟨9/11⟩","mis":"M6-2-u1-X16"},{"t":"10 ÷ ⟨5/8⟩","mis":"M6-2-u1-X16"},{"t":"8 ÷ ⟨4/7⟩","mis":"M6-2-u1-X16"}],"explanation":["7 ÷ ⟨3/7⟩ = ⟨16 1/3⟩, 10 ÷ ⟨5/8⟩ = 16이에요.","12 ÷ ⟨9/11⟩ = ⟨14 2/3⟩, 8 ÷ ⟨4/7⟩ = 14예요.","가장 큰 것은 7 ÷ ⟨3/7⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#20','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C8',3,'mc','auto','가로세로 나눗셈 퍼즐이에요. 4 ÷ ⟨2/9⟩의 몫을 ⟨2 1/4⟩로 나누면 얼마인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X10','M6-2-u1-X01']::text[],false,'{"seq":20,"concept":"M6-2-u1-C8","difficulty":3,"kind":"mc","stem":"가로세로 나눗셈 퍼즐이에요. 4 ÷ ⟨2/9⟩의 몫을 ⟨2 1/4⟩로 나누면 얼마인가요?","options":[{"t":"8","correct":true},{"t":"9","mis":"M6-2-u1-X13"},{"t":"⟨40 1/2⟩","mis":"M6-2-u1-X10"},{"t":"⟨1/8⟩","mis":"M6-2-u1-X01"}],"explanation":["4 ÷ ⟨2/9⟩ = 4 × ⟨9/2⟩ = 18이에요.","18 ÷ ⟨2 1/4⟩ = 18 × ⟨4/9⟩ = 8.","앞 몫이 다음 식의 나누어지는 수가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#21','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C5',3,'sa','auto','□ < 2 ÷ ⟨1/3⟩에서 □ 안에 들어갈 수 있는 가장 큰 자연수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M6-2-u1-C5","difficulty":3,"kind":"sa","stem":"□ < 2 ÷ ⟨1/3⟩에서 □ 안에 들어갈 수 있는 가장 큰 자연수를 숫자로 쓰세요.","answer":["5"],"explanation":["2 ÷ ⟨1/3⟩ = 2 × 3 = 6이에요.","□ < 6이에요.","가장 큰 자연수는 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#22','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C3',3,'mc','auto','집에서 도서관까지는 ⟨4/11⟩ km, 집에서 공원까지는 ⟨9/11⟩ km예요. 집에서 도서관까지의 거리는 집에서 공원까지의 거리의 몇 배인가요?',ARRAY['M6-2-u1-X23','M6-2-u1-X03','M6-2-u1-X02']::text[],false,'{"seq":22,"concept":"M6-2-u1-C3","difficulty":3,"kind":"mc","stem":"집에서 도서관까지는 ⟨4/11⟩ km, 집에서 공원까지는 ⟨9/11⟩ km예요. 집에서 도서관까지의 거리는 집에서 공원까지의 거리의 몇 배인가요?","options":[{"t":"⟨4/9⟩배","correct":true},{"t":"⟨2 1/4⟩배","mis":"M6-2-u1-X23"},{"t":"⟨5/11⟩배","mis":"M6-2-u1-X03"},{"t":"⟨4/99⟩배","mis":"M6-2-u1-X02"}],"explanation":["기준은 「~의」 앞의 공원까지의 거리예요.","⟨4/11⟩ ÷ ⟨9/11⟩ = 4 ÷ 9 = ⟨4/9⟩.","도서관까지의 거리는 공원까지의 ⟨4/9⟩배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#23','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C8',4,'mc','auto','직사각형 가의 넓이는 ⟨6 2/9⟩ cm²이고, 가의 넓이는 직사각형 나의 넓이의 ⟨2 1/3⟩배예요. 직사각형 나의 가로가 ⟨4/5⟩ cm일 때 나의 세로는 몇 cm인가요?',ARRAY['M6-2-u1-X22','M6-2-u1-X10','M6-2-u1-X18']::text[],false,'{"seq":23,"concept":"M6-2-u1-C8","difficulty":4,"kind":"mc","stem":"직사각형 가의 넓이는 ⟨6 2/9⟩ cm²이고, 가의 넓이는 직사각형 나의 넓이의 ⟨2 1/3⟩배예요. 직사각형 나의 가로가 ⟨4/5⟩ cm일 때 나의 세로는 몇 cm인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨2 2/3⟩","mis":"M6-2-u1-X22"},{"t":"⟨2 2/15⟩","mis":"M6-2-u1-X10"},{"t":"⟨7 7/9⟩","mis":"M6-2-u1-X18"}],"explanation":["나의 넓이 = ⟨6 2/9⟩ ÷ ⟨2 1/3⟩ = ⟨56/9⟩ × ⟨3/7⟩ = ⟨2 2/3⟩ cm²예요.","나의 세로 = ⟨2 2/3⟩ ÷ ⟨4/5⟩ = ⟨8/3⟩ × ⟨5/4⟩ = ⟨3 1/3⟩.","나의 넓이를 먼저 구한 뒤 가로로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#24','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C3',4,'mc','auto','조건에 맞는 분수의 나눗셈식은 어느 것인가요? — 진분수끼리의 나눗셈 · 두 분수의 분모는 같고 9 이하 · 8 ÷ 5를 이용하여 계산할 수 있음',ARRAY['M6-2-u1-X05','M6-2-u1-X18']::text[],false,'{"seq":24,"concept":"M6-2-u1-C3","difficulty":4,"kind":"mc","stem":"조건에 맞는 분수의 나눗셈식은 어느 것인가요? — 진분수끼리의 나눗셈 · 두 분수의 분모는 같고 9 이하 · 8 ÷ 5를 이용하여 계산할 수 있음","options":[{"t":"⟨8/9⟩ ÷ ⟨5/9⟩","correct":true},{"t":"⟨5/9⟩ ÷ ⟨8/9⟩","mis":"M6-2-u1-X05"},{"t":"⟨8/11⟩ ÷ ⟨5/11⟩","mis":"M6-2-u1-X18"},{"t":"⟨8/9⟩ ÷ ⟨5/8⟩","mis":"M6-2-u1-X18"}],"explanation":["분자가 8과 5고 분모가 같아야 8 ÷ 5로 계산할 수 있어요.","진분수이고 분모가 9 이하이니 분모는 9예요.","⟨8/9⟩ ÷ ⟨5/9⟩ = 8 ÷ 5 = ⟨1 3/5⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_a#25','math',6,2,'u1','','tb_g6_2_math_u1_review_a','unit_review','M6-2-u1-C9',4,'essay','teacher','한 변이 ⟨8 3/4⟩ cm인 정사각형 타일로 가로 350 cm, 세로 140 cm인 게시판을 꾸미는 문제를 만들고, 필요한 타일 수를 구하는 과정을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u1-C9","difficulty":4,"kind":"essay","stem":"한 변이 ⟨8 3/4⟩ cm인 정사각형 타일로 가로 350 cm, 세로 140 cm인 게시판을 꾸미는 문제를 만들고, 필요한 타일 수를 구하는 과정을 써 보세요.","answer_guide":{"answer":"예: 문제 — 게시판을 겹치지 않게 가득 붙이는 데 필요한 타일은 몇 개인가요? 풀이 — 가로에 350 ÷ ⟨8 3/4⟩ = 40(개), 세로에 140 ÷ ⟨8 3/4⟩ = 16(개)를 붙이므로 필요한 타일은 40 × 16 = 640(개)이다.","scoring_points":["조건을 넣어 문제를 만들었는가","가로 40개·세로 16개를 구했는가","40 × 16 = 640(개)로 답했는가"]},"explanation":["가로: 350 ÷ ⟨8 3/4⟩ = 40(개).","세로: 140 ÷ ⟨8 3/4⟩ = 16(개).","40 × 16 = 640(개)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#1','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C2',1,'sa','auto','그림을 보고 ⟨4/7⟩ ÷ ⟨1/7⟩을 계산해 보세요. 몫을 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M6-2-u1-C2","difficulty":1,"kind":"sa","stem":"그림을 보고 ⟨4/7⟩ ÷ ⟨1/7⟩을 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["4"],"explanation":["⟨4/7⟩는 ⟨1/7⟩이 4개, ⟨1/7⟩은 ⟨1/7⟩이 1개예요.","분모가 같으니 분자끼리 나눠요 — 4 ÷ 1 = 4.","분모 7은 조각의 크기라 몫에 남지 않아요."],"asset":{"type":"fbar","bars":[{"den":7,"num":4,"grp":1,"label":"⟨4/7⟩에서 ⟨1/7⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#2','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C4',1,'mc','auto','⟨3/5⟩ ÷ ⟨3/10⟩을 계산해 보세요.',ARRAY['M6-2-u1-X06','M6-2-u1-X10','M6-2-u1-X05']::text[],false,'{"seq":2,"concept":"M6-2-u1-C4","difficulty":1,"kind":"mc","stem":"⟨3/5⟩ ÷ ⟨3/10⟩을 계산해 보세요.","options":[{"t":"2","correct":true},{"t":"1","mis":"M6-2-u1-X06"},{"t":"⟨9/50⟩","mis":"M6-2-u1-X10"},{"t":"⟨1/2⟩","mis":"M6-2-u1-X05"}],"explanation":["분모가 다르니 먼저 통분해요 — ⟨3/5⟩ ÷ ⟨3/10⟩ = ⟨6/10⟩ ÷ ⟨3/10⟩.","분모가 같아졌으니 분자끼리 나눠요 — 6 ÷ 3 = 2.","조각의 크기를 같게 맞춘 뒤 개수끼리 나눈 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#3','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C5',1,'sa','auto','10 ÷ ⟨1/9⟩을 계산해 보세요. 몫을 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M6-2-u1-C5","difficulty":1,"kind":"sa","stem":"10 ÷ ⟨1/9⟩을 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["90"],"explanation":["1 안에는 ⟨1/9⟩이 9번 들어가요.","10 ÷ ⟨1/9⟩ = 10 × 9 = 90.","1보다 작은 수로 나누니 몫 90은 10보다 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#4','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C6',1,'mc','auto','2 ÷ ⟨5/6⟩를 계산해 보세요.',ARRAY['M6-2-u1-X10','M6-2-u1-X01','M6-2-u1-X22']::text[],false,'{"seq":4,"concept":"M6-2-u1-C6","difficulty":1,"kind":"mc","stem":"2 ÷ ⟨5/6⟩를 계산해 보세요.","options":[{"t":"⟨2 2/5⟩","correct":true},{"t":"⟨1 2/3⟩","mis":"M6-2-u1-X10"},{"t":"⟨5/12⟩","mis":"M6-2-u1-X01"},{"t":"⟨2/5⟩","mis":"M6-2-u1-X22"}],"explanation":["분자 5로 나누고 분모 6을 곱해요 — 2 ÷ ⟨5/6⟩ = 2 ÷ 5 × 6 = ⟨2 2/5⟩.","곱셈으로 나타내면 2 × ⟨6/5⟩ = ⟨2 2/5⟩.","나누는 분수의 분모와 분자를 바꾸어 곱한 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#5','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C8',1,'mc','auto','9 ÷ ⟨1 2/3⟩를 계산해 보세요.',ARRAY['M6-2-u1-X14','M6-2-u1-X13','M6-2-u1-X10']::text[],false,'{"seq":5,"concept":"M6-2-u1-C8","difficulty":1,"kind":"mc","stem":"9 ÷ ⟨1 2/3⟩를 계산해 보세요.","options":[{"t":"⟨5 2/5⟩","correct":true},{"t":"9","mis":"M6-2-u1-X14"},{"t":"⟨22 1/2⟩","mis":"M6-2-u1-X13"},{"t":"15","mis":"M6-2-u1-X10"}],"explanation":["대분수를 가분수로 고쳐요 — 9 ÷ ⟨1 2/3⟩ = 9 ÷ ⟨5/3⟩.","곱셈으로 나타내면 9 × ⟨3/5⟩ = ⟨5 2/5⟩.","대분수는 먼저 가분수로 고친 뒤 분수의 나눗셈을 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#6','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C7',1,'match','auto','나눗셈과 관계있는 곱셈을 찾아 이으세요.','{}'::text[],false,'{"seq":6,"concept":"M6-2-u1-C7","difficulty":1,"kind":"match","stem":"나눗셈과 관계있는 곱셈을 찾아 이으세요.","pairs":[{"l":"⟨5/7⟩ ÷ ⟨2/9⟩","r":"⟨5/7⟩ × ⟨9/2⟩"},{"l":"⟨4/5⟩ ÷ ⟨5/6⟩","r":"⟨4/5⟩ × ⟨6/5⟩"},{"l":"⟨7/8⟩ ÷ ⟨2/3⟩","r":"⟨7/8⟩ × ⟨3/2⟩"}],"mis":"M6-2-u1-X10","explanation":["나눗셈을 곱셈으로 나타낼 때 나누는 분수의 분모와 분자를 바꿔요.","⟨2/9⟩ → ⟨9/2⟩, ⟨5/6⟩ → ⟨6/5⟩, ⟨2/3⟩ → ⟨3/2⟩이에요.","나누어지는 분수는 그대로 둬요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#7','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C5',1,'sa','auto','주스 3 L를 하루에 ⟨1/7⟩ L씩 매일 마시려고 해요. 며칠 동안 마실 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M6-2-u1-C5","difficulty":1,"kind":"sa","stem":"주스 3 L를 하루에 ⟨1/7⟩ L씩 매일 마시려고 해요. 며칠 동안 마실 수 있나요? 숫자로 쓰세요.","answer":["21"],"explanation":["식은 3 ÷ ⟨1/7⟩이에요.","3 ÷ ⟨1/7⟩ = 3 × 7 = 21.","답은 21일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#8','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C3',1,'mc','auto','⟨3/13⟩, ⟨10/13⟩, ⟨7/13⟩ 가운데 가장 큰 분수를 가장 작은 분수로 나눈 몫은 얼마인가요?',ARRAY['M6-2-u1-X21']::text[],false,'{"seq":8,"concept":"M6-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨3/13⟩, ⟨10/13⟩, ⟨7/13⟩ 가운데 가장 큰 분수를 가장 작은 분수로 나눈 몫은 얼마인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨3/10⟩","mis":"M6-2-u1-X21"},{"t":"⟨1 3/7⟩","mis":"M6-2-u1-X21"},{"t":"⟨2 1/3⟩","mis":"M6-2-u1-X21"}],"explanation":["가장 큰 분수는 ⟨10/13⟩, 가장 작은 분수는 ⟨3/13⟩이에요.","⟨10/13⟩ ÷ ⟨3/13⟩ = 10 ÷ 3 = ⟨3 1/3⟩.","작은 수를 큰 수로 나누면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#9','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C7',2,'mc','auto','친구가 ⟨8/15⟩ ÷ ⟨4/5⟩ = ⟨8/15⟩ × ⟨4/5⟩ = ⟨32/75⟩로 잘못 계산했어요. 바르게 계산한 몫은 얼마인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X12','M6-2-u1-X06']::text[],false,'{"seq":9,"concept":"M6-2-u1-C7","difficulty":2,"kind":"mc","stem":"친구가 ⟨8/15⟩ ÷ ⟨4/5⟩ = ⟨8/15⟩ × ⟨4/5⟩ = ⟨32/75⟩로 잘못 계산했어요. 바르게 계산한 몫은 얼마인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨32/75⟩","mis":"M6-2-u1-X10"},{"t":"⟨1 1/2⟩","mis":"M6-2-u1-X12"},{"t":"2","mis":"M6-2-u1-X06"}],"explanation":["나누는 분수의 분모와 분자를 바꾸지 않았어요.","⟨8/15⟩ ÷ ⟨4/5⟩ = ⟨8/15⟩ × ⟨5/4⟩ = ⟨2/3⟩.","바른 몫은 ⟨2/3⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#10','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C4',2,'mc','auto','은수가 산 돼지고기는 ⟨3/5⟩ kg, 닭고기는 ⟨2/9⟩ kg이에요. 돼지고기 양은 닭고기 양의 몇 배인가요?',ARRAY['M6-2-u1-X23','M6-2-u1-X06','M6-2-u1-X10']::text[],false,'{"seq":10,"concept":"M6-2-u1-C4","difficulty":2,"kind":"mc","stem":"은수가 산 돼지고기는 ⟨3/5⟩ kg, 닭고기는 ⟨2/9⟩ kg이에요. 돼지고기 양은 닭고기 양의 몇 배인가요?","options":[{"t":"⟨2 7/10⟩배","correct":true},{"t":"⟨10/27⟩배","mis":"M6-2-u1-X23"},{"t":"⟨1 1/2⟩배","mis":"M6-2-u1-X06"},{"t":"⟨2/15⟩배","mis":"M6-2-u1-X10"}],"explanation":["⟨3/5⟩ ÷ ⟨2/9⟩로 구해요.","⟨3/5⟩ ÷ ⟨2/9⟩ = ⟨27/45⟩ ÷ ⟨10/45⟩ = 27 ÷ 10 = ⟨2 7/10⟩.","돼지고기는 닭고기의 ⟨2 7/10⟩배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#11','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C5',2,'sa','auto','진수는 자전거로 2 km를 가는 데 ⟨1/3⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 몇 km를 갈 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M6-2-u1-C5","difficulty":2,"kind":"sa","stem":"진수는 자전거로 2 km를 가는 데 ⟨1/3⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 몇 km를 갈 수 있나요? 숫자로 쓰세요.","answer":["6"],"explanation":["1시간은 ⟨1/3⟩시간의 3배예요.","2 ÷ ⟨1/3⟩ = 2 × 3 = 6.","1시간 동안 6 km를 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#12','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C7',2,'mc','auto','효준이가 딸기 ⟨7/9⟩ kg을 따는 데 ⟨2/5⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 딸 수 있는 딸기는 몇 kg인가요?',ARRAY['M6-2-u1-X22','M6-2-u1-X10','M6-2-u1-X01']::text[],false,'{"seq":12,"concept":"M6-2-u1-C7","difficulty":2,"kind":"mc","stem":"효준이가 딸기 ⟨7/9⟩ kg을 따는 데 ⟨2/5⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 딸 수 있는 딸기는 몇 kg인가요?","options":[{"t":"⟨1 17/18⟩","correct":true},{"t":"⟨7/18⟩","mis":"M6-2-u1-X22"},{"t":"⟨14/45⟩","mis":"M6-2-u1-X10"},{"t":"⟨18/35⟩","mis":"M6-2-u1-X01"}],"explanation":["⟨1/5⟩시간 동안 ⟨7/9⟩ ÷ 2 = ⟨7/18⟩ kg이에요.","1시간 동안 ⟨7/18⟩ × 5 = ⟨35/18⟩ kg이에요.","⟨7/9⟩ ÷ ⟨2/5⟩ = ⟨1 17/18⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#13','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C8',2,'mc','auto','넓이가 ⟨4 2/5⟩ m²이고 가로가 ⟨2 2/5⟩ m인 직사각형의 세로는 몇 m인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X01','M6-2-u1-X03']::text[],false,'{"seq":13,"concept":"M6-2-u1-C8","difficulty":2,"kind":"mc","stem":"넓이가 ⟨4 2/5⟩ m²이고 가로가 ⟨2 2/5⟩ m인 직사각형의 세로는 몇 m인가요?","options":[{"t":"⟨1 5/6⟩","correct":true},{"t":"3","mis":"M6-2-u1-X13"},{"t":"⟨6/11⟩","mis":"M6-2-u1-X01"},{"t":"⟨10 14/25⟩","mis":"M6-2-u1-X03"}],"explanation":["세로 = ⟨4 2/5⟩ ÷ ⟨2 2/5⟩.","⟨22/5⟩ ÷ ⟨12/5⟩ = 22 ÷ 12 = ⟨1 5/6⟩.","세로는 ⟨1 5/6⟩ m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#14','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C2',2,'ox','auto','⟨6/7⟩ ÷ ⟨2/7⟩ = 3이에요.',ARRAY['M6-2-u1-X02']::text[],false,'{"seq":14,"concept":"M6-2-u1-C2","difficulty":2,"kind":"ox","stem":"⟨6/7⟩ ÷ ⟨2/7⟩ = 3이에요.","answer":"O","reason_options":[{"t":"⟨1/7⟩ 6개를 ⟨1/7⟩ 2개씩 덜어 내면 3번이어서","correct":true},{"t":"분모 7이 몫에 남아야 해서","mis":"M6-2-u1-X02"}],"mis":"M6-2-u1-X02","explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개, ⟨2/7⟩는 ⟨1/7⟩이 2개예요.","⟨6/7⟩ ÷ ⟨2/7⟩ = 6 ÷ 2 = 3.","분모는 몫에 남지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#15','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C9',2,'sa','auto','한 변이 ⟨7 1/2⟩ cm인 정사각형 타일을 세로 ⟨82 1/2⟩ cm인 벽에 붙이려고 해요. 벽의 세로에 붙일 수 있는 타일은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M6-2-u1-C9","difficulty":2,"kind":"sa","stem":"한 변이 ⟨7 1/2⟩ cm인 정사각형 타일을 세로 ⟨82 1/2⟩ cm인 벽에 붙이려고 해요. 벽의 세로에 붙일 수 있는 타일은 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["⟨82 1/2⟩ ÷ ⟨7 1/2⟩ = ⟨165/2⟩ ÷ ⟨15/2⟩예요.","165 ÷ 15 = 11.","세로에 타일 11개를 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#16','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C1',2,'mc','auto','끈 ⟨4/5⟩ m로 한 장에 ⟨1/5⟩ m씩 쓰는 편지를 꾸며요. 꾸밀 수 있는 편지 수를 구하는 알맞은 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X03']::text[],false,'{"seq":16,"concept":"M6-2-u1-C1","difficulty":2,"kind":"mc","stem":"끈 ⟨4/5⟩ m로 한 장에 ⟨1/5⟩ m씩 쓰는 편지를 꾸며요. 꾸밀 수 있는 편지 수를 구하는 알맞은 식은 어느 것인가요?","options":[{"t":"⟨4/5⟩ ÷ ⟨1/5⟩","correct":true},{"t":"⟨1/5⟩ ÷ ⟨4/5⟩","mis":"M6-2-u1-X01"},{"t":"⟨4/5⟩ × ⟨1/5⟩","mis":"M6-2-u1-X03"},{"t":"⟨4/5⟩ − ⟨1/5⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨4/5⟩ m에서 ⟨1/5⟩ m씩 몇 번 덜어 내는지 묻고 있어요.","같은 양씩 덜어 내거나 1에 해당하는 양을 구하는 것은 나눗셈이에요.","나누어지는 양이 앞, 나누는 양이 뒤 — ⟨4/5⟩ ÷ ⟨1/5⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#17','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C9',3,'sa','auto','한 변이 ⟨8 3/4⟩ cm인 정사각형 타일로 가로 350 cm, 세로 140 cm인 게시판을 겹치지 않게 가득 붙이려고 해요. 필요한 타일은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M6-2-u1-C9","difficulty":3,"kind":"sa","stem":"한 변이 ⟨8 3/4⟩ cm인 정사각형 타일로 가로 350 cm, 세로 140 cm인 게시판을 겹치지 않게 가득 붙이려고 해요. 필요한 타일은 몇 개인가요? 숫자로 쓰세요.","answer":["640"],"explanation":["가로: 350 ÷ ⟨8 3/4⟩ = 40(개), 세로: 140 ÷ ⟨8 3/4⟩ = 16(개).","필요한 타일은 40 × 16 = 640(개)예요.","가로 수와 세로 수를 곱해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#18','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C5',3,'mc','auto','어떤 수를 ⟨1/6⟩로 나누어야 할 것을 잘못하여 곱했더니 18이 되었어요. 어떤 수는 얼마인가요?',ARRAY['M6-2-u1-X19','M6-2-u1-X01']::text[],false,'{"seq":18,"concept":"M6-2-u1-C5","difficulty":3,"kind":"mc","stem":"어떤 수를 ⟨1/6⟩로 나누어야 할 것을 잘못하여 곱했더니 18이 되었어요. 어떤 수는 얼마인가요?","options":[{"t":"108","correct":true},{"t":"3","mis":"M6-2-u1-X19"},{"t":"18","mis":"M6-2-u1-X19"},{"t":"⟨1/108⟩","mis":"M6-2-u1-X01"}],"explanation":["□ × ⟨1/6⟩ = 18이에요.","□ = 18 ÷ ⟨1/6⟩ = 18 × 6 = 108.","어떤 수는 108이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#19','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C4',3,'mc','auto','계산 결과가 큰 것부터 차례로 쓴 것은 어느 것인가요? ㉠ ⟨15/16⟩ ÷ ⟨5/16⟩ ㉡ ⟨7/18⟩ ÷ ⟨8/9⟩ ㉢ ⟨2/5⟩ ÷ ⟨3/10⟩',ARRAY['M6-2-u1-X20','M6-2-u1-X06','M6-2-u1-X16']::text[],false,'{"seq":19,"concept":"M6-2-u1-C4","difficulty":3,"kind":"mc","stem":"계산 결과가 큰 것부터 차례로 쓴 것은 어느 것인가요? ㉠ ⟨15/16⟩ ÷ ⟨5/16⟩ ㉡ ⟨7/18⟩ ÷ ⟨8/9⟩ ㉢ ⟨2/5⟩ ÷ ⟨3/10⟩","options":[{"t":"㉠, ㉢, ㉡","correct":true},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u1-X20"},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u1-X06"},{"t":"㉢, ㉠, ㉡","mis":"M6-2-u1-X16"}],"explanation":["㉠ = 15 ÷ 5 = 3이에요.","㉡ = 7 ÷ 16 = ⟨7/16⟩, ㉢ = 4 ÷ 3 = ⟨1 1/3⟩이에요.","㉠, ㉢, ㉡ 순서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#20','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C8',3,'mc','auto','가로세로 나눗셈 퍼즐이에요. ⟨1/2⟩ ÷ ⟨1/9⟩의 몫을 ⟨3/4⟩으로 나누면 얼마인가요?',ARRAY['M6-2-u1-X18','M6-2-u1-X10','M6-2-u1-X01']::text[],false,'{"seq":20,"concept":"M6-2-u1-C8","difficulty":3,"kind":"mc","stem":"가로세로 나눗셈 퍼즐이에요. ⟨1/2⟩ ÷ ⟨1/9⟩의 몫을 ⟨3/4⟩으로 나누면 얼마인가요?","options":[{"t":"6","correct":true},{"t":"⟨4 1/2⟩","mis":"M6-2-u1-X18"},{"t":"⟨3 3/8⟩","mis":"M6-2-u1-X10"},{"t":"⟨1/6⟩","mis":"M6-2-u1-X01"}],"explanation":["⟨1/2⟩ ÷ ⟨1/9⟩ = ⟨1/2⟩ × 9 = ⟨4 1/2⟩이에요.","⟨4 1/2⟩ ÷ ⟨3/4⟩ = ⟨9/2⟩ × ⟨4/3⟩ = 6.","첫 몫에서 멈추지 않고 한 번 더 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#21','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C6',3,'sa','auto','9 ÷ ⟨6/7⟩ > □에서 □ 안에 들어갈 수 있는 가장 큰 자연수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M6-2-u1-C6","difficulty":3,"kind":"sa","stem":"9 ÷ ⟨6/7⟩ > □에서 □ 안에 들어갈 수 있는 가장 큰 자연수를 숫자로 쓰세요.","answer":["10"],"explanation":["9 ÷ ⟨6/7⟩ = 9 × ⟨7/6⟩ = ⟨21/2⟩ = ⟨10 1/2⟩이에요.","□ < ⟨10 1/2⟩이에요.","가장 큰 자연수는 10이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#22','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C3',3,'mc','auto','빨간색 끈은 ⟨7/8⟩ m, 노란색 끈은 ⟨5/8⟩ m예요. 빨간색 끈의 길이는 노란색 끈의 길이의 몇 배인가요?',ARRAY['M6-2-u1-X23','M6-2-u1-X03','M6-2-u1-X02']::text[],false,'{"seq":22,"concept":"M6-2-u1-C3","difficulty":3,"kind":"mc","stem":"빨간색 끈은 ⟨7/8⟩ m, 노란색 끈은 ⟨5/8⟩ m예요. 빨간색 끈의 길이는 노란색 끈의 길이의 몇 배인가요?","options":[{"t":"⟨1 2/5⟩배","correct":true},{"t":"⟨5/7⟩배","mis":"M6-2-u1-X23"},{"t":"⟨1/4⟩배","mis":"M6-2-u1-X03"},{"t":"⟨7/40⟩배","mis":"M6-2-u1-X02"}],"explanation":["기준은 노란색 끈이에요.","⟨7/8⟩ ÷ ⟨5/8⟩ = 7 ÷ 5 = ⟨1 2/5⟩.","빨간색 끈은 노란색 끈의 ⟨1 2/5⟩배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#23','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C8',4,'mc','auto','직사각형 가의 넓이는 ⟨8 2/5⟩ cm², 가로는 ⟨3 1/2⟩ cm예요. 직사각형 나는 가와 세로가 같고 가로가 ⟨3/4⟩ cm예요. 나의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u1-X22','M6-2-u1-X10','M6-2-u1-X18']::text[],false,'{"seq":23,"concept":"M6-2-u1-C8","difficulty":4,"kind":"mc","stem":"직사각형 가의 넓이는 ⟨8 2/5⟩ cm², 가로는 ⟨3 1/2⟩ cm예요. 직사각형 나는 가와 세로가 같고 가로가 ⟨3/4⟩ cm예요. 나의 넓이는 몇 cm²인가요?","options":[{"t":"⟨1 4/5⟩","correct":true},{"t":"⟨2 2/5⟩","mis":"M6-2-u1-X22"},{"t":"⟨29 2/5⟩","mis":"M6-2-u1-X10"},{"t":"⟨6 3/10⟩","mis":"M6-2-u1-X18"}],"explanation":["가의 세로 = ⟨8 2/5⟩ ÷ ⟨3 1/2⟩ = ⟨42/5⟩ × ⟨2/7⟩ = ⟨2 2/5⟩ cm예요.","나의 넓이 = ⟨3/4⟩ × ⟨2 2/5⟩ = ⟨3/4⟩ × ⟨12/5⟩ = ⟨1 4/5⟩.","세로를 먼저 구한 뒤 나의 넓이를 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#24','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C3',4,'mc','auto','조건에 맞는 분수의 나눗셈식은 어느 것인가요? — 7 ÷ 9를 이용하여 계산할 수 있음 · 분모가 11보다 작은 진분수끼리의 나눗셈 · 두 분수의 분모는 같음',ARRAY['M6-2-u1-X05','M6-2-u1-X18']::text[],false,'{"seq":24,"concept":"M6-2-u1-C3","difficulty":4,"kind":"mc","stem":"조건에 맞는 분수의 나눗셈식은 어느 것인가요? — 7 ÷ 9를 이용하여 계산할 수 있음 · 분모가 11보다 작은 진분수끼리의 나눗셈 · 두 분수의 분모는 같음","options":[{"t":"⟨7/10⟩ ÷ ⟨9/10⟩","correct":true},{"t":"⟨9/10⟩ ÷ ⟨7/10⟩","mis":"M6-2-u1-X05"},{"t":"⟨7/11⟩ ÷ ⟨9/11⟩","mis":"M6-2-u1-X18"},{"t":"⟨7/14⟩ ÷ ⟨9/14⟩","mis":"M6-2-u1-X18"}],"explanation":["분자가 7과 9고 분모가 같아야 해요.","진분수이려면 분모가 9보다 크고, 11보다 작아야 하니 분모는 10이에요.","⟨7/10⟩ ÷ ⟨9/10⟩ = 7 ÷ 9 = ⟨7/9⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_b#25','math',6,2,'u1','','tb_g6_2_math_u1_review_b','unit_review','M6-2-u1-C7',4,'essay','teacher','세호는 ⟨3/4⟩ ÷ ⟨8/9⟩ = ⟨3/4⟩ × ⟨8/9⟩ = ⟨2/3⟩로 계산했어요. 잘못 계산한 까닭을 쓰고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u1-C7","difficulty":4,"kind":"essay","stem":"세호는 ⟨3/4⟩ ÷ ⟨8/9⟩ = ⟨3/4⟩ × ⟨8/9⟩ = ⟨2/3⟩로 계산했어요. 잘못 계산한 까닭을 쓰고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 나눗셈을 곱셈으로 나타낼 때 나누는 분수 ⟨8/9⟩의 분모와 분자를 바꾸지 않았다. 바르게 계산하면 ⟨3/4⟩ ÷ ⟨8/9⟩ = ⟨3/4⟩ × ⟨9/8⟩ = ⟨27/32⟩이다.","scoring_points":["나누는 분수를 바꾸지 않은 것을 까닭으로 썼는가","⟨3/4⟩ × ⟨9/8⟩로 고쳤는가","⟨27/32⟩을 구했는가"]},"explanation":["나누는 분수 ⟨8/9⟩을 ⟨9/8⟩로 바꾸어 곱해요.","⟨3/4⟩ × ⟨9/8⟩ = ⟨27/32⟩.","나누어지는 분수는 그대로 둬요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#1','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C2',1,'sa','auto','그림을 보고 ⟨8/9⟩ ÷ ⟨2/9⟩를 계산해 보세요. 몫을 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M6-2-u1-C2","difficulty":1,"kind":"sa","stem":"그림을 보고 ⟨8/9⟩ ÷ ⟨2/9⟩를 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["4"],"explanation":["⟨8/9⟩은 ⟨1/9⟩이 8개, ⟨2/9⟩는 ⟨1/9⟩이 2개예요.","분모가 같으니 분자끼리 나눠요 — 8 ÷ 2 = 4.","분모 9는 조각의 크기라 몫에 남지 않아요."],"asset":{"type":"fbar","bars":[{"den":9,"num":8,"grp":2,"label":"⟨8/9⟩에서 ⟨2/9⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#2','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C4',1,'mc','auto','⟨7/8⟩ ÷ ⟨4/5⟩를 계산해 보세요.',ARRAY['M6-2-u1-X06','M6-2-u1-X10','M6-2-u1-X05']::text[],false,'{"seq":2,"concept":"M6-2-u1-C4","difficulty":1,"kind":"mc","stem":"⟨7/8⟩ ÷ ⟨4/5⟩를 계산해 보세요.","options":[{"t":"⟨1 3/32⟩","correct":true},{"t":"⟨1 3/4⟩","mis":"M6-2-u1-X06"},{"t":"⟨7/10⟩","mis":"M6-2-u1-X10"},{"t":"⟨32/35⟩","mis":"M6-2-u1-X05"}],"explanation":["분모가 다르니 먼저 통분해요 — ⟨7/8⟩ ÷ ⟨4/5⟩ = ⟨35/40⟩ ÷ ⟨32/40⟩.","분모가 같아졌으니 분자끼리 나눠요 — 35 ÷ 32 = ⟨35/32⟩ = ⟨1 3/32⟩.","조각의 크기를 같게 맞춘 뒤 개수끼리 나눈 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#3','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C5',1,'sa','auto','8 ÷ ⟨1/7⟩을 계산해 보세요. 몫을 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M6-2-u1-C5","difficulty":1,"kind":"sa","stem":"8 ÷ ⟨1/7⟩을 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["56"],"explanation":["1 안에는 ⟨1/7⟩이 7번 들어가요.","8 ÷ ⟨1/7⟩ = 8 × 7 = 56.","1보다 작은 수로 나누니 몫 56은 8보다 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#4','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C6',1,'mc','auto','9 ÷ ⟨3/5⟩을 계산해 보세요.',ARRAY['M6-2-u1-X10','M6-2-u1-X01','M6-2-u1-X22']::text[],false,'{"seq":4,"concept":"M6-2-u1-C6","difficulty":1,"kind":"mc","stem":"9 ÷ ⟨3/5⟩을 계산해 보세요.","options":[{"t":"15","correct":true},{"t":"⟨5 2/5⟩","mis":"M6-2-u1-X10"},{"t":"⟨1/15⟩","mis":"M6-2-u1-X01"},{"t":"3","mis":"M6-2-u1-X22"}],"explanation":["분자 3으로 나누고 분모 5를 곱해요 — 9 ÷ ⟨3/5⟩ = 9 ÷ 3 × 5 = 15.","곱셈으로 나타내면 9 × ⟨5/3⟩ = 15.","나누는 분수의 분모와 분자를 바꾸어 곱한 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#5','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C8',1,'mc','auto','⟨9/10⟩ ÷ ⟨1 4/5⟩를 계산해 보세요.',ARRAY['M6-2-u1-X14','M6-2-u1-X13','M6-2-u1-X10']::text[],false,'{"seq":5,"concept":"M6-2-u1-C8","difficulty":1,"kind":"mc","stem":"⟨9/10⟩ ÷ ⟨1 4/5⟩를 계산해 보세요.","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨9/10⟩","mis":"M6-2-u1-X14"},{"t":"⟨2 1/40⟩","mis":"M6-2-u1-X13"},{"t":"⟨1 31/50⟩","mis":"M6-2-u1-X10"}],"explanation":["대분수를 가분수로 고쳐요 — ⟨9/10⟩ ÷ ⟨1 4/5⟩ = ⟨9/10⟩ ÷ ⟨9/5⟩.","곱셈으로 나타내면 ⟨9/10⟩ × ⟨5/9⟩ = ⟨1/2⟩.","대분수는 먼저 가분수로 고친 뒤 분수의 나눗셈을 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#6','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C7',1,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"M6-2-u1-C7","difficulty":1,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨7/10⟩ ÷ ⟨4/5⟩","r":"⟨7/8⟩"},{"l":"⟨5/12⟩ ÷ ⟨3/4⟩","r":"⟨5/9⟩"},{"l":"⟨14/15⟩ ÷ ⟨4/5⟩","r":"⟨1 1/6⟩"}],"mis":"M6-2-u1-X10","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요.","⟨7/10⟩ × ⟨5/4⟩ = ⟨7/8⟩, ⟨5/12⟩ × ⟨4/3⟩ = ⟨5/9⟩.","⟨14/15⟩ × ⟨5/4⟩ = ⟨1 1/6⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#7','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C8',1,'sa','auto','간장 ⟨7 1/2⟩ L를 병 한 개에 ⟨5/6⟩ L씩 모두 옮겨 담으려고 해요. 병은 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M6-2-u1-C8","difficulty":1,"kind":"sa","stem":"간장 ⟨7 1/2⟩ L를 병 한 개에 ⟨5/6⟩ L씩 모두 옮겨 담으려고 해요. 병은 몇 개 필요한가요? 숫자로 쓰세요.","answer":["9"],"explanation":["식은 ⟨7 1/2⟩ ÷ ⟨5/6⟩예요.","⟨15/2⟩ ÷ ⟨5/6⟩ = ⟨15/2⟩ × ⟨6/5⟩ = 9.","답은 9개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#8','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C3',1,'mc','auto','수 카드 ⟨7/19⟩, ⟨8/19⟩, ⟨9/19⟩, ⟨10/19⟩, ⟨11/19⟩ 가운데 2장을 골라 만든 나눗셈식의 몫이 가장 클 때, 그 몫은 얼마인가요?',ARRAY['M6-2-u1-X21']::text[],false,'{"seq":8,"concept":"M6-2-u1-C3","difficulty":1,"kind":"mc","stem":"수 카드 ⟨7/19⟩, ⟨8/19⟩, ⟨9/19⟩, ⟨10/19⟩, ⟨11/19⟩ 가운데 2장을 골라 만든 나눗셈식의 몫이 가장 클 때, 그 몫은 얼마인가요?","options":[{"t":"⟨1 4/7⟩","correct":true},{"t":"⟨7/11⟩","mis":"M6-2-u1-X21"},{"t":"⟨1 1/10⟩","mis":"M6-2-u1-X21"},{"t":"⟨1 3/7⟩","mis":"M6-2-u1-X21"}],"explanation":["몫이 가장 크려면 가장 큰 ⟨11/19⟩을 가장 작은 ⟨7/19⟩로 나눠요.","⟨11/19⟩ ÷ ⟨7/19⟩ = 11 ÷ 7 = ⟨11/7⟩ = ⟨1 4/7⟩.","큰 수끼리 나누면 몫이 작아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#9','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C7',2,'mc','auto','친구가 ⟨7/15⟩ ÷ ⟨10/21⟩ = ⟨15/7⟩ × ⟨10/21⟩ = ⟨1 1/49⟩로 잘못 계산했어요. 바르게 계산한 몫은 얼마인가요?',ARRAY['M6-2-u1-X12','M6-2-u1-X10','M6-2-u1-X06']::text[],false,'{"seq":9,"concept":"M6-2-u1-C7","difficulty":2,"kind":"mc","stem":"친구가 ⟨7/15⟩ ÷ ⟨10/21⟩ = ⟨15/7⟩ × ⟨10/21⟩ = ⟨1 1/49⟩로 잘못 계산했어요. 바르게 계산한 몫은 얼마인가요?","options":[{"t":"⟨49/50⟩","correct":true},{"t":"⟨1 1/49⟩","mis":"M6-2-u1-X12"},{"t":"⟨2/9⟩","mis":"M6-2-u1-X10"},{"t":"⟨7/10⟩","mis":"M6-2-u1-X06"}],"explanation":["앞의 분수를 뒤집었어요 — 뒤집는 것은 나누는 분수뿐이에요.","⟨7/15⟩ ÷ ⟨10/21⟩ = ⟨7/15⟩ × ⟨21/10⟩ = ⟨49/50⟩.","바른 몫은 ⟨49/50⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#10','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C4',2,'mc','auto','종이 팩을 선우는 ⟨7/9⟩ kg, 연우는 ⟨7/12⟩ kg 모았어요. 선우가 모은 무게는 연우가 모은 무게의 몇 배인가요?',ARRAY['M6-2-u1-X23','M6-2-u1-X06','M6-2-u1-X10']::text[],false,'{"seq":10,"concept":"M6-2-u1-C4","difficulty":2,"kind":"mc","stem":"종이 팩을 선우는 ⟨7/9⟩ kg, 연우는 ⟨7/12⟩ kg 모았어요. 선우가 모은 무게는 연우가 모은 무게의 몇 배인가요?","options":[{"t":"⟨1 1/3⟩배","correct":true},{"t":"⟨3/4⟩배","mis":"M6-2-u1-X23"},{"t":"1배","mis":"M6-2-u1-X06"},{"t":"⟨49/108⟩배","mis":"M6-2-u1-X10"}],"explanation":["⟨7/9⟩ ÷ ⟨7/12⟩로 구해요.","⟨7/9⟩ ÷ ⟨7/12⟩ = ⟨28/36⟩ ÷ ⟨21/36⟩ = 28 ÷ 21 = ⟨1 1/3⟩.","선우는 연우의 ⟨1 1/3⟩배를 모았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#11','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C6',2,'sa','auto','3 km를 걷는 데 ⟨3/4⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 몇 km를 걸을 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M6-2-u1-C6","difficulty":2,"kind":"sa","stem":"3 km를 걷는 데 ⟨3/4⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 몇 km를 걸을 수 있나요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨1/4⟩시간 동안 3 ÷ 3 = 1 km를 걸어요.","1시간은 ⟨1/4⟩시간의 4배 — 1 × 4 = 4.","3 ÷ ⟨3/4⟩ = 3 × ⟨4/3⟩ = 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#12','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C6',2,'mc','auto','굵기가 일정한 막대 ⟨3/4⟩ m의 무게가 9 kg이에요. 이 막대 1 m의 무게는 몇 kg인가요?',ARRAY['M6-2-u1-X22','M6-2-u1-X10','M6-2-u1-X01']::text[],false,'{"seq":12,"concept":"M6-2-u1-C6","difficulty":2,"kind":"mc","stem":"굵기가 일정한 막대 ⟨3/4⟩ m의 무게가 9 kg이에요. 이 막대 1 m의 무게는 몇 kg인가요?","options":[{"t":"12","correct":true},{"t":"3","mis":"M6-2-u1-X22"},{"t":"⟨6 3/4⟩","mis":"M6-2-u1-X10"},{"t":"⟨1/12⟩","mis":"M6-2-u1-X01"}],"explanation":["⟨1/4⟩ m의 무게는 9 ÷ 3 = 3 kg이에요.","1 m는 ⟨1/4⟩ m의 4배 — 3 × 4 = 12.","9 ÷ ⟨3/4⟩ = 9 × ⟨4/3⟩ = 12 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#13','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C8',2,'mc','auto','넓이가 ⟨5 3/5⟩ m²인 평행사변형의 밑변의 길이가 ⟨7/10⟩ m예요. 높이는 몇 m인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X03','M6-2-u1-X13']::text[],false,'{"seq":13,"concept":"M6-2-u1-C8","difficulty":2,"kind":"mc","stem":"넓이가 ⟨5 3/5⟩ m²인 평행사변형의 밑변의 길이가 ⟨7/10⟩ m예요. 높이는 몇 m인가요?","options":[{"t":"8","correct":true},{"t":"⟨1/8⟩","mis":"M6-2-u1-X01"},{"t":"⟨3 23/25⟩","mis":"M6-2-u1-X03"},{"t":"⟨7 1/7⟩","mis":"M6-2-u1-X13"}],"explanation":["높이 = 넓이 ÷ 밑변의 길이 = ⟨5 3/5⟩ ÷ ⟨7/10⟩.","⟨28/5⟩ × ⟨10/7⟩ = 8.","높이는 8 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#14','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C2',2,'ox','auto','⟨9/14⟩ ÷ ⟨3/14⟩ = ⟨3/14⟩이에요.',ARRAY['M6-2-u1-X02']::text[],false,'{"seq":14,"concept":"M6-2-u1-C2","difficulty":2,"kind":"ox","stem":"⟨9/14⟩ ÷ ⟨3/14⟩ = ⟨3/14⟩이에요.","answer":"X","reason_options":[{"t":"분자끼리 나누어 몫은 9 ÷ 3 = 3이고 분모는 남지 않아서","correct":true},{"t":"분자끼리 나누고 분모는 그대로 두어야 해서","mis":"M6-2-u1-X02"}],"mis":"M6-2-u1-X02","explanation":["⟨9/14⟩는 ⟨1/14⟩이 9개, ⟨3/14⟩은 ⟨1/14⟩이 3개예요.","⟨9/14⟩ ÷ ⟨3/14⟩ = 9 ÷ 3 = 3.","몫은 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#15','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C9',2,'sa','auto','한 변이 ⟨8 3/4⟩ cm인 정사각형 타일을 가로 350 cm인 게시판에 붙이려고 해요. 게시판의 가로에 붙일 수 있는 타일은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M6-2-u1-C9","difficulty":2,"kind":"sa","stem":"한 변이 ⟨8 3/4⟩ cm인 정사각형 타일을 가로 350 cm인 게시판에 붙이려고 해요. 게시판의 가로에 붙일 수 있는 타일은 몇 개인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["350 ÷ ⟨8 3/4⟩ = 350 ÷ ⟨35/4⟩예요.","350 × ⟨4/35⟩ = 40.","가로에 타일 40개를 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#16','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C1',2,'mc','auto','물 ⟨6/11⟩ L를 한 병에 ⟨2/11⟩ L씩 나누어 담아요. 필요한 병의 수를 구하는 알맞은 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X03']::text[],false,'{"seq":16,"concept":"M6-2-u1-C1","difficulty":2,"kind":"mc","stem":"물 ⟨6/11⟩ L를 한 병에 ⟨2/11⟩ L씩 나누어 담아요. 필요한 병의 수를 구하는 알맞은 식은 어느 것인가요?","options":[{"t":"⟨6/11⟩ ÷ ⟨2/11⟩","correct":true},{"t":"⟨2/11⟩ ÷ ⟨6/11⟩","mis":"M6-2-u1-X01"},{"t":"⟨6/11⟩ × ⟨2/11⟩","mis":"M6-2-u1-X03"},{"t":"⟨6/11⟩ − ⟨2/11⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨6/11⟩ L에서 ⟨2/11⟩ L씩 몇 번 덜어 내는지 묻고 있어요.","같은 양씩 덜어 내거나 1에 해당하는 양을 구하는 것은 나눗셈이에요.","나누어지는 양이 앞, 나누는 양이 뒤 — ⟨6/11⟩ ÷ ⟨2/11⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#17','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C9',3,'sa','auto','한 변이 ⟨8 3/4⟩ cm인 정사각형 타일로 한 변이 ⟨52 1/2⟩ cm인 정사각형 사물함 문을 겹치지 않게 가득 붙이려고 해요. 필요한 타일은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M6-2-u1-C9","difficulty":3,"kind":"sa","stem":"한 변이 ⟨8 3/4⟩ cm인 정사각형 타일로 한 변이 ⟨52 1/2⟩ cm인 정사각형 사물함 문을 겹치지 않게 가득 붙이려고 해요. 필요한 타일은 몇 개인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["한 변: ⟨52 1/2⟩ ÷ ⟨8 3/4⟩ = 6(개).","필요한 타일은 6 × 6 = 36(개)예요.","정사각형이라 가로와 세로의 타일 수가 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#18','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C3',3,'mc','auto','어떤 수를 ⟨4/15⟩로 나누어야 할 것을 잘못하여 더했더니 1이 되었어요. 바르게 계산한 값은 얼마인가요?',ARRAY['M6-2-u1-X18','M6-2-u1-X19','M6-2-u1-X05']::text[],false,'{"seq":18,"concept":"M6-2-u1-C3","difficulty":3,"kind":"mc","stem":"어떤 수를 ⟨4/15⟩로 나누어야 할 것을 잘못하여 더했더니 1이 되었어요. 바르게 계산한 값은 얼마인가요?","options":[{"t":"⟨2 3/4⟩","correct":true},{"t":"⟨11/15⟩","mis":"M6-2-u1-X18"},{"t":"⟨3 3/4⟩","mis":"M6-2-u1-X19"},{"t":"⟨4/11⟩","mis":"M6-2-u1-X05"}],"explanation":["어떤 수는 1 − ⟨4/15⟩ = ⟨11/15⟩이에요.","바르게 계산하면 ⟨11/15⟩ ÷ ⟨4/15⟩ = 11 ÷ 4 = ⟨2 3/4⟩.","어떤 수를 찾은 뒤 바르게 나누어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#19','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C4',3,'mc','auto','계산 결과가 더 작은 것은 어느 것인가요? ㉠ ⟨11/12⟩ ÷ ⟨2/3⟩ ㉡ ⟨11/12⟩ ÷ ⟨3/4⟩',ARRAY['M6-2-u1-X16','M6-2-u1-X06','M6-2-u1-X20']::text[],false,'{"seq":19,"concept":"M6-2-u1-C4","difficulty":3,"kind":"mc","stem":"계산 결과가 더 작은 것은 어느 것인가요? ㉠ ⟨11/12⟩ ÷ ⟨2/3⟩ ㉡ ⟨11/12⟩ ÷ ⟨3/4⟩","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M6-2-u1-X16"},{"t":"두 몫이 같다","mis":"M6-2-u1-X06"},{"t":"알 수 없다","mis":"M6-2-u1-X20"}],"explanation":["㉠ = 11 ÷ 8 = ⟨1 3/8⟩이에요.","㉡ = 11 ÷ 9 = ⟨1 2/9⟩예요.","나누는 수가 더 큰 ㉡의 몫이 더 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#20','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C6',3,'mc','auto','가로세로 나눗셈 퍼즐이에요. 6 ÷ ⟨1/6⟩의 몫을 ⟨9/10⟩로 나누면 얼마인가요?',ARRAY['M6-2-u1-X18','M6-2-u1-X10','M6-2-u1-X01']::text[],false,'{"seq":20,"concept":"M6-2-u1-C6","difficulty":3,"kind":"mc","stem":"가로세로 나눗셈 퍼즐이에요. 6 ÷ ⟨1/6⟩의 몫을 ⟨9/10⟩로 나누면 얼마인가요?","options":[{"t":"40","correct":true},{"t":"36","mis":"M6-2-u1-X18"},{"t":"⟨32 2/5⟩","mis":"M6-2-u1-X10"},{"t":"⟨1/40⟩","mis":"M6-2-u1-X01"}],"explanation":["6 ÷ ⟨1/6⟩ = 6 × 6 = 36이에요.","36 ÷ ⟨9/10⟩ = 36 × ⟨10/9⟩ = 40.","첫 몫에서 멈추지 않고 한 번 더 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#21','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C6',3,'sa','auto','□ < 9 ÷ ⟨7/11⟩에서 □ 안에 들어갈 수 있는 가장 큰 자연수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M6-2-u1-C6","difficulty":3,"kind":"sa","stem":"□ < 9 ÷ ⟨7/11⟩에서 □ 안에 들어갈 수 있는 가장 큰 자연수를 숫자로 쓰세요.","answer":["14"],"explanation":["9 ÷ ⟨7/11⟩ = 9 × ⟨11/7⟩ = ⟨14 1/7⟩이에요.","□ < ⟨14 1/7⟩이에요.","가장 큰 자연수는 14예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#22','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C4',3,'mc','auto','㉠ ⟨2/5⟩ ÷ ⟨1/10⟩ ㉡ ⟨3/8⟩ ÷ ⟨5/6⟩ — ㉠은 ㉡의 몇 배인가요?',ARRAY['M6-2-u1-X23','M6-2-u1-X10','M6-2-u1-X18']::text[],false,'{"seq":22,"concept":"M6-2-u1-C4","difficulty":3,"kind":"mc","stem":"㉠ ⟨2/5⟩ ÷ ⟨1/10⟩ ㉡ ⟨3/8⟩ ÷ ⟨5/6⟩ — ㉠은 ㉡의 몇 배인가요?","options":[{"t":"⟨8 8/9⟩배","correct":true},{"t":"⟨9/80⟩배","mis":"M6-2-u1-X23"},{"t":"⟨1 4/5⟩배","mis":"M6-2-u1-X10"},{"t":"4배","mis":"M6-2-u1-X18"}],"explanation":["㉠ = ⟨4/10⟩ ÷ ⟨1/10⟩ = 4 ÷ 1 = 4, ㉡ = ⟨3/8⟩ × ⟨6/5⟩ = ⟨9/20⟩예요.","㉠은 ㉡의 4 ÷ ⟨9/20⟩ = 4 × ⟨20/9⟩ = ⟨8 8/9⟩배예요.","기준인 ㉡으로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#23','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C8',4,'mc','auto','⟨5/14⟩ ÷ ⟨1 3/7⟩과 ⟨2 2/5⟩ ÷ ⟨3 1/5⟩의 몫의 합은 얼마인가요?',ARRAY['M6-2-u1-X18','M6-2-u1-X05']::text[],false,'{"seq":23,"concept":"M6-2-u1-C8","difficulty":4,"kind":"mc","stem":"⟨5/14⟩ ÷ ⟨1 3/7⟩과 ⟨2 2/5⟩ ÷ ⟨3 1/5⟩의 몫의 합은 얼마인가요?","options":[{"t":"1","correct":true},{"t":"⟨1/4⟩","mis":"M6-2-u1-X18"},{"t":"⟨3/4⟩","mis":"M6-2-u1-X18"},{"t":"⟨5 1/3⟩","mis":"M6-2-u1-X05"}],"explanation":["⟨5/14⟩ ÷ ⟨1 3/7⟩ = ⟨5/14⟩ × ⟨7/10⟩ = ⟨1/4⟩이에요.","⟨2 2/5⟩ ÷ ⟨3 1/5⟩ = ⟨12/5⟩ × ⟨5/16⟩ = ⟨3/4⟩이에요.","두 몫의 합은 ⟨1/4⟩ + ⟨3/4⟩ = 1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#24','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C8',4,'mc','auto','길이가 ⟨3 1/3⟩ km인 산책로의 한쪽에 처음부터 끝까지 ⟨5/18⟩ km 간격으로 나무를 심으려고 해요. 필요한 나무는 몇 그루인가요? (나무의 두께는 생각하지 않아요.)',ARRAY['M6-2-u1-X18']::text[],false,'{"seq":24,"concept":"M6-2-u1-C8","difficulty":4,"kind":"mc","stem":"길이가 ⟨3 1/3⟩ km인 산책로의 한쪽에 처음부터 끝까지 ⟨5/18⟩ km 간격으로 나무를 심으려고 해요. 필요한 나무는 몇 그루인가요? (나무의 두께는 생각하지 않아요.)","options":[{"t":"13그루","correct":true},{"t":"12그루","mis":"M6-2-u1-X18"},{"t":"11그루","mis":"M6-2-u1-X18"},{"t":"14그루","mis":"M6-2-u1-X18"}],"explanation":["간격 수는 ⟨3 1/3⟩ ÷ ⟨5/18⟩ = ⟨10/3⟩ × ⟨18/5⟩ = 12예요.","처음과 끝에 모두 심으니 나무는 간격 수보다 1 많아요.","12 + 1 = 13(그루)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_c#25','math',6,2,'u1','','tb_g6_2_math_u1_review_c','unit_review','M6-2-u1-C6',4,'essay','teacher','물 8 L를 한 통에 ⟨2/3⟩ L씩 나누어 담으면 통이 12개 필요해요. 「나눗셈을 하면 결과가 작아진다」는 생각이 늘 맞지는 않음을 이 문제로 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u1-C6","difficulty":4,"kind":"essay","stem":"물 8 L를 한 통에 ⟨2/3⟩ L씩 나누어 담으면 통이 12개 필요해요. 「나눗셈을 하면 결과가 작아진다」는 생각이 늘 맞지는 않음을 이 문제로 설명해 보세요.","answer_guide":{"answer":"예: 8 ÷ ⟨2/3⟩ = 8 ÷ 2 × 3 = 12로 몫 12는 나누어지는 수 8보다 크다. 나누는 수 ⟨2/3⟩이 1보다 작아 8 안에 여러 번 들어가기 때문이다. 그래서 나눗셈 결과가 늘 작아지는 것은 아니다.","scoring_points":["8 ÷ ⟨2/3⟩ = 12를 바르게 구했는가","몫이 나누어지는 수보다 커졌음을 밝혔는가","1보다 작은 수로 나누면 몫이 커지는 까닭을 썼는가"]},"explanation":["8 ÷ ⟨2/3⟩ = 8 ÷ 2 × 3 = 12예요.","12는 8보다 커요.","1보다 작은 수로 나누면 몫이 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#1','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C2',1,'sa','auto','그림을 보고 ⟨4/7⟩ ÷ ⟨2/7⟩를 계산해 보세요. 몫을 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M6-2-u1-C2","difficulty":1,"kind":"sa","stem":"그림을 보고 ⟨4/7⟩ ÷ ⟨2/7⟩를 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["2"],"explanation":["⟨4/7⟩는 ⟨1/7⟩이 4개, ⟨2/7⟩는 ⟨1/7⟩이 2개예요.","분모가 같으니 분자끼리 나눠요 — 4 ÷ 2 = 2.","분모 7은 조각의 크기라 몫에 남지 않아요."],"asset":{"type":"fbar","bars":[{"den":7,"num":4,"grp":2,"label":"⟨4/7⟩에서 ⟨2/7⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#2','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C4',1,'mc','auto','⟨5/6⟩ ÷ ⟨3/8⟩을 계산해 보세요.',ARRAY['M6-2-u1-X06','M6-2-u1-X10','M6-2-u1-X05']::text[],false,'{"seq":2,"concept":"M6-2-u1-C4","difficulty":1,"kind":"mc","stem":"⟨5/6⟩ ÷ ⟨3/8⟩을 계산해 보세요.","options":[{"t":"⟨2 2/9⟩","correct":true},{"t":"⟨1 2/3⟩","mis":"M6-2-u1-X06"},{"t":"⟨5/16⟩","mis":"M6-2-u1-X10"},{"t":"⟨9/20⟩","mis":"M6-2-u1-X05"}],"explanation":["분모가 다르니 먼저 통분해요 — ⟨5/6⟩ ÷ ⟨3/8⟩ = ⟨20/24⟩ ÷ ⟨9/24⟩.","분모가 같아졌으니 분자끼리 나눠요 — 20 ÷ 9 = ⟨20/9⟩ = ⟨2 2/9⟩.","조각의 크기를 같게 맞춘 뒤 개수끼리 나눈 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#3','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C5',1,'sa','auto','2 ÷ ⟨1/4⟩을 계산해 보세요. 몫을 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M6-2-u1-C5","difficulty":1,"kind":"sa","stem":"2 ÷ ⟨1/4⟩을 계산해 보세요. 몫을 숫자로 쓰세요.","answer":["8"],"explanation":["1 안에는 ⟨1/4⟩이 4번 들어가요.","2 ÷ ⟨1/4⟩ = 2 × 4 = 8.","1보다 작은 수로 나누니 몫 8은 2보다 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#4','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C6',1,'mc','auto','8 ÷ ⟨4/9⟩를 계산해 보세요.',ARRAY['M6-2-u1-X10','M6-2-u1-X01','M6-2-u1-X22']::text[],false,'{"seq":4,"concept":"M6-2-u1-C6","difficulty":1,"kind":"mc","stem":"8 ÷ ⟨4/9⟩를 계산해 보세요.","options":[{"t":"18","correct":true},{"t":"⟨3 5/9⟩","mis":"M6-2-u1-X10"},{"t":"⟨1/18⟩","mis":"M6-2-u1-X01"},{"t":"2","mis":"M6-2-u1-X22"}],"explanation":["분자 4로 나누고 분모 9를 곱해요 — 8 ÷ ⟨4/9⟩ = 8 ÷ 4 × 9 = 18.","곱셈으로 나타내면 8 × ⟨9/4⟩ = 18.","나누는 분수의 분모와 분자를 바꾸어 곱한 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#5','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C8',1,'mc','auto','⟨2 1/4⟩ ÷ ⟨2/7⟩를 계산해 보세요.',ARRAY['M6-2-u1-X14','M6-2-u1-X13','M6-2-u1-X10']::text[],false,'{"seq":5,"concept":"M6-2-u1-C8","difficulty":1,"kind":"mc","stem":"⟨2 1/4⟩ ÷ ⟨2/7⟩를 계산해 보세요.","options":[{"t":"⟨7 7/8⟩","correct":true},{"t":"⟨2 5/8⟩","mis":"M6-2-u1-X14"},{"t":"⟨2 7/8⟩","mis":"M6-2-u1-X13"},{"t":"⟨9/14⟩","mis":"M6-2-u1-X10"}],"explanation":["대분수를 가분수로 고쳐요 — ⟨2 1/4⟩ ÷ ⟨2/7⟩ = ⟨9/4⟩ ÷ ⟨2/7⟩.","곱셈으로 나타내면 ⟨9/4⟩ × ⟨7/2⟩ = ⟨7 7/8⟩.","대분수는 먼저 가분수로 고친 뒤 분수의 나눗셈을 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#6','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C2',1,'match','auto','관계있는 것끼리 이으세요.','{}'::text[],false,'{"seq":6,"concept":"M6-2-u1-C2","difficulty":1,"kind":"match","stem":"관계있는 것끼리 이으세요.","pairs":[{"l":"⟨8/11⟩ ÷ ⟨4/11⟩","r":"8 ÷ 4"},{"l":"⟨9/10⟩ ÷ ⟨3/10⟩","r":"9 ÷ 3"},{"l":"⟨3/5⟩ ÷ ⟨3/10⟩","r":"6 ÷ 3"}],"mis":"M6-2-u1-X06","explanation":["분모가 같으면 분자끼리 나눠요 — ⟨8/11⟩ ÷ ⟨4/11⟩ = 8 ÷ 4.","⟨9/10⟩ ÷ ⟨3/10⟩ = 9 ÷ 3이에요.","⟨3/5⟩ = ⟨6/10⟩이라 ⟨3/5⟩ ÷ ⟨3/10⟩ = 6 ÷ 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#7','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C5',1,'sa','auto','밀가루 8 kg을 한 통에 ⟨1/4⟩ kg씩 나누어 담으려고 해요. 통은 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M6-2-u1-C5","difficulty":1,"kind":"sa","stem":"밀가루 8 kg을 한 통에 ⟨1/4⟩ kg씩 나누어 담으려고 해요. 통은 몇 개 필요한가요? 숫자로 쓰세요.","answer":["32"],"explanation":["식은 8 ÷ ⟨1/4⟩이에요.","8 ÷ ⟨1/4⟩ = 8 × 4 = 32.","답은 32개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#8','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C3',1,'mc','auto','⟨5/13⟩와 ⟨8/13⟩ 가운데 작은 수를 큰 수로 나눈 몫은 얼마인가요?',ARRAY['M6-2-u1-X05','M6-2-u1-X02','M6-2-u1-X03']::text[],false,'{"seq":8,"concept":"M6-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨5/13⟩와 ⟨8/13⟩ 가운데 작은 수를 큰 수로 나눈 몫은 얼마인가요?","options":[{"t":"⟨5/8⟩","correct":true},{"t":"⟨1 3/5⟩","mis":"M6-2-u1-X05"},{"t":"⟨5/104⟩","mis":"M6-2-u1-X02"},{"t":"⟨3/13⟩","mis":"M6-2-u1-X03"}],"explanation":["작은 수는 ⟨5/13⟩, 큰 수는 ⟨8/13⟩이에요.","⟨5/13⟩ ÷ ⟨8/13⟩ = 5 ÷ 8 = ⟨5/8⟩.","작은 수를 큰 수로 나누면 몫은 1보다 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#9','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C4',2,'mc','auto','친구가 ⟨3/4⟩ ÷ ⟨3/16⟩ = 3 ÷ 3 = 1로 잘못 계산했어요. 바르게 계산한 몫은 얼마인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X05','M6-2-u1-X03']::text[],false,'{"seq":9,"concept":"M6-2-u1-C4","difficulty":2,"kind":"mc","stem":"친구가 ⟨3/4⟩ ÷ ⟨3/16⟩ = 3 ÷ 3 = 1로 잘못 계산했어요. 바르게 계산한 몫은 얼마인가요?","options":[{"t":"4","correct":true},{"t":"1","mis":"M6-2-u1-X06"},{"t":"⟨1/4⟩","mis":"M6-2-u1-X05"},{"t":"⟨9/64⟩","mis":"M6-2-u1-X03"}],"explanation":["분모가 다른데 통분하지 않고 분자끼리 나누었어요.","⟨3/4⟩ ÷ ⟨3/16⟩ = ⟨12/16⟩ ÷ ⟨3/16⟩ = 12 ÷ 3 = 4.","바른 몫은 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#10','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C4',2,'mc','auto','준기의 필통은 ⟨5/6⟩ kg, 지수의 필통은 ⟨3/4⟩ kg이에요. 준기의 필통 무게는 지수의 필통 무게의 몇 배인가요?',ARRAY['M6-2-u1-X23','M6-2-u1-X06','M6-2-u1-X10']::text[],false,'{"seq":10,"concept":"M6-2-u1-C4","difficulty":2,"kind":"mc","stem":"준기의 필통은 ⟨5/6⟩ kg, 지수의 필통은 ⟨3/4⟩ kg이에요. 준기의 필통 무게는 지수의 필통 무게의 몇 배인가요?","options":[{"t":"⟨1 1/9⟩배","correct":true},{"t":"⟨9/10⟩배","mis":"M6-2-u1-X23"},{"t":"⟨1 2/3⟩배","mis":"M6-2-u1-X06"},{"t":"⟨5/8⟩배","mis":"M6-2-u1-X10"}],"explanation":["⟨5/6⟩ ÷ ⟨3/4⟩으로 구해요.","⟨5/6⟩ ÷ ⟨3/4⟩ = ⟨10/12⟩ ÷ ⟨9/12⟩ = 10 ÷ 9 = ⟨1 1/9⟩.","준기의 필통은 지수의 ⟨1 1/9⟩배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#11','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C6',2,'sa','auto','자전거로 4 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 몇 km를 갈 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M6-2-u1-C6","difficulty":2,"kind":"sa","stem":"자전거로 4 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 몇 km를 갈 수 있나요? 숫자로 쓰세요.","answer":["6"],"explanation":["⟨1/3⟩시간 동안 4 ÷ 2 = 2 km를 가요.","1시간은 ⟨1/3⟩시간의 3배 — 2 × 3 = 6.","4 ÷ ⟨2/3⟩ = 4 × ⟨3/2⟩ = 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#12','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C8',2,'mc','auto','무게가 ⟨3/4⟩ kg인 천 ⟨3 1/6⟩ m가 있어요. 천 1 m의 무게는 몇 kg인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X10','M6-2-u1-X13']::text[],false,'{"seq":12,"concept":"M6-2-u1-C8","difficulty":2,"kind":"mc","stem":"무게가 ⟨3/4⟩ kg인 천 ⟨3 1/6⟩ m가 있어요. 천 1 m의 무게는 몇 kg인가요?","options":[{"t":"⟨9/38⟩","correct":true},{"t":"⟨4 2/9⟩","mis":"M6-2-u1-X01"},{"t":"⟨2 3/8⟩","mis":"M6-2-u1-X10"},{"t":"⟨1/4⟩","mis":"M6-2-u1-X13"}],"explanation":["⟨3/4⟩ ÷ ⟨3 1/6⟩로 구해요.","⟨3/4⟩ ÷ ⟨19/6⟩ = ⟨3/4⟩ × ⟨6/19⟩ = ⟨9/38⟩.","천 1 m의 무게는 ⟨9/38⟩ kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#13','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C8',2,'mc','auto','넓이가 ⟨6 1/4⟩ m²인 벽을 칠하는 데 페인트 ⟨2 1/2⟩ L를 썼어요. 페인트 1 L로 칠한 넓이는 몇 m²인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X10','M6-2-u1-X13']::text[],false,'{"seq":13,"concept":"M6-2-u1-C8","difficulty":2,"kind":"mc","stem":"넓이가 ⟨6 1/4⟩ m²인 벽을 칠하는 데 페인트 ⟨2 1/2⟩ L를 썼어요. 페인트 1 L로 칠한 넓이는 몇 m²인가요?","options":[{"t":"⟨2 1/2⟩","correct":true},{"t":"⟨2/5⟩","mis":"M6-2-u1-X01"},{"t":"⟨15 5/8⟩","mis":"M6-2-u1-X10"},{"t":"3","mis":"M6-2-u1-X13"}],"explanation":["1 L로 칠한 넓이 = ⟨6 1/4⟩ ÷ ⟨2 1/2⟩.","⟨25/4⟩ × ⟨2/5⟩ = ⟨5/2⟩ = ⟨2 1/2⟩.","1 L로 ⟨2 1/2⟩ m²를 칠했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#14','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C2',2,'ox','auto','⟨10/11⟩ ÷ ⟨5/11⟩ = 2예요.',ARRAY['M6-2-u1-X02']::text[],false,'{"seq":14,"concept":"M6-2-u1-C2","difficulty":2,"kind":"ox","stem":"⟨10/11⟩ ÷ ⟨5/11⟩ = 2예요.","answer":"O","reason_options":[{"t":"⟨1/11⟩ 10개를 ⟨1/11⟩ 5개씩 덜어 내면 2번이어서","correct":true},{"t":"분모 11끼리도 나누어야 해서","mis":"M6-2-u1-X02"}],"mis":"M6-2-u1-X02","explanation":["⟨10/11⟩은 ⟨1/11⟩이 10개, ⟨5/11⟩는 ⟨1/11⟩이 5개예요.","⟨10/11⟩ ÷ ⟨5/11⟩ = 10 ÷ 5 = 2.","분모는 몫에 남지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#15','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C9',2,'sa','auto','한 변이 ⟨8 3/4⟩ cm인 정사각형 타일을 세로 140 cm인 게시판에 붙이려고 해요. 게시판의 세로에 붙일 수 있는 타일은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M6-2-u1-C9","difficulty":2,"kind":"sa","stem":"한 변이 ⟨8 3/4⟩ cm인 정사각형 타일을 세로 140 cm인 게시판에 붙이려고 해요. 게시판의 세로에 붙일 수 있는 타일은 몇 개인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["140 ÷ ⟨8 3/4⟩ = 140 ÷ ⟨35/4⟩예요.","140 × ⟨4/35⟩ = 16.","세로에 타일 16개를 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#16','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C6',2,'mc','auto','흙 15 kg을 화분 한 개에 ⟨3/20⟩ kg씩 나누어 담아요. 필요한 화분의 수를 구하는 알맞은 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X10','M6-2-u1-X03']::text[],false,'{"seq":16,"concept":"M6-2-u1-C6","difficulty":2,"kind":"mc","stem":"흙 15 kg을 화분 한 개에 ⟨3/20⟩ kg씩 나누어 담아요. 필요한 화분의 수를 구하는 알맞은 식은 어느 것인가요?","options":[{"t":"15 ÷ ⟨3/20⟩","correct":true},{"t":"⟨3/20⟩ ÷ 15","mis":"M6-2-u1-X01"},{"t":"15 × ⟨3/20⟩","mis":"M6-2-u1-X10"},{"t":"15 − ⟨3/20⟩","mis":"M6-2-u1-X03"}],"explanation":["흙 15 kg에서 ⟨3/20⟩ kg씩 몇 번 덜어 내는지 묻고 있어요.","같은 양씩 덜어 내거나 1에 해당하는 양을 구하는 것은 나눗셈이에요.","나누어지는 양이 앞, 나누는 양이 뒤 — 15 ÷ ⟨3/20⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#17','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C9',3,'ox','auto','한 변이 ⟨7 1/2⟩ cm인 타일 100개로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 벽을 겹치지 않게 가득 붙일 수 있어요.',ARRAY['M6-2-u1-X17']::text[],false,'{"seq":17,"concept":"M6-2-u1-C9","difficulty":3,"kind":"ox","stem":"한 변이 ⟨7 1/2⟩ cm인 타일 100개로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 벽을 겹치지 않게 가득 붙일 수 있어요.","answer":"O","reason_options":[{"t":"8 × 11 = 88개만 있으면 되어 100개로 충분해서","correct":true},{"t":"8 + 11 = 19개만 있으면 되어서","mis":"M6-2-u1-X17"}],"mis":"M6-2-u1-X17","explanation":["가로에 8개, 세로에 11개를 붙여요.","필요한 타일은 8 × 11 = 88(개)예요.","88개는 100개보다 적어 가득 붙일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#18','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C7',3,'mc','auto','□ × ⟨4/5⟩ = ⟨1/3⟩일 때 □는 어떤 수인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X01','M6-2-u1-X19']::text[],false,'{"seq":18,"concept":"M6-2-u1-C7","difficulty":3,"kind":"mc","stem":"□ × ⟨4/5⟩ = ⟨1/3⟩일 때 □는 어떤 수인가요?","options":[{"t":"⟨5/12⟩","correct":true},{"t":"⟨4/15⟩","mis":"M6-2-u1-X10"},{"t":"⟨2 2/5⟩","mis":"M6-2-u1-X01"},{"t":"⟨1/3⟩","mis":"M6-2-u1-X19"}],"explanation":["□ × 3 = 6이면 □ = 6 ÷ 3이듯이 나누어 구해요.","□ = ⟨1/3⟩ ÷ ⟨4/5⟩ = ⟨1/3⟩ × ⟨5/4⟩ = ⟨5/12⟩.","□는 ⟨5/12⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#19','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C6',3,'mc','auto','두 몫을 비교한 것으로 알맞은 것은 어느 것인가요? 8 ÷ ⟨3/4⟩ ○ 10 ÷ ⟨5/6⟩',ARRAY['M6-2-u1-X16','M6-2-u1-X11','M6-2-u1-X20']::text[],false,'{"seq":19,"concept":"M6-2-u1-C6","difficulty":3,"kind":"mc","stem":"두 몫을 비교한 것으로 알맞은 것은 어느 것인가요? 8 ÷ ⟨3/4⟩ ○ 10 ÷ ⟨5/6⟩","options":[{"t":"8 ÷ ⟨3/4⟩ < 10 ÷ ⟨5/6⟩","correct":true},{"t":"8 ÷ ⟨3/4⟩ > 10 ÷ ⟨5/6⟩","mis":"M6-2-u1-X16"},{"t":"8 ÷ ⟨3/4⟩ = 10 ÷ ⟨5/6⟩","mis":"M6-2-u1-X11"},{"t":"비교할 수 없다","mis":"M6-2-u1-X20"}],"explanation":["8 ÷ ⟨3/4⟩ = 8 × ⟨4/3⟩ = ⟨10 2/3⟩예요.","10 ÷ ⟨5/6⟩ = 10 × ⟨6/5⟩ = 12예요.","⟨10 2/3⟩ < 12예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#20','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C8',3,'mc','auto','가로세로 나눗셈 퍼즐이에요. 6을 ⟨2 1/4⟩ ÷ ⟨1 1/2⟩의 몫으로 나누면 얼마인가요?',ARRAY['M6-2-u1-X18','M6-2-u1-X10','M6-2-u1-X01']::text[],false,'{"seq":20,"concept":"M6-2-u1-C8","difficulty":3,"kind":"mc","stem":"가로세로 나눗셈 퍼즐이에요. 6을 ⟨2 1/4⟩ ÷ ⟨1 1/2⟩의 몫으로 나누면 얼마인가요?","options":[{"t":"4","correct":true},{"t":"⟨1 1/2⟩","mis":"M6-2-u1-X18"},{"t":"9","mis":"M6-2-u1-X10"},{"t":"⟨1/4⟩","mis":"M6-2-u1-X01"}],"explanation":["⟨2 1/4⟩ ÷ ⟨1 1/2⟩ = ⟨9/4⟩ × ⟨2/3⟩ = ⟨1 1/2⟩이에요.","6 ÷ ⟨1 1/2⟩ = 6 × ⟨2/3⟩ = 4.","가로식과 세로식이 같은 칸을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#21','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C5',3,'sa','auto','5 ÷ ⟨1/3⟩과 4 ÷ ⟨1/6⟩의 계산 결과의 차를 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M6-2-u1-C5","difficulty":3,"kind":"sa","stem":"5 ÷ ⟨1/3⟩과 4 ÷ ⟨1/6⟩의 계산 결과의 차를 숫자로 쓰세요.","answer":["9"],"explanation":["5 ÷ ⟨1/3⟩ = 15예요.","4 ÷ ⟨1/6⟩ = 24예요.","24 − 15 = 9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#22','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C3',3,'mc','auto','집에서 학교까지는 ⟨12/13⟩ km, 집에서 도서관까지는 ⟨5/13⟩ km예요. 집에서 학교까지의 거리는 집에서 도서관까지의 거리의 몇 배인가요?',ARRAY['M6-2-u1-X23','M6-2-u1-X03','M6-2-u1-X02']::text[],false,'{"seq":22,"concept":"M6-2-u1-C3","difficulty":3,"kind":"mc","stem":"집에서 학교까지는 ⟨12/13⟩ km, 집에서 도서관까지는 ⟨5/13⟩ km예요. 집에서 학교까지의 거리는 집에서 도서관까지의 거리의 몇 배인가요?","options":[{"t":"⟨2 2/5⟩배","correct":true},{"t":"⟨5/12⟩배","mis":"M6-2-u1-X23"},{"t":"⟨7/13⟩배","mis":"M6-2-u1-X03"},{"t":"⟨12/65⟩배","mis":"M6-2-u1-X02"}],"explanation":["기준은 도서관까지의 거리예요.","⟨12/13⟩ ÷ ⟨5/13⟩ = 12 ÷ 5 = ⟨2 2/5⟩.","학교까지의 거리는 도서관까지의 ⟨2 2/5⟩배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#23','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C8',4,'mc','auto','수 카드 4, 1, 5를 한 번씩 모두 이용하여 만들 수 있는 대분수 가운데 가장 큰 대분수를 가장 작은 대분수로 나눈 몫은 얼마인가요?',ARRAY['M6-2-u1-X21','M6-2-u1-X13','M6-2-u1-X14']::text[],false,'{"seq":23,"concept":"M6-2-u1-C8","difficulty":4,"kind":"mc","stem":"수 카드 4, 1, 5를 한 번씩 모두 이용하여 만들 수 있는 대분수 가운데 가장 큰 대분수를 가장 작은 대분수로 나눈 몫은 얼마인가요?","options":[{"t":"⟨2 11/12⟩","correct":true},{"t":"⟨12/35⟩","mis":"M6-2-u1-X21"},{"t":"⟨5 5/16⟩","mis":"M6-2-u1-X13"},{"t":"⟨1 1/2⟩","mis":"M6-2-u1-X14"}],"explanation":["가장 큰 대분수는 ⟨5 1/4⟩, 가장 작은 대분수는 ⟨1 4/5⟩예요.","⟨5 1/4⟩ ÷ ⟨1 4/5⟩ = ⟨21/4⟩ × ⟨5/9⟩ = ⟨2 11/12⟩.","가분수로 고친 뒤 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#24','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C8',4,'mc','auto','들이가 11 L인 통에 물이 ⟨2 3/7⟩ L 들어 있어요. 이 통에 물을 가득 채우려면 들이가 ⟨6/7⟩ L인 그릇으로 적어도 몇 번 더 부어야 하나요?',ARRAY['M6-2-u1-X18','M6-2-u1-X15']::text[],false,'{"seq":24,"concept":"M6-2-u1-C8","difficulty":4,"kind":"mc","stem":"들이가 11 L인 통에 물이 ⟨2 3/7⟩ L 들어 있어요. 이 통에 물을 가득 채우려면 들이가 ⟨6/7⟩ L인 그릇으로 적어도 몇 번 더 부어야 하나요?","options":[{"t":"10번","correct":true},{"t":"13번","mis":"M6-2-u1-X18"},{"t":"⟨2 5/6⟩번","mis":"M6-2-u1-X18"},{"t":"9번","mis":"M6-2-u1-X15"}],"explanation":["더 부어야 할 물은 11 − ⟨2 3/7⟩ = ⟨8 4/7⟩ L예요.","⟨8 4/7⟩ ÷ ⟨6/7⟩ = ⟨60/7⟩ ÷ ⟨6/7⟩ = 60 ÷ 6 = 10.","적어도 10번 더 부어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u1_review_d#25','math',6,2,'u1','','tb_g6_2_math_u1_review_d','unit_review','M6-2-u1-C3',4,'essay','teacher','⟨10/11⟩, ⟨7/11⟩, ⟨4/11⟩, ⟨3/11⟩, ⟨5/11⟩ 가운데 두 분수를 골라 몫이 가장 큰 나눗셈식을 만들고, 그렇게 고른 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u1-C3","difficulty":4,"kind":"essay","stem":"⟨10/11⟩, ⟨7/11⟩, ⟨4/11⟩, ⟨3/11⟩, ⟨5/11⟩ 가운데 두 분수를 골라 몫이 가장 큰 나눗셈식을 만들고, 그렇게 고른 까닭을 설명해 보세요.","answer_guide":{"answer":"예: ⟨10/11⟩ ÷ ⟨3/11⟩ = 10 ÷ 3 = ⟨10/3⟩ = ⟨3 1/3⟩. 분모가 같으면 몫은 분자끼리 나눈 값이고, 나누어지는 수는 클수록, 나누는 수는 작을수록 몫이 크므로 가장 큰 분수를 가장 작은 분수로 나눈다.","scoring_points":["⟨10/11⟩ ÷ ⟨3/11⟩을 만들었는가","⟨3 1/3⟩을 구했는가","가장 큰 수 ÷ 가장 작은 수인 까닭을 썼는가"]},"explanation":["가장 큰 분수 ⟨10/11⟩, 가장 작은 분수 ⟨3/11⟩이에요.","⟨10/11⟩ ÷ ⟨3/11⟩ = 10 ÷ 3 = ⟨3 1/3⟩.","나누어지는 수는 크게, 나누는 수는 작게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
